(51, 22, 23, 'Socio', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass Socio\r\n{\r\n   private int numero;\r\n   private int idade;\r\n   private String nome;\r\n   \r\n   public Socio(){\r\n       this.numero=0;\r\n       this.idade=0;\r\n       this.nome="";\r\n   }\r\n   \r\n   public Socio(int numero, int idade, String nome){\r\n       this.numero=numero;\r\n       this.idade=idade;\r\n       this.nome=nome;\r\n   }\r\n   \r\n   \r\n   public void setNumero(int numero){\r\n       this.numero=numero;\r\n   }\r\n   \r\n   public void setIdade(int idade){\r\n       this.idade=idade;\r\n   }\r\n   \r\n   public void setNome(String nome){\r\n       this.nome=nome;\r\n   }\r\n   \r\n   public int getNumero(){\r\n       return this.numero;\r\n   }\r\n   \r\n    public int getIdade(){\r\n       return this.idade;\r\n   }\r\n   \r\n   public String getNome(){\r\n       return this.nome;\r\n   }\r\n   \r\n   @Override\r\n   public String toString(){\r\n       return (String.valueOf(this.numero)).concat(", ").concat(String.valueOf(this.idade)).concat(", ").concat(this.nome);\r\n   }\r\n   \r\n   \r\n   \r\n}\r\n', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass Socio\r\n{\r\n   private int numero;\r\n   private int idade;\r\n   private String nome;\r\n   \r\n   public Socio(){\r\n       this.numero=0;\r\n       this.idade=0;\r\n       this.nome="";\r\n   }\r\n   \r\n   public Socio(int numero, int idade, String nome){\r\n       this.numero=numero;\r\n       this.idade=idade;\r\n       this.nome=nome;\r\n   }\r\n   \r\n   \r\n   public void setNumero(int numero){\r\n       this.numero=numero;\r\n   }\r\n   \r\n   public void setIdade(int idade){\r\n       this.idade=idade;\r\n   }\r\n   \r\n   public void setNome(String nome){\r\n       this.nome=nome;\r\n   }\r\n   \r\n   public int getNumero