(52, 22, 23, 'SocioAtleta', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass SocioAtleta extends Socio\r\n{\r\n   private String categoria;\r\n   \r\n   public SocioAtleta(){\r\n       super(0,0,"");\r\n       this.categoria="Mirim";\r\n   }\r\n   \r\n   public SocioAtleta(int numero, int idade, String nome){\r\n       super(numero,idade,nome);\r\n       \r\n       if(idade <= 10){\r\n           this.categoria="Mirim";\r\n       }else if(idade >= 11 && idade <= 15){\r\n           this.categoria="Infantil";\r\n       }else if(idade >= 16 && idade <= 20){\r\n           this.categoria="Juvenil";\r\n       }else if(idade >= 21 && idade <= 40){\r\n           this.categoria="Adulto";\r\n       }else {\r\n         this.categoria="Master"; \r\n       }\r\n   }//fim metodo\r\n   \r\n    @Override\r\n	public void setIdade(int idade) {\r\n	    super.setIdade(idade);\r\n	    \r\n		if(idade <= 10){\r\n           this.categoria="Mirim";\r\n       }else if(idade >= 11 && idade <= 15){\r\n           this.categoria="Infantil";\r\n       }else if(idade >= 16 && idade <= 20){\r\n           this.categoria="Juvenil";\r\n       }else if(idade >= 21 && idade <= 40){\r\n           this.categoria="Adulto";\r\n       }else {\r\n         this.categoria="Master"; \r\n       }\r\n	}\r\n	\r\n	 @Override\r\n     public String toString(){\r\n        return super.getNumero() + ", " +  super.getIdade() + ", " + super.getNome() + ", " +  this.categoria;\r\n     }\r\n}', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass SocioAtleta extends Socio\r\n{\r\n   private String categoria;\r\n   \r\n   public SocioAtleta(){\r\n       super(0,0,"");\r\n       this.categoria="Mirim";\r\n   }\r\n   \r\n   public SocioAtleta(int numero, int idade, String nome){\r\n       super(numero,idade,nome);\r\n       \r\n       if(idade <= 10){\r\n           this.categoria="Mirim";\r\n       }else if(idade >= 11 && idade <= 15){\r\n           this.categoria="Infantil";\r\n       }else if(idade >= 16 && idade <= 20){\r\n           this.categoria="Juvenil";\r\n       }else if(idade >= 21 && idade <= 40){\r\n           this.categoria="Adulto";\r\n       }else {\r\n         this.categoria="Master"; \r\n       }\r\n   }//fim metodo\r\n   \r\n    @Override\r\n	public void setIdade(int idade) {\r\n	    super.setIdade(idade);\r\n	    \r\n		if(idade <= 10){\r\n           this.categoria="Mirim"\r\n       }else if(idade >= 11 && idade <= 15){\r\n           this.categoria="Infantil"\r\n       }else if(idade >= 16 && idade <= 20){\r\n           this.categoria="Juvenil"\r\n       }else if(idade >= 21 && idade <= 40){\r\n           this.categoria="Adulto"\r\n       }else {\r\n         this.categoria="Master"  \r\n       }\r\n	}\r\n	\r\n	 @Override\r\n     public String toString(){\r\n        return super.getNumero() + ", " +  super.getIdade() + ", " + super.getNome() + ", " +  this.categoria;\r\n     }\r\n}', '2015-05-23 18:40:08', 0),
(53, 21, 13, 'Ponto', 'public class Ponto {\r\n\r\n    private int x;\r\n    private int y;\r\n    \r\n    public Ponto()\r\n    {\r\n        this.x = 0;\r\n        this.y = 0;\r\n    }\r\n    \r\n    public Ponto(int x, int y) {\r\n        this.x = x;\r\n        this.y = y;\r\n    }\r\n\r\n    public int getX() {\r\n        return x;\r\n    }\r\n\r\n    public void setX(int x) {\r\n        this.x = x;\r\n    }\r\n\r\n    public int getY() {\r\n        return y;\r\n    }\r\n\r\n    public void setY(int y) {\r\n        this.y = y;\r\n    }\r\n\r\n    @Override\r\n    public String toString() {\r\n        return "(" + x + ", " + y + '')'';\r\n    }\r\n}\r\n', NULL, '2015-05-23 19:08:29', 0),
(54, 22, 14, 'Socio', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass Socio {\r\n	\r\n	private String nome;\r\n	private int idade;\r\n	private int numero;\r\n	\r\n	public Socio() {\r\n		this.numero = 0;		\r\n		this.idade = 0;\r\n		this.nome = "";\r\n	}\r\n	\r\n	public Socio(int numero, int idade, String nome){\r\n		this.numero = numero;\r\n		this.idade = idade;\r\n		this.nome = nome;\r\n	}\r\n\r\n	public String getNome() {\r\n		return nome;\r\n	}\r\n\r\n	public void setNome(String nome) {\r\n		this.nome = nome;\r\n	}\r\n\r\n	public int getIdade() {\r\n		return idade;\r\n	}\r\n\r\n	public void setIdade(int idade) {\r\n		this.idade = idade;\r\n	}\r\n\r\n	public int getNumero() {\r\n		return numero;\r\n	}\r\n\r\n	public void setNumero(int numero) {\r\n		this.numero = numero;\r\n	}\r\n	\r\n	public String toString(){\r\n		return this.numero + ", " + this.idade + ", " + this.nome;\r\n	}\r\n\r\n}', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass Socio {\r\n	\r\n	private String nome;\r\n	private int idade;\r\n	private int numero;\r\n	\r\n	public Socio() {\r\n		this.numero = 0;		\r\n		this.idade = 0;\r\n		this.nome = null;\r\n	}\r\n	\r\n	public Socio(int numero, int idade, String nome){\r\n		this.numero = numero;\r\n		this.idade = idade;\r\n		this.nome = nome;\r\n	}\r\n\r\n	public String getNome() {\r\n		return nome;\r\n	}\r\n\r\n	public void setNome(String nome) {\r\n		this.nome = nome;\r\n	}\r\n\r\n	public int getIdade() {\r\n		return idade;\r\n	}\r\n\r\n	public void setIdade(int idade) {\r\n		this.idade = idade;\r\n	}\r\n\r\n	public int getNumero() {\r\n		return numero;\r\n	}\r\n\r\n	public void setNumero(int numero) {\r\n		this.numero = numero;\r\n	}\r\n	\r\n	public String toString(){\r\n		return this.numero + ", " + this.idade + ", " + this.nome;\r\n	}\r\n\r\n}', '2015-05-24 03:20:57', 0),
(55, 22, 14, 'SocioAtleta', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass SocioAtleta extends Socio {\r\n    \r\n    private String categoria;\r\n	\r\n	public SocioAtleta(){\r\n		super();\r\n		this.categoria = "Mirim";\r\n	}\r\n	\r\n	public SocioAtleta(int numero, int idade, String nome){\r\n		super(numero, idade, nome);\r\n		if(super.getIdade() <=10){\r\n			this.categoria = "Mirim";\r\n		} else if(super.getIdade()>= 11 && super.getIdade() <=15){\r\n			this.categoria = "Infantil";\r\n		} else if(super.getIdade()>=16 && super.getIdade()<=20){\r\n			this.categoria = "Juvenil";\r\n		} else if(super.getIdade()>=21 && super.getIdade()<=40){\r\n			this.categoria = "Adulto";\r\n		} else {\r\n			this.categoria = "Master";\r\n		}\r\n	}\r\n	\r\n	public void setIdade(int idade){\r\n		super.setIdade(idade);\r\n		if(super.getIdade() <=10){\r\n			this.categoria = "Mirim";\r\n		} else if(super.getIdade()>= 11 && super.getIdade() <=15){\r\n			this.categoria = "Infantil";\r\n		} else if(super.getIdade()>=16 && super.getIdade()<=20){\r\n			this.categoria = "Juvenil";\r\n		} else if(super.getIdade()>=21 && super.getIdade()<=40){\r\n			this.categoria = "Adulto";\r\n		} else {\r\n			this.categoria = "Master";\r\n		}\r\n	}\r\n	\r\n	public String toString(){\r\n		return super.toString() + ", " + this.categoria;\r\n	}\r\n	\r\n\r\n    \r\n}', NULL, '2015-05-24 03:18:13', 0),
(56, 22, 20, 'Socio', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\npublic class Socio {\r\n   protected int numero, idade;\r\n   protected String nome;\r\n   \r\n   public Socio ( ) {\r\n       numero = idade = 0;\r\n       nome = "";\r\n   }\r\n   \r\n   public Socio (int numero, int idade, String nome) {\r\n       this.numero = numero;\r\n       this.idade = idade;\r\n       this.nome = nome;\r\n   }\r\n   \r\n   public void setNumero (int numero) {\r\n       this.numero = numero;\r\n   }\r\n   \r\n   public void setIdade (int idade) {\r\n       this.idade = idade; \r\n   }\r\n   \r\n   public void setNome (String nome) {\r\n       this.nome = nome;\r\n   }\r\n   \r\n   public int getNumero ( ) {\r\n       return numero;\r\n   }\r\n   \r\n   public int getIdade ( ) {\r\n       return idade;\r\n   }\r\n   \r\n   public String getNome ( ) {\r\n       return nome;\r\n   }\r\n   \r\n   public String toString ( ) {\r\n       return numero + ", " + idade + ", " + nome;\r\n   }\r\n}', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\npublic class Socio {\r\n   protected int numero, idade;\r\n   protected String nome;\r\n   \r\n   public Socio ( ) {\r\n       numero = idade = 0;\r\n       nome = "";\r\n   }\r\n   \r\n   public Socio (int numero, int idade, String nome) {\r\n       this.numero = numero;\r\n       this.idade = idade;\r\n       this.nome = nome;\r\n   }\r\n   \r\n   public void setNumero (int numero) {\r\n       this.numero = numero;\r\n   }\r\n   \r\n   public void setIdade (int idade) {\r\n       this.idade = idade; \r\n   }\r\n   \r\n   public void setNome (String nome) {\r\n       this.nome = nome;\r\n   }\r\n   \r\n   public int getNumero ( ) {\r\n       return numero;\r\n   }\r\n   \r\n   public int getIdade ( ) {\r\n       return idade;\r\n   }\r\n   \r\n   public int getNome ( ) {\r\n       return nome;\r\n   }\r\n   \r\n   public String toString ( ) {\r\n       return numero + ", " + idade + ", " + nome;\r\n   }\r\n}', '2015-05-24 20:46:41', 0),
(57, 22, 20, 'SocioAtleta', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\npublic class SocioAtleta extends Socio {\r\n    private String categoria;\r\n    \r\n    public SocioAtleta ( ) {\r\n        super ( );\r\n        categoria = "Mirim";\r\n    }\r\n\r\n    public SocioAtleta (int numero, int idade, String nome) {\r\n        super (numero, idade, nome);\r\n        verificaCategoria ( );\r\n    }\r\n    \r\n    public void setIdade (int idade) {\r\n        this.idade = idade;\r\n        verificaCategoria ( );\r\n    }\r\n    \r\n    public void verificaCategoria ( ) {\r\n        if (idade <= 10)\r\n            categoria = "Mirim";\r\n    \r\n        else if (idade >= 11 && idade <= 15)\r\n            categoria = "Infantil";\r\n    \r\n        else if (idade >= 16 && idade <= 20)\r\n            categoria = "Juvenil";\r\n        \r\n        else if (idade >= 21 && idade <= 40)\r\n            categoria = "Adulto";\r\n    \r\n        else\r\n            categoria = "Master";\r\n    }\r\n    \r\n    public String toString ( ) {\r\n        return super.toString ( ) + ", " + categoria;\r\n    }\r\n}\r\n\r\n', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\npublic class SocioAtleta extends Socio {\r\n    private String categoria;\r\n    \r\n    public SocioAtleta ( ) {\r\n        super ( );\r\n        categoria = "Mirim";\r\n    }\r\n\r\n    public SocioAtleta (int numero, int idade, String nome) {\r\n        super (numero, idade, nome);\r\n        verificaCategoria ( );\r\n    }\r\n    \r\n    public void setIdade (int idade) {\r\n        this.idade = idade;\r\n        verificaCategoria ( );\r\n    }\r\n    \r\n    public void verificaCategoria ( ) {\r\n        if (idade <= 10)\r\n            categoria = "Mirim";\r\n    \r\n        else if (idade >= 11 && idade <= 15)\r\n            categoria = "Infantil";\r\n    \r\n        else if (idade >= 16 && idade <= 20)\r\n            categoria = "Juvenil";\r\n        \r\n        else if (idade >= 21 && idade <= 40)\r\n            categoria = "Adulto"\r\n    \r\n        else\r\n            categoria = "Master";\r\n    }\r\n    \r\n    public String toString ( ) {\r\n        return super.toString ( ) + ", " + categoria;\r\n    }\r\n}\r\n\r\n', '2015-05-25 16:49:00', 0),
(58, 21, 22, 'Ponto', 'public class Ponto {\r\n\r\n    private int x;\r\n    private int y;\r\n    \r\n    public Ponto()\r\n    {\r\n        this.x = 0;\r\n        this.y = 0;\r\n    }\r\n    \r\n    public Ponto(int x, int y) {\r\n        this.x = x;\r\n        this.y = y;\r\n    }\r\n\r\n    public int getX() {\r\n        return x;\r\n    }\r\n\r\n    public void setX(int x) {\r\n        this.x = x;\r\n    }\r\n\r\n    public int getY() {\r\n        return y;\r\n    }\r\n\r\n    public void setY(int y) {\r\n        this.y = y;\r\n    }\r\n\r\n    @Override\r\n    public String toString() {\r\n        return "(" + x + ", " + y + '')'';\r\n    }\r\n}\r\n', NULL, '2015-05-25 02:34:20', 0),
(59, 21, 22, 'ArrayDePontos', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass ArrayDePontos\r\n{\r\n   private Ponto[] pontos;\r\n   private int tamanho;\r\n   \r\n   public ArrayDePontos(int a)\r\n   {\r\n       pontos = new Ponto[a];\r\n   }\r\n   \r\n   public int getTamanho(){\r\n       return tamanho;\r\n   }\r\n   \r\n   public void inserirPonto(Ponto a){\r\n       for(int i=0;i<pontos.length;i++)\r\n       {\r\n           if(pontos[i]==null)\r\n           {\r\n               pontos[i]=a;\r\n               tamanho++;\r\n               break;\r\n           }\r\n       }\r\n   }\r\n   \r\n   public Ponto obtemPontoSuperior(){\r\n       Ponto a = pontos[0];\r\n       \r\n       for(int i =1; i< pontos.length; i++){\r\n           if(pontos[i]==null){\r\n               break;\r\n           }\r\n           if(pontos[i].getY()>a.getY()){\r\n               a=pontos[i];\r\n           }\r\n       }\r\n       return a;\r\n   }\r\n   \r\n   public Ponto obtemPontoInferior(){\r\n       Ponto a = pontos[0];\r\n       \r\n       for(int i =1; i< pontos.length; i++){\r\n           if(pontos[i]==null){\r\n               break;\r\n           }\r\n           if(pontos[i].getY()<a.getY()){\r\n               a=pontos[i];\r\n           }\r\n       }\r\n       return a;\r\n   }\r\n   \r\n   public Ponto obtemPontoMaisADireita(){\r\n       Ponto a = pontos[0];\r\n       \r\n       for(int i =1; i< pontos.length; i++){\r\n           if(pontos[i]==null){\r\n               break;\r\n           }\r\n           if(pontos[i].getX()>a.getX()){\r\n               a=pontos[i];\r\n           }\r\n       }\r\n       return a;\r\n   }\r\n   \r\n   public Ponto obtemPontoMaisAEsquerda(){\r\n       Ponto a = pontos[0];\r\n       \r\n       for(int i =1; i< pontos.length; i++){\r\n           if(pontos[i]==null){\r\n               break;\r\n           }\r\n           if(pontos[i].getX()<a.getX()){\r\n         