(63, 20, 19, 'Ponto', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\npublic class Ponto {\r\n	\r\n	private int x;\r\n	private int y;\r\n	\r\n	public Ponto() {\r\n	}\r\n\r\n	public Ponto(int x, int y) {\r\n		this.x = x;\r\n		this.y = y;\r\n	}\r\n\r\n	public void setX(int x) {\r\n		this.x = x;\r\n	}\r\n	\r\n	public void setY(int y) {\r\n		this.y = y;\r\n	}\r\n	\r\n	public int getX() {\r\n		return x;\r\n	}\r\n\r\n	public int getY() {\r\n		return y;\r\n	}\r\n\r\n	@Override\r\n	public String toString() {\r\n		return ( "("+ getX() + ", " + getY() + ")" );\r\n	}\r\n\r\n}', NULL, '2015-05-29 01:52:59', 0),
(64, 20, 19, 'Reta', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\npublic class Reta {\r\n\r\n	private Ponto p;\r\n	private Ponto q;\r\n	\r\n	public Reta() {\r\n\r\n	}\r\n\r\n	public Reta(Ponto p, Ponto q) {\r\n		this.p = p;\r\n		this.q = q;\r\n	}\r\n\r\n	public void setP(Ponto p) {\r\n		this.p = p;\r\n	}\r\n	\r\n	public void setQ(Ponto q) {\r\n		this.q = q;\r\n	}\r\n\r\n	public Ponto getP() {\r\n		return p;\r\n	}\r\n	\r\n	public Ponto getQ() {\r\n		return q;\r\n	}\r\n\r\n	public double getDistancia() {\r\n		\r\n		return Math.sqrt( ( Math.pow( ( getQ().getX() - getP().getX() ), 2) +  Math.pow( ( getQ().getY() - getP().getY() ), 2) ) );\r\n		\r\n	}\r\n	\r\n}', NULL, '2015-05-29 01:53:49', 0),
