(139, 24, 30, 'NumerosPares', '\r\n/**\r\n * Escreva a descrição da classe NumerosPares aqui.\r\n * \r\n * @author (seu nome) \r\n * @version (número de versão ou data)\r\n */\r\npublic class NumerosPares{\r\n    private int n;\r\n    \r\n    public NumerosPares (){\r\n    }\r\n    \r\n    public NumerosPares (int n){\r\n        this.n = n;\r\n    }\r\n    \r\n    public void setN(int n1){\r\n        this.n = n1;\r\n    } \r\n    \r\n    public int getN (){\r\n        return this.n;\r\n    }\r\n    \r\n    public String geraPares (){\r\n    String par = "";\r\n    int cont = 2;\r\n    while(cont <= n ){\r\n    if( cont != n && cont != n-1){\r\n        par = par+cont+", ";\r\n    } else par = par+cont;\r\n    cont += 2;\r\n    }\r\n    return par;\r\n    }\r\n    \r\n    public int somaNumeros(){\r\n    int Soma = 0;\r\n    int cont = 0;\r\n        while(cont <= n){\r\n        if(cont > 0 )\r\n        Soma +=cont;\r\n        cont++;\r\n    }\r\n    return Soma;\r\n}\r\n        \r\n    \r\n\r\n}\r\n', '\r\n/**\r\n * Escreva a descrição da classe NumerosPares aqui.\r\n * \r\n * @author (seu nome) \r\n * @version (número de versão ou data)\r\n */\r\npublic class NumerosPares{\r\n    private int n;\r\n    \r\n    public NumerosPares (){\r\n    }\r\n    \r\n    public NumerosPares (int n){\r\n        this.n = n;\r\n    }\r\n    \r\n    public void setN(int n1){\r\n        this.n = n1;\r\n    } \r\n    \r\n    public int getN (){\r\n        return this.n;\r\n    }\r\n    \r\n    public String geraPares (){\r\n    String par = "";\r\n    int cont = 2;\r\n    while(cont <= n ){\r\n    if( cont != n && cont != n-1){\r\n        par = par+cont+", ";\r\n    } else par = par+cont+".";\r\n    cont += 2;\r\n    }\r\n    return par;\r\n    }\r\n    \r\n    public int somaNumeros(){\r\n    int Soma = 0;\r\n    int cont = 0;\r\n        while(cont <= n){\r\n        if(cont > 0 )\r\n        Soma +=cont;\r\n        cont++;\r\n    }\r\n    return Soma;\r\n}\r\n        \r\n    \r\n\r\n}\r\n', '2016-05-11 20:42:28', 0),
(140, 20, 35, 'Ponto', 'public class Ponto {\r\n    private int x,y;\r\n    \r\n    public Ponto() {\r\n        this.x = 0;\r\n        this.y = 0;\r\n    }\r\n    \r\n    public Ponto(int x, int y) {\r\n        this.x = x;\r\n        this.y = y;\r\n    }\r\n    \r\n    public void setX (int x){\r\n        this.x = x;\r\n    }\r\n    \r\n    public void setY (int y){\r\n        this.y = y;\r\n    }\r\n    \r\n    public int getX (){\r\n        return x;\r\n    }\r\n    \r\n    public int getY (){\r\n        return y;\r\n    }\r\n    \r\n    public String toString() {\r\n        String resultado = "("+x+", "+y+")";\r\n        return resultado;\r\n    }\r\n\r\n\r\n}\r\n', 'public class Ponto {\r\n    private int x,y;\r\n    \r\n    public Ponto() {\r\n        this.x = 0;\r\n        this.y = 0;\r\n    }\r\n    \r\n    public Ponto(int x, int y) {\r\n        this.x = x;\r\n        this.y = y;\r\n    }\r\n    \r\n    public void setX (int x){\r\n        this.x = x;\r\n    }\r\n    \r\n    public void setY (int y){\r\n        this.y = y;\r\n    }\r\n    \r\n    public int getX (){\r\n        return x;\r\n    }\r\n    \r\n    public int getY (){\r\n        return y;\r\n    }\r\n    \r\n    public String toString() {\r\n        String resultado = "("+x+","+y+")";\r\n        return resultado;\r\n    }\r\n\r\n\r\n}\r\n', '2016-05-13 00:56:45', 0),
