(144, 26, 9, 'Tabuada', '\r\n/**\r\n * Escreva a descrição da classe Tabuada aqui.\r\n * \r\n * @author (seu nome) \r\n * @version (número de versão ou data)\r\n */\r\npublic class Tabuada\r\n{\r\n    // variáveis de instância - substitua o exemplo abaixo pelo seu próprio\r\n    private int numero;\r\n\r\n    /**\r\n     * COnstrutor para objetos da classe Tabuada\r\n     */\r\n    public Tabuada()\r\n    {\r\n        // inicializa variáveis de instância\r\n        numero = 0;\r\n    }\r\n    \r\n    public Tabuada(int numero)\r\n    {\r\n        // inicializa variáveis de instância\r\n        this.numero = numero;\r\n    }\r\n    \r\n    public void setNumero (int numero){\r\n         this.numero = numero;\r\n    }\r\n    \r\n    public int getNumero (){\r\n        return numero;\r\n    }\r\n\r\n    public String calculaTabuada (){\r\n        String ret = "";\r\n        for (int i=1; i<=10; i++) {\r\n            ret += numero + " x " + i + " = "+(numero*i)+"\\n";\r\n        }\r\n        return ret;\r\n    }\r\n}\r\n', NULL, '2016-05-12 01:12:31', 0),
(145, 26, 9, 'Teclado', ' \r\n\r\nimport java.io.*;\r\n\r\n/** Classe que permite fazer leitura de dados do tecladeo */\r\n\r\npublic class Teclado\r\n{\r\n     private String s;\r\n     private InputStreamReader i = new InputStreamReader (System.in);\r\n     private BufferedReader d = new BufferedReader(i);\r\n\r\n     /**\r\n        Le um inteiro.\r\n        @return int\r\n     */\r\n     public int leInt ()\r\n     {   System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         int a = 0;\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser inteiro: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um inteiro, com mensagem.\r\n        @return int\r\n     */\r\n     public int leInt (String msg)\r\n     { \r\n         int a = 0;\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: "+e );\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser inteiro: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um double.\r\n        @return double\r\n     */\r\n     public double leDouble()\r\n     { \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         double a = 0;\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Double.parseDouble(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser numero: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um double, com mensagem.\r\n        @return double\r\n     */\r\n     public double leDouble(String msg)\r\n     {   double a = 0;\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Double.parseDouble(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser numero: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um string.\r\n        @return String\r\n     */\r\n     public String leString()\r\n     { \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         s = "";\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            \r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (s);\r\n     }\r\n\r\n     /**\r\n        Le um string. com mensagem.\r\n        @return String\r\n     */\r\n     public String leString(String msg)\r\n     {   s = "";\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n            s = d.readLine();\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (s);\r\n     }\r\n        \r\n    /**\r\n        Le um char.\r\n        @return char\r\n     */\r\n     public char leChar()\r\n     {  \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         s = "";\r\n         char c='' '';\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            c = s.charAt(0);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (c);\r\n     }\r\n          \r\n     /**\r\n        Le um char com mensagem.\r\n        @return char\r\n     */\r\n     public char leChar(String msg)\r\n     {   s = "";\r\n         char c='' '';\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            c = s.charAt(0);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (c);\r\n     }\r\n     \r\n     \r\n    \r\n    }\r\n\r\n\r\n', NULL, '2016-05-12 01:12:40', 0),
(146, 26, 9, 'TestaTabuada', '\r\npublic class TestaTabuada\r\n{\r\n    public static void main (String args[]){\r\n        Teclado teclado = new Teclado();\r\n        int num = teclado.leInt("Digite um numero ou -1 para sair:");\r\n        while (num != -1){\r\n            Tabuada t = new Tabuada (num);\r\n            System.out.println (t.calculaTabuada());\r\n            num = teclado.leInt("Digite um numero ou -1 para sair:");\r\n            \r\n        }\r\n    }\r\n}\r\n', '\r\npublic class TestaTabuada\r\n{\r\n    public static void main (String args[]){\r\n        Teclado teclado = new Teclado();\r\n        int num = teclado.leInt("Digite um número ou -1 para sair:");\r\n        while (num != -1){\r\n            Tabuada t = new Tabuada (num);\r\n            System.out.println (t.calculaTabuada());\r\n            num = teclado.leInt("Digite um número ou -1 para sair:");\r\n            \r\n        }\r\n    }\r\n}\r\n', '2016-05-12 01:58:00', 0),
(147, 20, 39, 'Ponto', '\r\n/**\r\n * Write a description of class Ponto here.\r\n * \r\n * @author Joice Cazanoski Gomes \r\n * @version 06/05/2016\r\n */\r\npublic class Ponto {\r\n    private int x, y;\r\n    \r\n    public Ponto(){\r\n        x = 0;\r\n        y = 0;\r\n    }\r\n    \r\n    public Ponto(int x, int y){\r\n        this.x = x;\r\n        this.y = y;\r\n    }\r\n    \r\n    public void setX(int x){\r\n        this.x = x;\r\n    }\r\n    \r\n    public void setY(int y){\r\n        this.y = y;\r\n    }\r\n    \r\n    public int getX(){\r\n        return x;\r\n    }\r\n    \r\n    public int getY(){\r\n        return y;\r\n    }\r\n    \r\n    public String toString(){\r\n        String s = "";\r\n        s = "("+x+", "+y+")";\r\n        return s;\r\n    }\r\n}\r\n   ', NULL, '2016-05-12 02:20:36', 0),
(148, 20, 39, 'Reta', '\r\n/**\r\n * Write a description of class Reta here.\r\n * \r\n * @author (your name) \r\n * @version (a version number or a date)\r\n */\r\npublic class Reta{\r\n    private Ponto ponto1= new Ponto();\r\n    private Ponto ponto2= new Ponto();\r\n    \r\n    public Reta(){\r\n      \r\n    }\r\n    \r\n    public Reta(Ponto ponto1, Ponto ponto2){\r\n        this.ponto1 = ponto1;\r\n        this.ponto2 = ponto2;\r\n    }\r\n    \r\n    public void setPonto1(Ponto ponto1){\r\n        this.ponto1 = ponto1;\r\n    }\r\n    \r\n    public void setPonto2(Ponto ponto2){\r\n        this.ponto2 = ponto2;\r\n    }\r\n    \r\n    public Ponto getPonto1(){\r\n        return ponto1;\r\n    }\r\n    \r\n    public Ponto getPonto2(){\r\n        return ponto2;\r\n    }\r\n    \r\n    public double getDistancia(){\r\n        double d = Math.sqrt(Math.pow((ponto2.getX()-ponto1.getX()),2)+ Math.pow((ponto2.getY()-ponto1.getY()), 2));\r\n        return d;\r\n    }\r\n    \r\n    public String toString(){\r\n        String s = "Ponto 1: "+ ponto1.toString() + "\\nPonto 2: "+ponto2.toString() + "\\nDistância: " +getDistancia();\r\n        System.out.println(s);\r\n        return s;\r\n    }\r\n\r\n}\r\n', NULL, '2016-05-12 02:20:59', 0),
(150, 24, 40, 'NumerosPares', 'public class NumerosPares{\r\n    private int n;\r\n    \r\n    public NumerosPares(){\r\n        \r\n    }\r\n    public NumerosPares(int n){\r\n        this.n = n;\r\n    }\r\n    \r\n    public void setN(int n){\r\n        this.n = n;\r\n    }\r\n    \r\n    public int getN(){\r\n        return n;\r\n    }\r\n    \r\n    public String geraPares(){\r\n        int i = 1;\r\n        String pares = "";\r\n        while(i <= n){\r\n            if(i%2 == 0){\r\n                if(i==2){\r\n                    pares = pares + i;\r\n                }\r\n                else{\r\n                    pares = pares + ", " + i;\r\n                }\r\n            }\r\n            i++;\r\n        }\r\n        return pares;\r\n    }\r\n    \r\n    public int somaNumeros(){\r\n        int i = 1;\r\n        int soma = 0;\r\n        while(i <= n){\r\n            soma = soma + i;\r\n            i++;\r\n        }\r\n        return soma;\r\n    }\r\n}', NULL, '2016-05-12 17:42:01', 0),
(151, 20, 40, 'Ponto', 'public class Ponto{\r\n    private int x, y;\r\n    \r\n    public Ponto(){\r\n        \r\n    }\r\n    public Ponto(int x, int y){\r\n        this.x = x;\r\n        this.y = y;\r\n    }\r\n    \r\n    public void setX(int x){\r\n        this.x = x;\r\n    }\r\n    public void setY(int y){\r\n        this.y = y;\r\n    }\r\n    \r\n    public int getX(){\r\n        return x;\r\n    }\r\n    public int getY(){\r\n        return y;\r\n    }\r\n    \r\n    public String toString(){\r\n        String str = "";\r\n        str = "(" + x + ", " + y + ")";\r\n        return str;\r\n    }\r\n}', NULL, '2016-05-12 17:43:40', 0);
