(154, 20, 40, 'Teclado', ' \r\n\r\nimport java.io.*;\r\n\r\n/** Classe que permite fazer leitura de dados do tecladeo */\r\n\r\npublic class Teclado\r\n{\r\n     private String s;\r\n     private InputStreamReader i = new InputStreamReader (System.in);\r\n     private BufferedReader d = new BufferedReader(i);\r\n\r\n     /**\r\n        Le um inteiro.\r\n        @return int\r\n     */\r\n     public int leInt ()\r\n     {   System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         int a = 0;\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser inteiro: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um inteiro, com mensagem.\r\n        @return int\r\n     */\r\n     public int leInt (String msg)\r\n     { \r\n         int a = 0;\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: "+e );\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser inteiro: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um double.\r\n        @return double\r\n     */\r\n     public double leDouble()\r\n     { \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         double a = 0;\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Double.parseDouble(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser numero: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um double, com mensagem.\r\n        @return double\r\n     */\r\n     public double leDouble(String msg)\r\n     {   double a = 0;\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Double.parseDouble(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser numero: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um string.\r\n        @return String\r\n     */\r\n     public String leString()\r\n     { \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         s = "";\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            \r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (s);\r\n     }\r\n\r\n     /**\r\n        Le um string. com mensagem.\r\n        @return String\r\n     */\r\n     public String leString(String msg)\r\n     {   s = "";\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n            s = d.readLine();\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (s);\r\n     }\r\n        \r\n    /**\r\n        Le um char.\r\n        @return char\r\n     */\r\n     public char leChar()\r\n     {  \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         s = "";\r\n         char c='' '';\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            c = s.charAt(0);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (c);\r\n     }\r\n          \r\n     /**\r\n        Le um char com mensagem.\r\n        @return char\r\n     */\r\n     public char leChar(String msg)\r\n     {   s = "";\r\n         char c='' '';\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            c = s.charAt(0);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (c);\r\n     }\r\n     \r\n     \r\n    \r\n    }\r\n\r\n', NULL, '2016-05-12 17:44:32', 0),
(155, 24, 35, 'NumerosPares', 'public class NumerosPares {\r\n    private int n;\r\n    \r\n    public NumerosPares (){\r\n        this.n = 0;\r\n    }\r\n    \r\n    public NumerosPares (int n){\r\n        this.n = n;\r\n    }\r\n    \r\n    public void setN (int n){\r\n        this.n = n;\r\n    }\r\n    \r\n    public int getN (){\r\n        return n;\r\n    }\r\n    \r\n    public String geraPares (){\r\n        int i = 2;\r\n        String valor = "";\r\n        \r\n        while ( i <= n && n >= 0){\r\n            if (n % 2 == 0 && i < n){\r\n                valor = valor + i +", ";\r\n            }\r\n            else if (n % 2 == 0 && i == n){\r\n                valor = valor + i;\r\n            }\r\n            else if (n % 2 != 0 && i < n - 2){\r\n                valor = valor + i + ",";\r\n            }\r\n            else\r\n            valor = valor + i;\r\n           \r\n            i=i+2;\r\n        }\r\n        return valor;\r\n    }\r\n   \r\n    public int somaNumeros (){\r\n            int i = 1;\r\n        int valor = 0;\r\n        \r\n        while ( i <= n && n >= 0){\r\n            if (n % 2 == 0 && i < n){\r\n                valor = valor + i;\r\n            }\r\n            else if (n % 2 == 0 && i == n){\r\n                valor = valor + i;\r\n            }\r\n            else if (n % 2 != 0 && i < n - 2){\r\n                valor = valor + i;\r\n            }\r\n            else\r\n            valor = valor + i;\r\n           \r\n            i++;\r\n        }\r\n        return valor;\r\n    }\r\n}\r\n                \r\n            \r\n            \r\n            ', 'public class NumerosPares {\r\n    private int n;\r\n    \r\n    public NumerosPares (){\r\n        this.n = 0;\r\n    }\r\n    \r\n    public NumerosPares (int n){\r\n        this.n = n;\r\n    }\r\n    \r\n    public void setN (int n){\r\n        this.n = n;\r\n    }\r\n    \r\n    public int getN (){\r\n        return n;\r\n    }\r\n    \r\n    public String geraPares (){\r\n        int i = 2;\r\n        String valor = "";\r\n        \r\n        while ( i <= n && n >= 0){\r\n            if (n % 2 == 0 && i < n){\r\n                valor = valor + i +", ";\r\n            }\r\n            else if (n % 2 == 0 && i == n){\r\n                valor = valor + i;\r\n            }\r\n            else if (n % 2 != 0 && i < n - 2){\r\n                valor = valor + i + ",";\r\n            }\r\n            else\r\n            valor = valor + i;\r\n           \r\n            i=i+2;\r\n        }\r\n        return valor;\r\n    }\r\n   \r\n    public int somaNumeros (){\r\n            int i = 2;\r\n        int valor = 0;\r\n        \r\n        while ( i <= n && n >= 0){\r\n            if (n % 2 == 0 && i < n){\r\n                valor = valor + i;\r\n            }\r\n            else if (n % 2 == 0 && i == n){\r\n                valor = valor + i;\r\n            }\r\n            else if (n % 2 != 0 && i < n - 2){\r\n                valor = valor + i;\r\n            }\r\n            else\r\n            valor = valor + i;\r\n           \r\n            i=i+2;\r\n        }\r\n        return valor;\r\n    }\r\n}\r\n                \r\n            \r\n            \r\n            ', '2016-05-13 01:01:42', 0),
(156, 24, 39, 'NumerosPares', '\r\n/**\r\n * @author Joice Cazanoski Gomes\r\n * @version 10/05/2016\r\n */\r\npublic class NumerosPares {\r\n    private int n;\r\n    \r\n    public NumerosPares(){\r\n        n = 0;\r\n    }\r\n    \r\n    public NumerosPares(int n){\r\n        this.n = n;\r\n    }\r\n    \r\n    public void setN(int n){\r\n        this.n = n;\r\n    }\r\n\r\n    public int getN(){\r\n        return n;\r\n    }\r\n    \r\n    public String geraPares(){\r\n        int i = 2;\r\n        String s = i + "";\r\n        while(i > 0 && i < n){\r\n            i += 2;\r\n            s+= ", " + i;            \r\n     }\r\n     return s;\r\n    }\r\n\r\n    public int somaNumeros(){\r\n        int soma = 1;\r\n        int i = 1;\r\n        while (i > 0 && i < n){\r\n            i++;\r\n            soma+=i;\r\n        }       \r\n        return soma;\r\n    }\r\n}', NULL, '2016-05-13 15:20:42', 0),
(158, 20, 49, 'Ponto', 'public class Ponto {\r\n    private int x, y;\r\n    \r\n    public Ponto () {\r\n        this.x = 0;\r\n        this.y = 0;\r\n    }\r\n    \r\n    public Ponto (int x, int y) {\r\n        this.x = x;\r\n        this.y = y;\r\n    }\r\n    \r\n    public void setX (int x) {\r\n        this.x = x;\r\n    }\r\n    \r\n    public int getX () {\r\n        return x;\r\n    }\r\n    \r\n    public void setY (int y) {\r\n        this.y = y;\r\n    }\r\n    \r\n    public int getY () {\r\n        return y;\r\n    }\r\n    \r\n    public String toString () {\r\n        String str = "";\r\n        str = "("+x+", "+y+")";\r\n        return str;\r\n    }\r\n}', NULL, '2016-05-13 16:14:47', 0),
(159, 20, 49, 'Teclado', ' \r\n\r\nimport java.io.*;\r\n\r\n/** Classe que permite fazer leitura de dados do tecladeo */\r\n\r\npublic class Teclado\r\n{\r\n     private String s;\r\n     private InputStreamReader i = new InputStreamReader (System.in);\r\n     private BufferedReader d = new BufferedReader(i);\r\n\r\n     /**\r\n        Le um inteiro.\r\n        @return int\r\n     */\r\n     public int leInt ()\r\n     {   System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         int a = 0;\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser inteiro: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um inteiro, com mensagem.\r\n        @return int\r\n     */\r\n     public int leInt (String msg)\r\n     { \r\n         int a = 0;\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: "+e );\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser inteiro: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um double.\r\n        @return double\r\n     */\r\n     public double leDouble()\r\n     { \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         double a = 0;\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Double.parseDouble(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser numero: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um double, com mensagem.\r\n        @return double\r\n     */\r\n     public double leDouble(String msg)\r\n     {   double a = 0;\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Double.parseDouble(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser numero: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um string.\r\n        @return String\r\n     */\r\n     public String leString()\r\n     { \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         s = "";\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            \r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (s);\r\n     }\r\n\r\n     /**\r\n        Le um string. com mensagem.\r\n        @return String\r\n     */\r\n     public String leString(String msg)\r\n     {   s = "";\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n            s = d.readLine();\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (s);\r\n     }\r\n        \r\n    /**\r\n        Le um char.\r\n        @return char\r\n     */\r\n     public char leChar()\r\n     {  \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         s = "";\r\n         char c='' '';\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            c = s.charAt(0);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (c);\r\n     }\r\n          \r\n     /**\r\n        Le um char com mensagem.\r\n        @return char\r\n     */\r\n     public char leChar(String msg)\r\n     {   s = "";\r\n         char c='' '';\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            c = s.charAt(0);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (c);\r\n     }\r\n     \r\n     \r\n    \r\n    }\r\n\r\n', NULL, '2016-05-13 16:14:57', 0),
(160, 20, 49, 'TestaReta', 'public class TestaReta {\r\n    public static void main (String args[]) {\r\n        Teclado t = new Teclado();\r\n        int x1 = 0, y1 = 0, x2 = 0, y2 = 0;\r\n        Ponto p1, p2;\r\n        Reta r;\r\n        char c = '' '';           \r\n        while (c!=''S'' && c!=''s'') {\r\n            x1 = t.leInt("Digite a coordenada X do primeiro ponto da reta");\r\n            y1 = t.leInt("Digite a coordenada Y do primeiro ponto da reta");\r\n            x2 = t.leInt("Digite a coordenada X do segundo ponto da reta");\r\n            y2 = t.leInt("Digite a coordenada Y do segundo ponto da reta");\r\n            p1 = new Ponto(x1,y1);\r\n            p2 = new Ponto(x2,y2);\r\n            r = new Reta(p1,p2);\r\n            System.out.println (r);\r\n            c = t.leChar("Deseja sair do programa?(digite S ou s para sair, digite qualquer outro caracter para continuar)");\r\n        }\r\n    }\r\n}', NULL, '2016-05-13 16:15:02', 0),
(161, 24, 49, 'NumerosPares', 'public class NumerosPares {\r\n    private int n;\r\n    \r\n    public NumerosPares () {\r\n        n = 0;\r\n    }\r\n    \r\n    public NumerosPares (int n) {\r\n        this.n = n;\r\n    }\r\n    \r\n    public void setN (int n) {\r\n        this.n = n;\r\n    }\r\n    \r\n    public int getN () {\r\n        return n;\r\n    }\r\n    \r\n    public String geraPares () {\r\n        String res = "";\r\n        int cont = n;\r\n        int teste = cont%2;\r\n        if (teste !=0) {\r\n            cont--;\r\n        }\r\n        while (cont>0) {\r\n            if (cont!=n) {\r\n                res = cont+", "+res;\r\n            }\r\n            else{\r\n                res += cont;\r\n            }\r\n            cont -=2;\r\n        }\r\n        return res;\r\n    }\r\n    \r\n    public int somaNumeros () {\r\n        int soma = 0;\r\n        int teste = n%2;\r\n        int m = 0; //usado caso n seja impar\r\n        int i = 0; //índice da multiplicação\r\n        int b = 0; // base da soma\r\n        if (teste==0) {\r\n            i = n / 2; \r\n            b = n + 1;\r\n            soma = b * i;\r\n        }\r\n        else {\r\n            m = n - 1;\r\n            b = m + 1;\r\n            i = m / 2;\r\n            soma = b * i + n;\r\n        }\r\n        return soma;\r\n    }\r\n}', NULL, '2016-05-13 16:15:19', 0),
(162, 20, 40, 'Reta', 'public class Reta{\r\n    private Ponto ponto1, ponto2;\r\n    \r\n    public Reta(){\r\n        ponto1 = new Ponto();\r\n        ponto2 = new Ponto();\r\n    }\r\n    public Reta(Ponto p1, Ponto p2){\r\n        ponto1 = p1;\r\n        ponto2 = p2;\r\n    }\r\n    \r\n    public void setPonto1(Ponto p1){\r\n        ponto1 = p1;\r\n    }\r\n     public void setPonto2(Ponto p2){\r\n        ponto2 = p2;\r\n    }\r\n    \r\n    public Ponto getPonto1(){\r\n        return ponto1;\r\n    }\r\n    public Ponto getPonto2(){\r\n        return ponto2;\r\n    }\r\n    \r\n    public double getDistancia(){\r\n        double par1 = (ponto2.getX() - ponto1.getX());\r\n        double par2 = (ponto2.getY() - ponto1.getY());\r\n        double contIncomp = (Math.pow(par1, 2)) + (Math.pow(par2, 2));\r\n        double contCompl = Math.sqrt(contIncomp);\r\n        return contCompl;\r\n    }\r\n    \r\n    public String toString(){\r\n        String str = "\\n Distância entre os dois pontos: " + getDistancia();\r\n        return str;\r\n    }\r\n}', NULL, '2016-05-13 16:38:14', 0),
(163, 20, 40, 'TestaReta', 'public class TestaReta{\r\n    public static void main(String[] args){\r\n        Teclado t = new Teclado();\r\n        String opc = "";\r\n        \r\n        while(!(opc.equalsIgnoreCase("s"))){\r\n            System.out.println("Digite a coordenada X do ponto 1");\r\n            int x1 = t.leInt();\r\n            System.out.println("Digite a coordenada Y do ponto 1");\r\n            int y1 = t.leInt();\r\n            Ponto p1 = new Ponto(x1, y1);\r\n            System.out.println("Digite a coordenada X do ponto 2");\r\n            int x2 = t.leInt();\r\n            System.out.println("Digite a coordenada Y do ponto 2");\r\n            int y2 = t.leInt();\r\n            Ponto p2 = new Ponto(x2, y2);\r\n            \r\n            Reta r1 = new Reta(p1, p2); \r\n            \r\n            System.out.println(r1.toString());\r\n            System.out.println("");\r\n            \r\n            System.out.println("Você quer sair? [Digite ''S'' para sair]");\r\n            opc = t.leString();\r\n        }\r\n    }\r\n}', NULL, '2016-05-13 16:38:24', 0),
(164, 20, 31, 'Reta', '\r\n/**\r\n * Escreva a descrição da classe Reta aqui.\r\n * \r\n * @author (Augusto Dal Ago Richter) \r\n * @version (número de versão ou data)\r\n */\r\npublic class Reta\r\n{\r\n   private Ponto ponto1;\r\n   private Ponto ponto2;\r\n   \r\n   public Reta(Ponto p1, Ponto p2){\r\n       this.ponto1 = p1;\r\n       this.ponto2 = p2;\r\n   }\r\n   \r\n   public Reta(){\r\n       this.ponto1 = null;\r\n       this.ponto2 = null;\r\n    }\r\n    \r\n   public void setPonto1(Ponto p1){\r\n       this.ponto1 = p1;\r\n    }\r\n    \r\n    public void setPonto2(Ponto p2){\r\n        this.ponto2 = p2;\r\n    }\r\n    \r\n    public Ponto getPonto1(){\r\n        return ponto1;\r\n    }\r\n    \r\n    public Ponto getPonto2(){\r\n        return ponto2;\r\n    }\r\n    \r\n    public double getDistancia(){\r\n        double calculo = Math.pow((ponto2.getX() - ponto1.getX()),2) + Math.pow((ponto2.getY() - ponto1.getY()),2);\r\n        double raiz = Math.sqrt(calculo);\r\n        return raiz;\r\n    }\r\n    \r\n    public String toString(){\r\n        String texto = "Ponto 1:" + ponto1.toString()+ "\\nPonto 2:" +ponto2.toString();\r\n        return texto;\r\n    }\r\n}\r\n    \r\n        \r\n\r\n    \r\n   \r\n   \r\n', NULL, '2016-05-13 19:03:46', 0),
(165, 20, 31, 'Ponto', '\r\n/**\r\n * Escreva a descrição da classe Ponto aqui.\r\n * \r\n * @author Augusto Dal Ago Richter\r\n * @version (número de versão ou data)\r\n */\r\npublic class Ponto\r\n{\r\n    private int x, y;\r\n    \r\n    public Ponto(){\r\n        this.x = 0;\r\n        this.y = 0;\r\n    }\r\n    \r\n    public Ponto(int x, int y){\r\n        this.x = x;\r\n        this.y = y;\r\n    }\r\n    \r\n    public void setX(int x){\r\n        this.x = x;\r\n    }\r\n    \r\n    public void setY(int y){\r\n        this.y = y;\r\n    }\r\n    \r\n    public int getX(){\r\n        return x;\r\n    }\r\n    \r\n    public int getY(){\r\n        return y;\r\n    }\r\n    \r\n    public String toString(){\r\n         String texto = "("+x+","+y+")";\r\n         return texto;\r\n        }\r\n        \r\n    }   \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n\r\n', NULL, '2016-05-13 19:03:59', 0),
(166, 20, 31, 'Ponto', '\r\n/**\r\n * Escreva a descrição da classe Ponto aqui.\r\n * \r\n * @author Augusto Dal Ago Richter\r\n * @version (número de versão ou data)\r\n */\r\npublic class Ponto\r\n{\r\n    private int x, y;\r\n    \r\n    public Ponto(){\r\n        this.x = 0;\r\n        this.y = 0;\r\n    }\r\n    \r\n    public Ponto(int x, int y){\r\n        this.x = x;\r\n        this.y = y;\r\n    }\r\n    \r\n    public void setX(int x){\r\n        this.x = x;\r\n    }\r\n    \r\n    public void setY(int y){\r\n        this.y = y;\r\n    }\r\n    \r\n    public int getX(){\r\n        return x;\r\n    }\r\n    \r\n    public int getY(){\r\n        return y;\r\n    }\r\n    \r\n    public String toString(){\r\n         String texto = "("+x+","+y+")";\r\n         return texto;\r\n        }\r\n        \r\n    }   \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n\r\n', NULL, '2016-05-13 19:03:59', 0),
(169, 20, 31, 'Teclado', '\r\n/**\r\n * Escreva a descrição da classe Teclado aqui.\r\n * \r\n * @author (seu nome) \r\n * @version (número de versão ou data)\r\n */\r\npublic class Teclado\r\n{\r\n    // variáveis de instância - substitua o exemplo abaixo pelo seu próprio\r\n    private int x;\r\n\r\n    /**\r\n     * COnstrutor para objetos da classe Teclado\r\n     */\r\n    public Teclado()\r\n    {\r\n        // inicializa variáveis de instância\r\n        x = 0;\r\n    }\r\n\r\n    /**\r\n     * Exemplo de método - substitua este comentário pelo seu próprio\r\n     * \r\n     * @param  y   exemplo de um parâmetro de método\r\n     * @return     a soma de x com y \r\n     */\r\n    public int sampleMethod(int y)\r\n    {\r\n        // ponha seu código aqui\r\n        return x + y;\r\n    }\r\n}\r\n', NULL, '2016-05-13 19:04:18', 0),
(170, 20, 31, 'Teclado', '\r\n/**\r\n * Escreva a descrição da classe Teclado aqui.\r\n * \r\n * @author (seu nome) \r\n * @version (número de versão ou data)\r\n */\r\npublic class Teclado\r\n{\r\n    // variáveis de instância - substitua o exemplo abaixo pelo seu próprio\r\n    private int x;\r\n\r\n    /**\r\n     * COnstrutor para objetos da classe Teclado\r\n     */\r\n    public Teclado()\r\n    {\r\n        // inicializa variáveis de instância\r\n        x = 0;\r\n    }\r\n\r\n    /**\r\n     * Exemplo de método - substitua este comentário pelo seu próprio\r\n     * \r\n     * @param  y   exemplo de um parâmetro de método\r\n     * @return     a soma de x com y \r\n     */\r\n    public int sampleMethod(int y)\r\n    {\r\n        // ponha seu código aqui\r\n        return x + y;\r\n    }\r\n}\r\n', NULL, '2016-05-13 19:04:18', 0),
(171, 20, 50, 'Reta', '\r\n/**\r\n * Write a description of class Reta here.\r\n * \r\n * @author Vinícius Mateus Flach \r\n * @version (a version number or a date)\r\n */\r\npublic class Reta\r\n{\r\n    private Ponto ponto1;\r\n    private Ponto ponto2;\r\n    \r\n    public Reta(){\r\n        ponto1 = new Ponto();\r\n        ponto2 = new Ponto();\r\n    }\r\n    \r\n    public Reta(Ponto ponto1, Ponto ponto2){\r\n        this.ponto1 = ponto1;\r\n        this.ponto2 = ponto2;\r\n    }\r\n    \r\n    \r\n    public void setPonto1(Ponto ponto1){\r\n        this.ponto1 = ponto1;\r\n    }\r\n    \r\n    public Ponto getPonto1(){\r\n        return ponto1;\r\n    }\r\n    \r\n    public void setPonto2(Ponto ponto2){\r\n        this.ponto2 = ponto2;\r\n    }\r\n    \r\n    public Ponto getPonto2(){\r\n        return ponto2;\r\n    }\r\n    \r\n     public double getDistancia(){\r\n        double distancia = 0;\r\n        double a1, a2;\r\n        a1 = Math.pow(ponto2.getX() - ponto1.getX(), 2);\r\n        a2 = Math.pow(ponto2.getY() - ponto1.getY(), 2);\r\n        distancia = Math.sqrt(a1 + a2);\r\n        return distancia;\r\n    }\r\n\r\n    public String toString() {\r\n        String str = "";\r\n        str = "A distância é de: "+getDistancia();\r\n        return str;\r\n    }\r\n}\r\n\r\n\r\n', '\r\n/**\r\n * Write a description of class Reta here.\r\n * \r\n * @author (your name) \r\n * @version (a version number or a date)\r\n */\r\npublic class Reta\r\n{\r\n    private Ponto ponto1;\r\n    private Ponto ponto2;\r\n    \r\n    public Reta(){\r\n        ponto1 = new Ponto();\r\n        ponto2 = new Ponto();\r\n    }\r\n    \r\n    public Reta(Ponto ponto1, Ponto ponto2){\r\n        this.ponto1 = ponto1;\r\n        this.ponto2 = ponto2;\r\n    }\r\n    \r\n    \r\n    public void setPonto1(Ponto ponto1){\r\n        this.ponto1 = ponto1;\r\n    }\r\n    \r\n    public Ponto getPonto1(){\r\n        return ponto1;\r\n    }\r\n    \r\n    public void setPonto2(Ponto ponto2){\r\n        this.ponto2 = ponto2;\r\n    }\r\n    \r\n    public Ponto getPonto2(){\r\n        return ponto2;\r\n    }\r\n    \r\n     public double getDistancia(){\r\n        double distancia = 0;\r\n        double a1, a2;\r\n        a1 = Math.pow(ponto2.getX() - ponto1.getX(), 2);\r\n        a2 = Math.pow(ponto2.getY() - ponto1.getY(), 2);\r\n        distancia = Math.sqrt(a1 + a2);\r\n        return distancia;\r\n    }\r\n\r\n    public String toString() {\r\n        String str = "";\r\n        str = "A distância é de: "+getDistancia();\r\n        return str;\r\n    }\r\n}\r\n\r\n\r\n', '2016-05-13 20:56:40', 0),
(172, 20, 50, 'Teclado', ' \r\n\r\nimport java.io.*;\r\n\r\n/** Classe que permite fazer leitura de dados do tecladeo */\r\n\r\npublic class Teclado\r\n{\r\n     private String s;\r\n     private InputStreamReader i = new InputStreamReader (System.in);\r\n     private BufferedReader d = new BufferedReader(i);\r\n\r\n     /**\r\n        Le um inteiro.\r\n        @return int\r\n     */\r\n     public int leInt ()\r\n     {   System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         int a = 0;\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser inteiro: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um inteiro, com mensagem.\r\n        @return int\r\n     */\r\n     public int leInt (String msg)\r\n     { \r\n         int a = 0;\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: "+e );\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser inteiro: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um double.\r\n        @return double\r\n     */\r\n     public double leDouble()\r\n     { \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         double a = 0;\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Double.parseDouble(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser numero: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um double, com mensagem.\r\n        @return double\r\n     */\r\n     public double leDouble(String msg)\r\n     {   double a = 0;\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Double.parseDouble(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser numero: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um string.\r\n        @return String\r\n     */\r\n     public String leString()\r\n     { \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         s = "";\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            \r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (s);\r\n     }\r\n\r\n     /**\r\n        Le um string. com mensagem.\r\n        @return String\r\n     */\r\n     public String leString(String msg)\r\n     {   s = "";\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n            s = d.readLine();\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (s);\r\n     }\r\n        \r\n    /**\r\n        Le um char.\r\n        @return char\r\n     */\r\n     public char leChar()\r\n     {  \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         s = "";\r\n         char c='' '';\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            c = s.charAt(0);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (c);\r\n     }\r\n          \r\n     /**\r\n        Le um char com mensagem.\r\n        @return char\r\n     */\r\n     public char leChar(String msg)\r\n     {   s = "";\r\n         char c='' '';\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            c = s.charAt(0);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (c);\r\n     }\r\n     \r\n     \r\n    \r\n    }\r\n\r\n', NULL, '2016-05-13 20:50:18', 0),
(174, 20, 50, 'TestaReta', '/**\r\n * Write a description of class TestaReta here.\r\n * \r\n * @author Vinícius Mateus Flach\r\n * @version (a version number or a date)\r\n */\r\npublic class TestaReta\r\n{\r\n    public static void main (String args[]){\r\n        Teclado teclado = new Teclado();\r\n        char cont = teclado.leChar("Continuar ou sair?");\r\n        \r\n        while(cont!=''s''){\r\n        int p1 = teclado.leInt("Digite a coordenada x do Ponto 1: ");\r\n        int p2 = teclado.leInt("Digite a coordenada y do Ponto 1: ");\r\n        Ponto ponto1 = new Ponto (p1, p2);\r\n        \r\n        int p3 = teclado.leInt("Digite a coordenada x do Ponto 2: ");\r\n        int p4 = teclado.leInt("Digite a coordenada y do Ponto 2: ");\r\n        Ponto ponto2 = new Ponto (p3, p4);\r\n        \r\n        Reta r1 = new Reta (ponto1, ponto2);\r\n        \r\n        System.out.print(r1.toString());\r\n        cont = teclado.leChar("\\nContinuar ou sair?");\r\n        }\r\n    }\r\n}', NULL, '2016-05-13 21:03:36', 0),
