(180, 21, 51, 'Ponto', 'public class Ponto {\r\n\r\n    private int x;\r\n    private int y;\r\n    \r\n    public Ponto()\r\n    {\r\n        this.x = 0;\r\n        this.y = 0;\r\n    }\r\n    \r\n    public Ponto(int x, int y) {\r\n        this.x = x;\r\n        this.y = y;\r\n    }\r\n\r\n    public int getX() {\r\n        return x;\r\n    }\r\n\r\n    public void setX(int x) {\r\n        this.x = x;\r\n    }\r\n\r\n    public int getY() {\r\n        return y;\r\n    }\r\n\r\n    public void setY(int y) {\r\n        this.y = y;\r\n    }\r\n\r\n    @Override\r\n    public String toString() {\r\n        return "(" + x + ", " + y + '')'';\r\n    }\r\n}\r\n', NULL, '2016-05-13 22:31:31', 0),
(182, 26, 48, 'Teclado', ' \r\n\r\nimport java.io.*;\r\n\r\n/** Classe que permite fazer leitura de dados do tecladeo */\r\n\r\npublic class Teclado\r\n{\r\n     private String s;\r\n     private InputStreamReader i = new InputStreamReader (System.in);\r\n     private BufferedReader d = new BufferedReader(i);\r\n\r\n     /**\r\n        Le um inteiro.\r\n        @return int\r\n     */\r\n     public int leInt ()\r\n     {   System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         int a = 0;\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser inteiro: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um inteiro, com mensagem.\r\n        @return int\r\n     */\r\n     public int leInt (String msg)\r\n     { \r\n         int a = 0;\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: "+e );\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser inteiro: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um double.\r\n        @return double\r\n     */\r\n     public double leDouble()\r\n     { \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         double a = 0;\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Double.parseDouble(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser numero: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um double, com mensagem.\r\n        @return double\r\n     */\r\n     public double leDouble(String msg)\r\n     {   double a = 0;\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Double.parseDouble(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser numero: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um string.\r\n        @return String\r\n     */\r\n     public String leString()\r\n     { \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         s = "";\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            \r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (s);\r\n     }\r\n\r\n     /**\r\n        Le um string. com mensagem.\r\n        @return String\r\n     */\r\n     public String leString(String msg)\r\n     {   s = "";\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n            s = d.readLine();\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (s);\r\n     }\r\n        \r\n    /**\r\n        Le um char.\r\n        @return char\r\n     */\r\n     public char leChar()\r\n     {  \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         s = "";\r\n         char c='' '';\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            c = s.charAt(0);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (c);\r\n     }\r\n          \r\n     /**\r\n        Le um char com mensagem.\r\n        @return char\r\n     */\r\n     public char leChar(String msg)\r\n     {   s = "";\r\n         char c='' '';\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            c = s.charAt(0);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (c);\r\n     }\r\n     \r\n     \r\n    \r\n    }\r\n\r\n', NULL, '2016-05-13 23:38:05', 0);
INSERT INTO `exercicioclasse` (`ID`, `IdExercicio`, `IdAluno`, `NomeClasse`, `Codigo`, `CodigoAnterior`, `DataCadastro`, `Favorito`) VALUES
(186, 20, 49, 'Reta', 'public class Reta {\r\n    private Ponto ponto1, ponto2;\r\n    \r\n    public Reta () {\r\n        this.ponto1 = new Ponto();\r\n        this.ponto2 = new Ponto();\r\n    }\r\n    \r\n    public Reta (Ponto ponto1,Ponto ponto2) {\r\n        this.ponto1 = ponto1;\r\n        this.ponto2 = ponto2;\r\n    }\r\n    \r\n    public void setPonto1 (Ponto ponto1) {\r\n        this.ponto1 = ponto1;        \r\n    }\r\n    \r\n    public Ponto getPonto1 () {\r\n        return ponto1;\r\n    }\r\n    \r\n    public void setPonto2 (Ponto ponto2) {\r\n        this.ponto2 = ponto2;        \r\n    }\r\n    \r\n    public Ponto getPonto2 () {\r\n        return ponto2;\r\n    }\r\n    \r\n    public double getDistancia () {\r\n        double res = 0;\r\n        double a = 0;\r\n        double b = 0;\r\n        double c = 0;\r\n        a = ponto2.getX() - ponto1.getX();\r\n        b = Math.pow (a,2);\r\n        res = res + b;\r\n        a = ponto2.getY() - ponto1.getY();\r\n        b = Math.pow (a,2);\r\n        res = res + b;\r\n        c = Math.sqrt(res);\r\n        res = c;\r\n        return res;\r\n    }\r\n    \r\n    public String toString() {\r\n        String tex ="";\r\n        tex = "Ponto 1 da reta: "+ponto1.toString();\r\n        tex += "\\nPonto 2 da reta: "+ponto2.toString();\r\n        tex += "\\nDistância entre os pontos da reta: "+getDistancia();\r\n        return tex;\r\n    }\r\n}', NULL, '2016-05-13 23:42:13', 0),
(188, 26, 48, 'TestaTabuada', '/**\r\n * @author Rodrigo Brandt\r\n * @version 13/05/16\r\n */\r\n\r\npublic class TestaTabuada{\r\n    public static void main(String args[]){\r\n        Teclado t = new Teclado();\r\n        int numero = t.leInt("Digite um numero ou -1 para sair: ");\r\n        while(numero != -1){\r\n            Tabuada ts = new Tabuada(numero);\r\n            System.out.println(ts.calculaTabuada());\r\n            numero = t.leInt("Digite um numero ou -1 para sair: ");\r\n        }\r\n    }\r\n}\r\n', NULL, '2016-05-13 23:45:38', 0),
(191, 25, 39, 'Desenho', '/* \r\n * Joice Cazanoski Gomes\r\n * 13/05/2016\r\n */\r\npublic class Desenho{\r\n    private String simbolo;\r\n    \r\n    public Desenho(String simbolo){\r\n        this.simbolo = simbolo;\r\n    }\r\n    \r\n    public void setSimbolo(String simbolo){\r\n        this.simbolo = simbolo;\r\n    }\r\n    \r\n    public String getSimbolo(){\r\n        return simbolo;\r\n    }\r\n    \r\n    public String desenhaLinha(int comp){\r\n        String ret = "";\r\n        for(int i =1; i <= comp; i++){\r\n            ret += simbolo;\r\n        }        \r\n        return ret;\r\n    }\r\n    \r\n    public String desenhaTriangulo(int linhas){\r\n        String ret = "";\r\n        for(int i = 1; i<=linhas; i++){\r\n            ret += desenhaLinha(i)+ "\\n";\r\n        }\r\n        return ret;\r\n    }\r\n    \r\n    public String desenhaQuadrado(int nroLinhas){\r\n        String ret = "";\r\n        for(int i = 1; i <= nroLinhas; i++){\r\n            ret += desenhaLinha(nroLinhas) + "\\n";\r\n        }\r\n        System.out.println(ret);\r\n        return ret;\r\n    }\r\n    \r\n    public String desenhaLinhaVazada(int comp){\r\n        String ret = "";\r\n        for (int i = 1; i <= comp; i++){\r\n            if (i == 1 || i == comp)\r\n                ret += simbolo;\r\n            else \r\n                ret += " ";\r\n        }      \r\n        return ret;\r\n    }\r\n    \r\n    public String desenhaQuadradoVazado(int linhas){\r\n        String ret = "";\r\n        for(int i = 1; i<=linhas; i++){\r\n            if(i == 1 || i == linhas)\r\n            ret += desenhaLinha(linhas)+ "\\n";\r\n            else\r\n            ret += desenhaLinhaVazada(linhas)+ "\\n";\r\n        }\r\n        return ret;\r\n    }\r\n}', NULL, '2016-05-14 00:03:01', 0),
(195, 25, 48, 'Desenho', '/**\r\n * @author Rodrigo Brandt\r\n * @version 13/05/16\r\n */\r\n\r\npublic class Desenho{\r\n    \r\n    // atributos\r\n    private String simbolo;\r\n    \r\n    // construtor\r\n    public Desenho(String s){\r\n        this.simbolo = s;\r\n    }\r\n    \r\n    // get\r\n    public String getSimbolo(){\r\n        return simbolo;\r\n    }\r\n    \r\n    // set\r\n    public void setSimbolo(String s){\r\n        this.simbolo = s;\r\n    }\r\n    \r\n    \r\n    public String desenhaTriangulo (int linhas){\r\n        String triangulo = "";\r\n        for (int i = 1; i <= linhas; i++){\r\n            triangulo += desenhaLinha(i)+"\\n";\r\n        }\r\n        return triangulo;\r\n    }\r\n    \r\n    // Esse método desenha  uma  linha  de  comprimento  comp  e  a  retorna  como  uma String\r\n    public String desenhaLinha (int comp){\r\n        String linha = "";\r\n        for (int i = 1; i <= comp; i++){\r\n            linha += simbolo;\r\n        }\r\n        return linha;\r\n    }\r\n    \r\n    /* Esse método desenha uma linha de  comprimento comp e  a  retorna  como  uma String\r\n     * A  diferença  deste método  para  o  método desenhaLinha é que  apenas  o  primeiro  e  último\r\n     * caracteres da linha serão representados pelo símbolo\r\n     */\r\n    public String desenhaLinhaVazada (int comp){\r\n        String linha = simbolo;\r\n        for (int i = 1; i <= (comp-2); i++){\r\n            linha += " ";\r\n        }\r\n        linha += simbolo;\r\n        return linha;\r\n    }\r\n    \r\n    // Esse método desenha  um  quadrado,  onde  o número de linhas do mesmo é passado como parâmetro\r\n    public String desenhaQuadrado (int linhas){\r\n        String quadrado = "";\r\n        quadrado += desenhaLinha(linhas)+"\\n";\r\n        for (int i = 1; i <= (linhas-2); i++){\r\n            quadrado += desenhaLinha(linhas)+"\\n";\r\n        }\r\n        quadrado += desenhaLinha(linhas)+"\\n";\r\n        return quadrado;\r\n    }\r\n    \r\n    \r\n    public String desenhaQuadradoVazado (int nroLinhas){\r\n        String quadrado = "";\r\n        quadrado += desenhaLinha(nroLinhas)+"\\n";\r\n        for (int i = 1; i <= (nroLinhas-2); i++){\r\n            quadrado += desenhaLinhaVazada(nroLinhas)+"\\n";\r\n        }\r\n        quadrado += desenhaLinha(nroLinhas)+"\\n";\r\n        return quadrado;\r\n    }\r\n    \r\n    \r\n    \r\n}\r\n', NULL, '2016-05-14 00:07:10', 0),
(198, 26, 39, 'Teclado', ' \r\n\r\nimport java.io.*;\r\n\r\n/** Classe que permite fazer leitura de dados do tecladeo */\r\n\r\npublic class Teclado\r\n{\r\n     private String s;\r\n     private InputStreamReader i = new InputStreamReader (System.in);\r\n     private BufferedReader d = new BufferedReader(i);\r\n\r\n     /**\r\n        Le um inteiro.\r\n        @return int\r\n     */\r\n     public int leInt ()\r\n     {   System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         int a = 0;\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser inteiro: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um inteiro, com mensagem.\r\n        @return int\r\n     */\r\n     public int leInt (String msg)\r\n     { \r\n         int a = 0;\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: "+e );\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser inteiro: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um double.\r\n        @return double\r\n     */\r\n     public double leDouble()\r\n     { \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         double a = 0;\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Double.parseDouble(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n