(200, 26, 39, 'Tabuada', '\r\n/**\r\n * @author Joice Cazanoski Gomes\r\n * @version 13/05/2016\r\n */\r\npublic class Tabuada {\r\n    private int numero;\r\n    \r\n    public Tabuada(int numero){\r\n        this.numero = numero;\r\n    }\r\n    \r\n    public Tabuada(){\r\n        numero = 0;\r\n    }\r\n    \r\n    public void setNumero(int numero){\r\n        this.numero = numero;\r\n    }\r\n    \r\n    public int getNumero(){\r\n        return numero;\r\n    }\r\n    \r\n    public String calculaTabuada(){\r\n        String ret = "";\r\n        for(int i = 1; i<=10; i++){\r\n            ret += numero + " x " + i + " = " + (numero*i)+ "\\n";\r\n        }\r\n        return ret;\r\n    }\r\n}\r\n   ', NULL, '2016-05-14 00:10:45', 0),
(202, 26, 39, 'TestaTabuada', '\r\n/**\r\n * @author Joice Cazanoski Gomes\r\n * @version 13/05/2016\r\n */\r\npublic class TestaTabuada{\r\n    public static void main(String args[]){\r\n        Teclado t = new Teclado();\r\n        int i = 0;\r\n        while(i != -1){ \r\n            i = t.leInt("Digite um numero ou -1 para sair");\r\n            if(i != -1){\r\n            Tabuada a = new Tabuada(i);\r\n            System.out.println(a.calculaTabuada()); \r\n           }\r\n        \r\n        }\r\n    }\r\n}\r\n    ', NULL, '2016-05-14 00:13:02', 0),
(204, 26, 49, 'Teclado', ' \r\n\r\nimport java.io.*;\r\n\r\n/** Classe que permite fazer leitura de dados do tecladeo */\r\n\r\npublic class Teclado\r\n{\r\n     private String s;\r\n     private InputStreamReader i = new InputStreamReader (System.in);\r\n     private BufferedReader d = new BufferedReader(i);\r\n\r\n     /**\r\n        Le um inteiro.\r\n        @return int\r\n     */\r\n     public int leInt ()\r\n     {   System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         int a = 0;\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser inteiro: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um inteiro, com mensagem.\r\n        @return int\r\n     */\r\n     public int leInt (String msg)\r\n     { \r\n         int a = 0;\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: "+e );\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser inteiro: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um double.\r\n        @return double\r\n     */\r\n     public double leDouble()\r\n     { \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         double a = 0;\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Double.parseDouble(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser numero: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um double, com mensagem.\r\n        @return double\r\n     */\r\n     public double leDouble(String msg)\r\n     {   double a = 0;\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Double.parseDouble(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser numero: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um string.\r\n        @return String\r\n     */\r\n     public String leString()\r\n     { \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         s = "";\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            \r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (s);\r\n     }\r\n\r\n     /**\r\n        Le um string. com mensagem.\r\n        @return String\r\n     */\r\n     public String leString(String msg)\r\n     {   s = "";\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n            s = d.readLine();\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (s);\r\n     }\r\n        \r\n    /**\r\n        Le um char.\r\n        @return char\r\n     */\r\n     public char leChar()\r\n     {  \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         s = "";\r\n         char c='' '';\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            c = s.charAt(0);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (c);\r\n     }\r\n          \r\n     /**\r\n        Le um char com mensagem.\r\n        @return char\r\n     */\r\n     public char leChar(String msg)\r\n     {   s = "";\r\n         char c='' '';\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            c = s.charAt(0);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (c);\r\n     }\r\n     \r\n     \r\n    \r\n    }\r\n\r\n', NULL, '2016-05-14 00:13:22', 0),
(209, 25, 30, 'Desenho', '\r\n/**\r\n * Escreva a descrição da classe Desenho aqui.\r\n * \r\n * @author (seu nome) \r\n * @version (número de versão ou data)\r\n */\r\npublic class Desenho\r\n{\r\n    private String simbolo;\r\n    \r\n    public Desenho (String simbolo){\r\n        this.simbolo = simbolo;\r\n    }\r\n    \r\n    public void setSimbolo (String simbolo){\r\n        this.simbolo = simbolo;\r\n    }\r\n    \r\n    public String getSimbolo () {\r\n        return simbolo;\r\n    }\r\n    \r\n    public  String desenhaLinha(int  comp) {\r\n        String ret = "";\r\n        \r\n        for (int i=1; i<= comp; i++) {\r\n            ret = ret + simbolo;\r\n        }        \r\n        return ret;\r\n    }\r\n    \r\n    public String desenhaTriangulo (int nroLinhas) {\r\n        String ret = "";\r\n        \r\n        for (int i=1; i<= nroLinhas; i++) {\r\n            ret = ret + desenhaLinha (i)+"\\n";\r\n        }\r\n        \r\n        return ret;\r\n    }\r\n    \r\n    public String desenhaQuadrado (int nroLinhas){\r\n        String ret = "";\r\n        \r\n        for ( int i = 1; i <= nroLinhas ; i++){\r\n            ret = ret + desenhaLinha(nroLinhas)+ "\\n";\r\n        }\r\n        return  ret;\r\n    }\r\n    \r\n    public String desenhaLinhaVazada (int comp){\r\n        String ret = "";\r\n        for (int i = 1; i <= comp ; i++){\r\n            if (i == 1 || i == comp){\r\n                ret = ret + simbolo;\r\n            }\r\n            \r\n            else{\r\n                ret = ret + " ";\r\n            }\r\n            \r\n        } \r\n        return ret;\r\n    }\r\n    \r\n    public String desenhaQuadradoVazado (int nroLinhas){\r\n        String ret = "";\r\n        for (int i = 1 ; i <= nroLinhas ; i++){\r\n        if ( i == 1 || i == nroLinhas){\r\n            ret = ret + desenhaLinha(nroLinhas)+ "\\n";\r\n        }\r\n        \r\n        else{\r\n            ret = ret + desenhaLinhaVazada(nroLinhas)+"\\n";\r\n        }\r\n    }\r\n    \r\n    \r\n        return ret;\r\n    }\r\n    \r\n   \r\n        \r\n        \r\n        \r\n}\r\n', NULL, '2016-05-14 00:17:33', 0),
(211, 25, 45, 'Desenho', '\r\n/**\r\n * Escreva a descrição da classe Desenho aqui.\r\n * \r\n * @author (Mateus Hoff) \r\n * @version (número de versão ou data)\r\n */\r\npublic class Desenho{\r\n    private String simbolo;\r\n    public Desenho (String simbolo){\r\n        this.simbolo = simbolo;\r\n    }\r\n    public void setSimbolo (String simbolo){\r\n        this.simbolo = simbolo;\r\n    }\r\n    public String getSimbolo(){\r\n        return simbolo;\r\n    }\r\n    public String desenhaLinha(int comp){\r\n      String ret =""; \r\n      for (int i = 1; i <= comp; i++){\r\n          ret = ret+simbolo;\r\n      }\r\n      return ret;\r\n    }\r\n    public String desenhaTriangulo(int nroLinhas){\r\n        String ret ="";\r\n        for(int i = 1; i<= nroLinhas; i++){\r\n            ret = ret +desenhaLinha(i)+"\\n";\r\n        }\r\n        return ret;\r\n    }\r\n    public String desenhaQuadrado(int nroLinhas){\r\n        String ret = "";\r\n        for(int i = 1; i <= nroLinhas ; i++){\r\n            \r\n            ret = ret + desenhaLinha(nroLinhas)+"\\n";\r\n        }\r\n        return ret;\r\n        \r\n    }\r\n    public String desenhaLinhaVazada(int comp){\r\n    String ret = "";\r\n        for(int i = 1; i <= comp; i++){\r\n            if( i == 1 || i == comp)\r\n                ret = ret + simbolo;\r\n        else \r\n         ret = ret+" ";\r\n    }\r\n    return ret;\r\n    }\r\n    public String desenhaQuadradoVazado(int nroLinhas){\r\n        String ret = "";\r\n        for(int i = 1; i <= nroLinhas; i++){\r\n            if(i == 1 || i == nroLinhas)\r\n            ret = ret + desenhaLinha(nroLinhas)+"\\n";\r\n            else \r\n            ret = ret + desenhaLinhaVazada(nroLinhas)+"\\n";\r\n        }\r\n        return ret;\r\n        \r\n    }\r\n}', NULL, '2016-05-14 00:17:59', 0),
(214, 25, 45, 'TestaDesenho', '\r\n/**\r\n * Escreva a descrição da classe TestaDesenho aqui.\r\n * \r\n * @author (seu nome) \r\n * @version (número de versão ou data)\r\n */\r\npublic class TestaDesenho{\r\n    public static void main (String args []){\r\n        Desenho d = new Desenho ("*");\r\n        System.out.println("Linha: \\n"+d.desenhaLinha(4));\r\n        System.out.println("Triangulo: \\n"+d.desenhaTriangulo(5));\r\n        System.out.println("Quadrado: \\n"+d.desenhaQuadrado(4));\r\n        System.out.println("Linha Vazada: \\n"+d.desenhaLinhaVazada(5));\r\n        System.out.println("Quadrado Vazado: \\n"+d.desenhaQuadradoVazado(4));\r\n        \r\n    }\r\n}', NULL, '2016-05-14 00:18:23', 0),
(215, 25, 49, 'Desenho', 'public class Desenho {\r\n    private String simbolo;\r\n    \r\n    public Desenho (String simbolo) {\r\n        this.simbolo = simbolo;\r\n    }\r\n    \r\n    public void setSimbolo (String simbolo) {\r\n        this.simbolo = simbolo;\r\n    }\r\n    \r\n    public String getSimbolo () {\r\n        return simbolo;\r\n    }\r\n    \r\n    public String desenhaLinha (int comp) {\r\n        String ret = "";\r\n        for (int i=1; i<=comp; i++) {\r\n            ret = ret + simbolo;\r\n        }\r\n        return ret;\r\n    }\r\n    \r\n    public String desenhaTriangulo (int linhas) {\r\n        String ret = "";\r\n        for (int i=1; i<=linhas; i++) {\r\n            ret = ret + desenhaLinha(i) + "\\n";            \r\n        }        \r\n        return ret;\r\n    }\r\n    \r\n    public String desenhaLinhaVazada (int comp) {\r\n        String ret = "";\r\n        if (comp>2) {\r\n            ret = ret + simbolo;\r\n            for (int i=1; i<=(comp-2); i++) {\r\n                ret = ret + " ";\r\n            }\r\n            ret = ret + simbolo;\r\n        }\r\n        else {\r\n            desenhaLinha(comp);\r\n        }        \r\n        return ret;\r\n    }\r\n    \r\n    public String desenhaQuadradoVazado (int linhas) {\r\n        String ret = "";\r\n        for (int i=1; i<=linhas; i++) {\r\n            if (i==1 || i==linhas) {\r\n                ret = ret + desenhaLinha(linhas) + "\\n";\r\n            }\r\n            else {\r\n                ret = ret + desenhaLinhaVazada(linhas) + "\\n";\r\n            }                         \r\n        }        \r\n        return ret;\r\n    }\r\n	public String desenhaQuadrado (int linhas) {\r\n		String ret = "";\r\n		for (int i=1; i<=linhas; i++) {\r\n			ret = ret + desenhaLinha(linhas) + "\\n";\r\n		}\r\n		return ret;\r\n	}\r\n}', NULL, '2016-05-14 00:18:42', 0),
(216, 26, 48, 'Tabuada', '/**\r\n * @author Rodrigo Brandt\r\n * @version 13/05/16\r\n */\r\n\r\npublic class Tabuada{\r\n    \r\n    // atributo\r\n    private int numero;\r\n    \r\n    // construtor\r\n    public Tabuada(int n){\r\n        this.numero = n;\r\n    }\r\n    \r\n    // construtor default\r\n    public Tabuada(){\r\n        this.numero = 0;\r\n    }\r\n    \r\n    // get\r\n    public int getNumero(){\r\n        return numero;\r\n    }\r\n    \r\n    // set\r\n    public void setNumero(int n){\r\n        this.numero = n;\r\n    }\r\n    \r\n    //  Esse  método  irá  calcular  e  retornar  uma  String  contendo  a  tabuada  para  o  número  guardado  no  atributo\r\n    public String calculaTabuada(){\r\n        String tabuada = "";\r\n        for (int i = 1; i <= 10; i++){\r\n            tabuada += (numero+" x "+i+" = "+(numero*i)+"\\n");\r\n        }\r\n        return tabuada;\r\n    }\r\n}\r\n', NULL, '2016-05-14 00:19:54', 0),
(218, 26, 49, 'TestaTabuada', 'public class TestaTabuada {\r\n    public static void main (String args[]) {\r\n        Teclado t = new Teclado();\r\n        Tabuada t1 = new Tabuada();\r\n        int i = 0;\r\n        while(i!=-1){\r\n            i=t.leInt("Digite um numero ou -1 para sair");\r\n            if (i!=-1) {\r\n                t1 = new Tabuada(i);\r\n                System.out.println(t1.calculaTabuada());\r\n            }\r\n        }        \r\n    }\r\n}', NULL, '2016-05-14 00:21:19', 0),
(220, 26, 49, 'Tabuada', 'public class Tabuada {\r\n    private int numero;\r\n    \r\n    public Tabuada (int numero) {\r\n        this.numero = numero;\r\n    }\r\n    \r\n    public Tabuada () {\r\n        this.numero = 0;\r\n    }    \r\n    \r\n    public void setNumero (int numero) {\r\n        this.numero = numero;\r\n    }\r\n    \r\n    public int getNumero () {\r\n        return numero;\r\n    }\r\n    \r\n    public String calculaTabuada() {\r\n        String ret = "";\r\n        int res = 0;\r\n        for (int i=1; i<=10; i++) {\r\n            res = numero * i;\r\n            ret = ret+numero+" x "+i+" = "+res+"\\n";\r\n        }        \r\n        return ret;\r\n    }\r\n}', 'public class Tabuada {\r\n    private int numero;\r\n    \r\n    public Tabuada (int numero) {\r\n        this.numero = numero;\r\n    }\r\n    \r\n    public Tabuada () {\r\n        this.numero = 0;\r\n    }    \r\n    \r\n    public void setNumero (int numero) {\r\n        this.numero = numero;\r\n    }\r\n    \r\n    public int getNumero () {\r\n        return numero;\r\n    }\r\n    \r\n    public String calculaTabuada() {\r\n        String ret = "";\r\n        int res = 0;\r\n        for (int i=1; i<=10; i++) {\r\n            res = numero * i;\r\n            ret = ret+numero+"x"+i+"="+res+"\\n";\r\n        }        \r\n        return ret;\r\n    }\r\n}', '2016-05-14 00:28:59', 0),
(222, 25, 46, 'Desenho', '\r\n/**\r\n * Escreva a descrição da classe Desenho aqui.\r\n * \r\n * @author (seu nome) \r\n * @version (número de versão ou data)\r\n */\r\npublic class Desenho\r\n{\r\n    private String simbolo;\r\n    \r\n    public Desenho (String simbolo){\r\n        this.simbolo = simbolo;\r\n    }\r\n   \r\n     public void setSimbolo (String simbolo){\r\n        this.simbolo = simbolo;\r\n    }\r\n    \r\n    public String getSimbolo (){\r\n        return simbolo;\r\n    }\r\n    \r\n    public String desenhaLinha (int comp) {\r\n        String ret = "";\r\n        for (int i=1; i<=comp; i++) {\r\n            ret = ret + simbolo;\r\n        }\r\n        return ret;\r\n    } \r\n   public String desenhaQuadrado (int nroLinhas) {\r\n       String ret = "";\r\n       for (int i=1; i<=nroLinhas ; i++) {\r\n        ret = ret + desenhaLinha (nroLinhas) + "\\n";\r\n        } \r\n       return ret;\r\n    } \r\n    \r\n   public String desenhaTriangulo (int nroLinhas) {\r\n       String ret = "";\r\n       for (int i=1; i<=nroLinhas ; i++) {\r\n        ret = ret + desenhaLinha (i) + "\\n";\r\n        } \r\n       \r\n       return ret;\r\n    } \r\n   public String desenhaLinhaVazada (int nroLinhas) {\r\n       String ret = "";\r\n       for (int i=1; i<=nroLinhas; i++) {\r\n        if (i==1 || i==nroLinhas)\r\n        ret = ret + desenhaLinha (1);\r\n        else\r\n        ret = ret + " ";\r\n    }\r\n    return ret;\r\n    }\r\n   public String desenhaQuadradoVazado (int nroLinhas) {\r\n      String ret = "";\r\n    for (int i=1; i<=nroLinhas; i++) {\r\n    if (i==1 || i==nroLinhas)\r\n    ret = ret + desenhaLinha (nroLinhas) + "\\n";\r\n    else \r\n    ret = ret + desenhaLinhaVazada (nroLinhas) + "\\n";\r\n    }\r\n    return ret;\r\n    }\r\n   }\r\n\r\n\r\n\r\n', NULL, '2016-05-14 00:31:14', 0),
(223, 25, 47, 'Desenho', '\r\n/**\r\n * Escreva a descrição da classe Desenho aqui.\r\n * \r\n * @author (seu nome) \r\n * @version (número de versão ou data)\r\n */\r\npublic class Desenho\r\n{\r\n    private String simbolo;\r\n    \r\n    public Desenho (String simbolo){\r\n        this.simbolo = simbolo;\r\n    }\r\n    \r\n    public void setSimbolo (String simbolo){\r\n        this.simbolo = simbolo;\r\n    }\r\n    \r\n    public String getSimbolo () {\r\n        return simbolo;\r\n    }\r\n    \r\n    public  String desenhaLinha(int  comp) {\r\n        String ret = "";\r\n        \r\n        for (int i=1; i<= comp; i++) {\r\n            ret = ret + simbolo;\r\n        }        \r\n        return ret;\r\n    }\r\n    \r\n    public String desenhaTriangulo (int nroLinhas) {\r\n        String ret = "";\r\n        \r\n        for (int i=1; i<= nroLinhas; i++) {\r\n            ret = ret + desenhaLinha (i)+"\\n";\r\n        }\r\n        \r\n        return ret;\r\n    }\r\n    \r\n    public String desenhaLinhaVazada(int comp){\r\n        String ret="";\r\n        for (int i=1;i<=comp;i++){\r\n            if(i==1||i==comp){\r\n                ret = ret + simbolo;\r\n            }else{\r\n                ret=ret+" ";\r\n            }\r\n            \r\n        }\r\n        \r\n        return ret;\r\n    }\r\n    \r\n    public  String desenhaQuadradoVazado(int linhas){\r\n        String ret="";\r\n        for(int i=1;i<=linhas;i++){\r\n            if(i==1||i==linhas){\r\n                ret=ret+desenhaLinha(linhas)+"\\n";\r\n            }else{\r\n                ret=ret+desenhaLinhaVazada(linhas)+"\\n";\r\n            }   \r\n        }\r\n        \r\n        return ret;\r\n    }\r\n    \r\n    public String desenhaQuadrado(int nroLinhas){\r\n        String ret="";\r\n        for(int i =1;i<=nroLinhas;i++){\r\n            ret=ret+desenhaLinha(nroLinhas)+"\\n";\r\n        }\r\n        return ret;\r\n    }\r\n}\r\n', NULL, '2016-05-14 00:35:27', 0),
(224, 25, 47, 'TestaDesenho', '\r\n/**\r\n * Escreva a descrição da classe TestaDesenho aqui.\r\n * \r\n * @author (seu nome) \r\n * @version (número de versão ou data)\r\n */\r\npublic class TestaDesenho\r\n{\r\n    public static void main (String args[]){\r\n        Desenho d = new Desenho ("x");\r\n        System.out.println (d.desenhaQuadrado(5));\r\n    }\r\n}\r\n', NULL, '2016-05-14 00:35:37', 0),
(230, 25, 40, 'Desenho', '\r\n/**\r\n * Escreva a descrição da classe Desenho aqui.\r\n * \r\n * @author (seu nome) \r\n * @version (número de versão ou data)\r\n */\r\npublic class Desenho\r\n{\r\n    private String simbolo;\r\n    \r\n    public Desenho (String simbolo){\r\n        this.simbolo = simbolo;\r\n    }\r\n    \r\n    public void setSimbolo (String simbolo){\r\n        this.simbolo = simbolo;\r\n    }\r\n    \r\n    public String getSimbolo () {\r\n        return simbolo;\r\n    }\r\n    \r\n    public  String desenhaLinha(int  comp) {\r\n        String ret = "";\r\n        \r\n        for (int i=1; i<= comp; i++) {\r\n            ret = ret + simbolo;\r\n        }        \r\n        return ret;\r\n    }\r\n    \r\n    public String desenhaTriangulo (int nroLinhas) {\r\n        String ret = "";\r\n        \r\n        for (int i=1; i<= nroLinhas; i++) {\r\n            ret = ret + desenhaLinha (i)+"\\n";\r\n        }\r\n        \r\n        return ret;\r\n    }\r\n    \r\n    public String desenhaQuadrado(int nroLinhas){\r\n        String ret = "";\r\n        for(int i=1; i <=nroLinhas; i++){\r\n            ret = ret + desenhaLinha (nroLinhas)+"\\n";\r\n        }\r\n        return ret;\r\n    }\r\n    \r\n    public String desenhaLinhaVazada (int comp){\r\n        String ret = "";\r\n        for(int i = 1; i <= comp; i++){\r\n            if(i == 1 || i == comp){\r\n                ret = ret + simbolo;\r\n            }\r\n            else{\r\n                ret = ret + " "; \r\n            }\r\n        }\r\n        return ret;\r\n    }\r\n    \r\n    public String desenhaQuadradoVazado (int nrolinhas){\r\n        String ret = "";\r\n        for(int i = 1; i <= nrolinhas; i++){\r\n            if(i == 1 || i == nrolinhas){\r\n                ret = ret + desenhaLinha(nrolinhas)+"\\n";\r\n            }\r\n            else{\r\n                ret = ret + desenhaLinhaVazada(nrolinhas)+"\\n";\r\n            }\r\n        }\r\n        return ret;\r\n    }\r\n}\r\n', NULL, '2016-05-14 04:28:30', 0),
(231, 25, 40, 'TestaDesenho', '\r\n/**\r\n * Escreva a descrição da classe TestaDesenho aqui.\r\n * \r\n * @author (seu nome) \r\n * @version (número de versão ou data)\r\n */\r\npublic class TestaDesenho\r\n{\r\n    public static void main (String args[]){\r\n        Desenho d = new Desenho ("*");\r\n        System.out.println(d.desenhaLinha(8));\r\n        System.out.println(d.desenhaLinhaVazada(8));\r\n        System.out.println (d.desenhaTriangulo(8));\r\n        System.out.println(d.desenhaQuadrado(8));\r\n        System.out.println(d.desenhaQuadradoVazado(8));\r\n        \r\n    }\r\n}\r\n', NULL, '2016-05-14 04:28:36', 0),
(232, 25, 43, 'Desenho', '\r\n/**\r\n * Escreva a descrição da classe Desenho aqui.\r\n * \r\n * @author Marcos Roberto Souza \r\n * @version 13/05/2016\r\n */\r\npublic class Desenho\r\n{\r\n    private String simbolo;\r\n    \r\n    public Desenho (String simbolo){\r\n        this.simbolo = simbolo;\r\n    }\r\n    \r\n    public void setSimbolo (String simbolo){\r\n        this.simbolo = simbolo;\r\n    }\r\n    \r\n    public String getSimbolo () {\r\n        return simbolo;\r\n    }\r\n    \r\n    public  String desenhaLinha(int  comp) {\r\n        String ret = "";\r\n        \r\n        for (int i=1; i<= comp; i++) {\r\n            ret = ret + simbolo;\r\n        }        \r\n        return ret;\r\n    }\r\n    \r\n    public String desenhaTriangulo (int nroLinhas) {\r\n        String ret = "";\r\n        \r\n        for (int i=1; i<= nroLinhas; i++) {\r\n            ret = ret + desenhaLinha (i)+"\\n";\r\n        }\r\n        \r\n        return ret;\r\n    }\r\n    \r\n    public String desenhaQuadrado (int nroLinhas) {\r\n        String ret = "";\r\n        \r\n        for (int i=1; i<= nroLinhas; i++) {\r\n            ret = ret + desenhaLinha (nroLinhas)+"\\n";\r\n        }\r\n        \r\n        return ret;\r\n    }\r\n    \r\n    public String desenhaLinhaVazada(int comp){\r\n        String ret = "";\r\n        \r\n        for (int i=1; i<= comp; i++) {\r\n            if(i==1 || i==comp)\r\n                ret = ret + simbolo;\r\n            else\r\n        ret = ret + " ";\r\n        }\r\n        return ret;\r\n    }\r\n    \r\n    public String desenhaQuadradoVazado(int comp){\r\n        String ret = "";\r\n        \r\n        for (int i=1; i<= comp; i++) {\r\n            if(i==1 || i==comp)\r\n                ret = ret + desenhaLinha (comp)+"\\n";\r\n            else\r\n                ret = ret + desenhaLinhaVazada (comp)+"\\n";\r\n        }\r\n        return ret;\r\n    }\r\n    \r\n}\r\n', NULL, '2016-05-15 19:44:23', 0),
(233, 25, 43, 'TestaDesenho', '\r\n/**\r\n * Escreva a descrição da classe TestaDesenho aqui.\r\n * \r\n * @author (seu nome) \r\n * @version (número de versão ou data)\r\n */\r\npublic class TestaDesenho\r\n{\r\n    public static void main (String args[]){\r\n        Desenho d1 = new Desenho ("X");\r\n        System.out.println ("  Quadrado\\n");\r\n        System.out.println (d1.desenhaQuadrado(5));\r\n        \r\n        Desenho d2 = new Desenho ("X");\r\n        System.out.println ("  Linha Vazada:\\n");\r\n        System.out.println (d2.desenhaLinhaVazada(5));\r\n        System.out.println ("\\n");\r\n        \r\n        Desenho d3 = new Desenho ("X");\r\n        System.out.println ("  Quadrado Vazado\\n");\r\n        System.out.println (d3.desenhaQuadradoVazado(5));\r\n    }\r\n}\r\n', NULL, '2016-05-15 19:45:09', 0),
(234, 26, 43, 'Tabuada', '\r\n/**\r\n * Write a description of class Tabuada here.\r\n * \r\n * @author Marcos Roberto Souza \r\n * @version 13/05/2016\r\n */\r\npublic class Tabuada\r\n{\r\n    private int numero;\r\n    \r\n    public Tabuada (int numero){\r\n        this.numero = numero;\r\n    }\r\n    \r\n    public Tabuada (){\r\n        this.numero = 0;\r\n    }\r\n    \r\n    public void setNumero (int setNumero){\r\n        this.numero = setNumero;\r\n    }\r\n    \r\n    public int getNumero () {\r\n        return numero;\r\n    }\r\n    \r\n    public String calculaTabuada () {\r\n        String ret = "";\r\n        for (int i=1; i<= 10; i++) {\r\n            int resultado = numero*i;\r\n            ret = ret+numero+" X "+i+" = "+resultado+"\\n";\r\n        }\r\n        \r\n        return ret;\r\n    }\r\n}\r\n', '\r\n/**\r\n * Write a description of class Tabuada here.\r\n * \r\n * @author Marcos Roberto Souza \r\n * @version 13/05/2016\r\n */\r\npublic class Tabuada\r\n{\r\n    private int numero;\r\n    \r\n    public Tabuada (int numero){\r\n        this.numero = numero;\r\n    }\r\n    \r\n    public Tabuada (){\r\n        this.numero = 0;\r\n    }\r\n    \r\n    public void setNumero (int setNumero){\r\n        this.numero = setNumero;\r\n    }\r\n    \r\n    public int getNumero () {\r\n        return numero;\r\n    }\r\n    \r\n    public String calculaTabuada () {\r\n        String ret = "";\r\n        for (int i=1; i<= 10; i++) {\r\n            int resultado = numero*i;\r\n            ret = ret+numero+" X "+i+" = "+resultado;\r\n        }\r\n        \r\n        return ret;\r\n    }\r\n}\r\n', '2016-05-16 01:05:18', 0),
(235, 26, 43, 'Teclado', ' \r\n\r\nimport java.io.*;\r\n\r\n/** Classe que permite fazer leitura de dados do tecladeo */\r\n\r\npublic class Teclado\r\n{\r\n     private String s;\r\n     private InputStreamReader i = new InputStreamReader (System.in);\r\n     private BufferedReader d = new BufferedReader(i);\r\n\r\n     /**\r\n        Le um inteiro.\r\n        @return int\r\n     */\r\n     public int leInt ()\r\n     {   System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         int a = 0;\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser inteiro: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um inteiro, com mensagem.\r\n        @return int\r\n     */\r\n     public int leInt (String msg)\r\n     { \r\n         int a = 0;\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: "+e );\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser inteiro: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um double.\r\n        @return double\r\n     */\r\n     public double leDouble()\r\n     { \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         double a = 0;\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Double.parseDouble(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser numero: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um double, com mensagem.\r\n        @return double\r\n     */\r\n     public double leDouble(String msg)\r\n     {   double a = 0;\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Double.parseDouble(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser numero: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um string.\r\n        @return String\r\n     */\r\n     public String leString()\r\n     { \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         s = "";\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            \r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (s);\r\n     }\r\n\r\n     /**\r\n        Le um string. com mensagem.\r\n        @return String\r\n     */\r\n     public String leString(String msg)\r\n     {   s = "";\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n            s = d.readLine();\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (s);\r\n     }\r\n        \r\n    /**\r\n        Le um char.\r\n        @return char\r\n     */\r\n     public char leChar()\r\n     {  \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         s = "";\r\n         char c='' '';\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            c = s.charAt(0);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (c);\r\n     }\r\n          \r\n     /**\r\n        Le um char com mensagem.\r\n        @return char\r\n     */\r\n     public char leChar(String msg)\r\n     {   s = "";\r\n         char c='' '';\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            c = s.charAt(0);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (c);\r\n     }\r\n     \r\n     \r\n    \r\n    }\r\n\r\n', NULL, '2016-05-16 00:47:09', 0),
(236, 26, 43, 'TestaTabuada', '\r\n/**\r\n * Write a description of class TestaTabuada here.\r\n * \r\n * @author (your name) \r\n * @version (a version number or a date)\r\n */\r\npublic class TestaTabuada\r\n{\r\n    public static void main (String args[]){\r\n        Teclado teclado = new Teclado();\r\n        \r\n        int numero = teclado.leInt ("Digite um numero ou -1 para sair: ");\r\n        while (numero != -1){\r\n            System.out.println("\\f");\r\n            Tabuada t1 = new Tabuada(numero);\r\n            System.out.println ("--------Tabuada do Numero "+numero+"--------");\r\n            System.out.println (t1.calculaTabuada());\r\n            numero = teclado.leInt ("Digite um numero ou -1 para sair: ");\r\n            \r\n            if (numero == -1)\r\n            System.out.println("\\f");\r\n    }\r\n}\r\n}\r\n', '\r\n/**\r\n * Write a description of class TestaTabuada here.\r\n * \r\n * @author (your name) \r\n * @version (a version number or a date)\r\n */\r\npublic class TestaTabuada\r\n{\r\n    public static void main (String args[]){\r\n        Teclado teclado = new Teclado();\r\n        \r\n        int numero = teclado.leInt ("Digite um numero ou -1 para sair: ");\r\n        while (numero != -1){\r\n            System.out.println("\\f");\r\n            Tabuada t1 = new Tabuada(numero);\r\n            System.out.println ("--------Tabuada do Numero "+numero+"--------");\r\n            System.out.println (t1.calculaTabuada());\r\n            numero = teclado.leInt ("Digite um numero ou -1 para sair: ");\r\n            \r\n            if (numero == -1)\r\n            System.out.println("\\f");\r\n    }\r\n}\r\n}\r\n', '2016-05-16 01:04:51', 0),
