(245, 20, 33, 'Ponto', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\n/**\r\n * Escreva a descriÃ§Ã£o da classe Ponto aqui.\r\n * \r\n * @author Ceci­lia \r\n * @version Maio/2016\r\n */\r\n\r\npublic class Ponto{\r\n    private int x;\r\n    private int y;\r\n\r\n    //construtor sem nenhum argumento\r\n    public Ponto(){\r\n        x = 0;\r\n        y = 0;\r\n    }\r\n    \r\n    //construtor que inicializa os atributos da classe\r\n    public Ponto(int x, int y){\r\n        this.x = x;\r\n        this.y = y;    \r\n    }\r\n    \r\n    //mÃ©todos de acesso (get)\r\n    public int getX(){\r\n        return x;\r\n    }\r\n    \r\n    public int getY(){\r\n        return y;\r\n    }\r\n    \r\n    //mÃ©todos modificadores(set)\r\n    public void setX(int novoX){\r\n        x = novoX;\r\n    }\r\n    \r\n    public void setY(int novoY){\r\n        y = novoY;\r\n    }\r\n    \r\n}\r\n', NULL, '2016-05-17 18:53:04', 0),
(246, 20, 33, 'Reta', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\n/**\r\n * Escreva a descrição da classe Reta aqui.\r\n * \r\n * @author Ceci­lia \r\n * @version Maio/2016\r\n */\r\n\r\npublic class Reta{\r\n    private Ponto ponto1;\r\n    private Ponto ponto2;\r\n\r\n    //construtor sem nenhum argumento\r\n    public Reta(){\r\n        ponto1 = 0;\r\n        ponto2 = 0;\r\n    }\r\n    \r\n    //construtor que inicializa os atributos da classe\r\n    public Reta(Ponto ponto1, Ponto ponto2){\r\n        this.ponto1 = ponto1;\r\n        this.ponto2 = ponto2;    \r\n    }\r\n    \r\n    //méodos de acesso (get)\r\n    public int getPonto1(){\r\n        return ponto1;\r\n    }\r\n    \r\n    public int getPonto2(){\r\n        return ponto2;\r\n    }\r\n    \r\n    //métodos modificadores(set)\r\n    public void setPonto1(int ponto1){\r\n        ponto1 = novoPonto1;\r\n    }\r\n    \r\n    public void setPonto2(int ponto2){\r\n        ponto2 = novoPonto2;\r\n    }\r\n\r\n}\r\n', NULL, '2016-05-17 19:04:57', 0),
(247, 24, 33, 'NumerosPares', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\npublic class NumerosPares{\r\n    private int n;\r\n    \r\n    //construtor sem nenhum argumento\r\n    public NumerosPares(){\r\n        n = 0;\r\n    }\r\n    \r\n    //construtor que inicializa os atributos da classe\r\n    public NumerosPares(int n){\r\n        this.n = n;\r\n    }\r\n    \r\n    //mÃ©todos de acesso (get)\r\n    public int getN(){\r\n        return n;\r\n    }\r\n\r\n    //mÃ©todos modificadores(set)\r\n    public void setN(int novoN){\r\n        n = novoN;\r\n    }\r\n	\r\n	public String geraPares(){		\r\n		int inicio = 2;\r\n		String res = "";\r\n		\r\n		while(inicio <= n){\r\n			res += inicio + ", ";			\r\n			inicio += 2;\r\n		}		\r\n		res = res.substring(0, res.length()-2);		\r\n		return res;\r\n	}\r\n	\r\n	public int somaNumeros(){\r\n		int soma = 0;\r\n		\r\n		for(int i=1; i<=n; i++){\r\n			soma += i;\r\n		}\r\n		return soma;\r\n	}   \r\n}\r\n', NULL, '2016-05-17 19:17:44', 0),
(249, 22, 9, 'SocioAtleta', 'public class SocioAtleta extends Socio {\r\n\r\n    private String categoria;\r\n\r\n    public SocioAtleta() {\r\n        super();\r\n        this.categoria = "Mirim";\r\n    }\r\n\r\n    public SocioAtleta(int numero, int idade, String nome) {\r\n        super(numero, idade, nome);\r\n        this.atualizaCategoria();\r\n    }\r\n\r\n    @Override\r\n    public void setIdade(int idade) {\r\n        super.setIdade(idade);\r\n        this.atualizaCategoria();\r\n    }\r\n\r\n    private void atualizaCategoria() {\r\n\r\n        if (this.getIdade() <= 10) {\r\n            this.categoria = "Mirim";\r\n        } else if (this.getIdade() <= 15) {\r\n            this.categoria = "Infantil";\r\n        } else if (this.getIdade() <= 20) {\r\n            this.categoria = "Juvenil";\r\n        } else if (this.getIdade() <= 40) {\r\n            this.categoria = "Adulto";\r\n        } else {\r\n            this.categoria = "Master";\r\n        }\r\n    }\r\n\r\n    @Override\r\n    public String toString() {\r\n        return super.toString() + ", " + categoria;\r\n    }\r\n\r\n}\r\n', 'public class SocioAtleta extends Socio {\r\n\r\n    private String categoria;\r\n\r\n    public SocioAtleta() {\r\n        super();\r\n    }\r\n\r\n    public SocioAtleta(int numero, int idade, String nome) {\r\n        super(numero, idade, nome);\r\n        this.atualizaCategoria();\r\n    }\r\n\r\n    @Override\r\n    public void setIdade(int idade) {\r\n        super.setIdade(idade);\r\n        this.atualizaCategoria();\r\n    }\r\n\r\n    private void atualizaCategoria() {\r\n\r\n        if (this.getIdade() <= 10) {\r\n            this.categoria = "Mirim";\r\n        } else if (this.getIdade() <= 15) {\r\n            this.categoria = "Infantil";\r\n        } else if (this.getIdade() <= 20) {\r\n            this.categoria = "Juvenil";\r\n        } else if (this.getIdade() <= 40) {\r\n            this.categoria = "Adulto";\r\n        } else {\r\n            this.categoria = "Master";\r\n        }\r\n    }\r\n\r\n    @Override\r\n    public String toString() {\r\n        return super.toString() + ", " + categoria;\r\n    }\r\n\r\n}\r\n', '2016-05-18 00:13:12', 0),
(250, 22, 9, 'Socio', 'public class Socio {\r\n\r\n    private int numero;\r\n    private int idade;\r\n    private String nome;\r\n\r\n    public Socio() {\r\n        this.numero = 0;\r\n        this.idade = 0;\r\n        this.nome = "";\r\n    }\r\n\r\n    public Socio(int numero, int idade, String nome) {\r\n        this.numero = numero;\r\n        this.idade = idade;\r\n        this.nome = nome;\r\n    }\r\n\r\n    public int getNumero() {\r\n        return numero;\r\n    }\r\n\r\n    public void setNumero(int numero) {\r\n        this.numero = numero;\r\n    }\r\n\r\n    public int getIdade() {\r\n        return idade;\r\n    }\r\n\r\n    public void setIdade(int idade) {\r\n        this.idade = idade;\r\n    }\r\n\r\n    public String getNome() {\r\n        return nome;\r\n    }\r\n\r\n    public void setNome(String nome) {\r\n        this.nome = nome;\r\n    }\r\n\r\n    @Override\r\n    public String toString() {\r\n        return numero + ", " + idade + ", " + nome;\r\n    }\r\n\r\n}\r\n', NULL, '2016-05-18 00:12:01', 0),
(251, 21, 60, 'Ponto', 'public class Ponto {\r\n\r\n    private int x;\r\n    private int y;\r\n    \r\n    public Ponto()\r\n    {\r\n        this.x = 0;\r\n        this.y = 0;\r\n    }\r\n    \r\n    public Ponto(int x, int y) {\r\n        this.x = x;\r\n        this.y = y;\r\n    }\r\n\r\n    public int getX() {\r\n        return x;\r\n    }\r\n\r\n    public void setX(int x) {\r\n        this.x = x;\r\n    }\r\n\r\n    public int getY() {\r\n        return y;\r\n    }\r\n\r\n    public void setY(int y) {\r\n        this.y = y;\r\n    }\r\n\r\n    @Override\r\n    public String toString() {\r\n        return "(" + x + ", " + y + '')'';\r\n    }\r\n}\r\n', NULL, '2018-01-06 19:01:23', 0),
(252, 22, 60, 'Socio', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass Socio\r\n{\r\n    int numero;\r\n    int idade;\r\n    String nome;\r\n    \r\n    public Socio(){\r\n        this.numero = 0;\r\n        this.idade = 0;\r\n        this.nome = "";\r\n    }\r\n    public Socio(int numero, int idade, String nome){\r\n        this.numero = numero;\r\n        this.idade = idade;\r\n        this.nome = nome;\r\n    }\r\n    \r\n    public void setNumero(int numero){\r\n        this.numero = numero;\r\n    }\r\n    public void setIdade(int idade){\r\n        this.idade = idade;\r\n    }\r\n    public void setNome(String nome){\r\n        this.nome = nome;\r\n    }\r\n    public int getNumero(){\r\n        return numero;\r\n    }\r\n    public int getIdade(){\r\n        return idade;\r\n    }\r\n    public String getNome(){\r\n        return nome;\r\n    }\r\n    \r\n    public String toString(){\r\n        return numero+","+idade+","+nome;\r\n    }\r\n    \r\n   // Coloque aqui o seu código\r\n}', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass Socio\r\n{\r\n    int numero;\r\n    int idade;\r\n    String nome;\r\n    \r\n    public Socio(){\r\n        this.numero = 0;\r\n        this.idade = 0;\r\n        this.nome = "";\r\n    }\r\n    \r\n    public void setNumero(int numero){\r\n        this.numero = numero;\r\n    }\r\n    public void setIdade(int idade){\r\n        this.idade = idade;\r\n    }\r\n    public void setNome(String nome){\r\n        this.nome = nome;\r\n    }\r\n    public int getNumero(){\r\n        return numero;\r\n    }\r\n    public int getIdade(){\r\n        return idade;\r\n    }\r\n    public String getNome(){\r\n        return nome;\r\n    }\r\n    \r\n    public String toString(){\r\n        return numero+","+idade+","+nome;\r\n    }\r\n    \r\n   // Coloque aqui o seu código\r\n}', '2018-01-06 19:27:23', 0),
(253, 22, 60, 'SocioAtleta', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass SocioAtleta extends Socio\r\n{\r\n    String categoria;\r\n   public SocioAtleta(){\r\n       this.numero = 0;\r\n       this.idade = 0;\r\n       this.nome = "";\r\n       this.categoria = "Mirim";\r\n   }\r\n   public void setIdade(int idade){\r\n       this.idade = idade;\r\n       if(idade <= 10){\r\n           categoria = "Mirim";\r\n       }\r\n       else if(idade >= 11 && idade <= 15){\r\n           categoria = "Infantil";\r\n       }\r\n       else if(idade >= 16 && idade <= 20){\r\n           categoria = "Juvenil";\r\n       }\r\n       else if(idade >= 21 && idade <= 40){\r\n           categoria = "Adulto";\r\n       }\r\n       else{\r\n           categoria = "Master";\r\n       }\r\n   }\r\n   \r\n   public String toString(){\r\n       return numero + "," + idade + "," + nome +"," + categoria;\r\n   }\r\n   \r\n   public SocioAtleta(int numero, int idade, String nome){\r\n       this.numero = numero;\r\n       this.idade = idade;\r\n       this.nome = nome;\r\n       setIdade(idade);\r\n   }\r\n   \r\n}', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass SocioAtleta extends Socio\r\n{\r\n    String categoria;\r\n   public SocioAtleta(){\r\n       this.numero = 0;\r\n       this.idade = 0;\r\n       this.nome = "";\r\n       this.categoria = "Mirim";\r\n   }m\r\n   \r\n   public void setIdade(int idade){\r\n       this.idade = idade;\r\n       if(idade <= 10){\r\n           categoria = "Mirim";\r\n       }\r\n       else if(idade >= 11 && idade <= 15){\r\n           categoria = "Infantil";\r\n       }\r\n       else if(idade >= 16 && idade <= 20){\r\n           categoria = "Juvenil";\r\n       }\r\n       else if(idade >= 21 && idade <= 40){\r\n           categoria = "Adulto";\r\n       }\r\n       else{\r\n           categoria = "Master";\r\n       }\r\n   }\r\n   \r\n   public String toString(){\r\n       return numero + "," + idade + "," + nome +"," + categoria;\r\n   }\r\n   \r\n   public SocioAtleta(int numero, int idade, String nome){\r\n       this.numero = numero;\r\n       this.idade = idade;\r\n       this.nome = nome;\r\n       setIdade(idade);\r\n   }\r\n   \r\n}', '2018-01-06 23:56:51', 0),
