(253, 130, 'ArrayDePontos', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass ArrayDePontos\r\n{\r\n   private Ponto[] pontos; \r\n   \r\n   private Integer tamanho;\r\n   \r\n   public ArrayDePontos(Integer numMaxElem)\r\n   {\r\n       pontos = new Ponto[numMaxElem];\r\n      \r\n   }\r\n   \r\n   public Integer getTamanho(){\r\n       return this.tamanho;\r\n   }\r\n   \r\n   public void setTamanho(Integer num){\r\n       this.tamanho=num;\r\n   }\r\n   \r\n   public Ponto[] getPontos(){\r\n       return this.pontos;\r\n   }\r\n   \r\n   \r\n   public void inserirPonto(Ponto ponto){\r\n       \r\n       Boolean inserido = Boolean.FALSE;\r\n       for (int i = 0; i < this.pontos.length; i++) \r\n       {\r\n           if(pontos[i]==null){\r\n               this.pontos[i] = ponto;\r\n               this.tamanho++;\r\n               inserido = Boolean.TRUE;\r\n               return;\r\n           }\r\n        }\r\n        \r\n        if(!inserido){\r\n            Ponto[] copiaPontos = new Ponto[this.pontos.lenth()*2];\r\n            System.arraycopy(this.pontos, 0, copiaPontos, 0, copiaPontos.lenth());\r\n            \r\n            this.pontos=copiaPontos[];\r\n            \r\n            for (int i = 0; i < this.pontos.length; i++) \r\n            {\r\n                if(pontos[i]==null){\r\n                    this.pontos[i] = ponto;\r\n                    this.tamanho++;\r\n                    return;\r\n                }//fim if\r\n            }//fim for\r\n            \r\n        }//fim inserido\r\n    }//fim metodo\r\n   \r\n   public Ponto obtemPontoSuperior(){\r\n       \r\n       Ponto p = null;\r\n       \r\n       for (Ponto ponto : this.pontos) \r\n       {\r\n           if(p == null)\r\n           {\r\n            p = ponto;\r\n           }\r\n           else\r\n           {\r\n               if(ponto.getY() > p.getY())  \r\n               {\r\n                   p.setY(ponto.getY());\r\n               } \r\n           }\r\n           \r\n       }//fim for\r\n       \r\n       return p;\r\n			    \r\n   }//fim metodo\r\n   \r\n   public Ponto obtemPontoInferior(){\r\n       \r\n       Ponto p = null;\r\n       \r\n       for (Ponto ponto : this.pontos) \r\n       {\r\n           if(p == null)\r\n           {\r\n            p = ponto;\r\n           }\r\n           else\r\n           {\r\n               if(ponto.getY() < p.getY())  \r\n               {\r\n                   p.setY(ponto.getY());\r\n               } \r\n           }\r\n           \r\n       }//fim for\r\n       \r\n       return p;\r\n			    \r\n   }//fim metodo\r\n   \r\n   public Ponto obtemPontoMaisADireita(){\r\n       \r\n       Ponto p = null;\r\n       \r\n       for (Ponto ponto : this.pontos) \r\n       {\r\n           if(p == null)\r\n           {\r\n            p = ponto;\r\n           }\r\n           else\r\n           {\r\n               if(ponto.getX() > p.getY())  \r\n               {\r\n                   p.setX(ponto.getX());\r\n               } \r\n           }\r\n           \r\n       }//fim for\r\n       \r\n       return p;\r\n			    \r\n   }//fim metodo\r\n   \r\n   \r\n    public Ponto obtemPontoMaisAEsquerda(){\r\n       \r\n       Ponto p = null;\r\n       \r\n       for (Ponto ponto : this.pontos) \r\n       {\r\n           if(p == null)\r\n           {\r\n            p = ponto;\r\n           }\r\n           else\r\n           {\r\n               if(ponto.getX() < p.getX())  \r\n               {\r\n                   p.setX(ponto.getX());\r\n               } \r\n           }\r\n           \r\n       }//fim for\r\n       \r\n       return p;\r\n			    \r\n   }//fim metodo\r\n   \r\n   \r\n}//fim classe'),
(254, 131, 'Ponto', 'public class Ponto {\r\n\r\n    private int x;\r\n    private int y;\r\n    \r\n    public Ponto()\r\n    {\r\n        this.x = 0;\r\n        this.y = 0;\r\n    }\r\n    \r\n    public Ponto(int x, int y) {\r\n        this.x = x;\r\n        this.y = y;\r\n    }\r\n\r\n    public int getX() {\r\n        return x;\r\n    }\r\n\r\n    public void setX(int x) {\r\n        this.x = x;\r\n    }\r\n\r\n    public int getY() {\r\n        return y;\r\n    }\r\n\r\n    public void setY(int y) {\r\n        this.y = y;\r\n    }\r\n\r\n    @Override\r\n    public String toString() {\r\n        return "(" + x + ", " + y + '')'';\r\n    }\r\n}\r\n'),
(255, 131, 'ArrayDePontos', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass ArrayDePontos\r\n{\r\n   private Ponto[] pontos; \r\n   \r\n   private Integer tamanho;\r\n   \r\n   public ArrayDePontos(Integer numMaxElem)\r\n   {\r\n       pontos = new Ponto[numMaxElem];\r\n      \r\n   }\r\n   \r\n   public Integer getTamanho(){\r\n       return this.tamanho;\r\n   }\r\n   \r\n   public void setTamanho(Integer num){\r\n       this.tamanho=num;\r\n   }\r\n   \r\n   public Ponto[] getPontos(){\r\n       return this.pontos;\r\n   }\r\n   \r\n   \r\n   public void inserirPonto(Ponto ponto){\r\n       \r\n       Boolean inserido = Boolean.FALSE;\r\n       int cont = 0;\r\n       for (int i = 0; i < this.pontos.length; i++) \r\n       {\r\n           if(pontos[i]==null){\r\n               this.pontos[i] = ponto;\r\n               this.tamanho++;\r\n               inserido = Boolean.TRUE;\r\n           }else{\r\n               cont++;\r\n           }\r\n        }\r\n        \r\n        if(!inserido){\r\n            Ponto[] copiaPontos = new Ponto[this.pontos.lenth * 2];\r\n            System.arraycopy(this.pontos, 0, copiaPontos, 0,  Math.min (this.pontos.length, copiaPontos.length));\r\n            \r\n            this.pontos=copiaPontos;\r\n            copiaPontos=null;\r\n            \r\n            this.pontos[cont] =  ponto;\r\n         }//fim if\r\n            \r\n        }//fim inserido\r\n    }//fim metodo\r\n   \r\n   public Ponto obtemPontoSuperior(){\r\n       \r\n       Ponto p = null;\r\n       \r\n       for (Ponto ponto : this.pontos) \r\n       {\r\n           if(p == null)\r\n           {\r\n            p = ponto;\r\n           }\r\n           else\r\n           {\r\n               if(ponto.getY() > p.getY())  \r\n               {\r\n                   p.setY(ponto.getY());\r\n               } \r\n           }\r\n           \r\n       }//fim for\r\n       \r\n       return p;\r\n			    \r\n   }//fim metodo\r\n   \r\n   public Ponto obtemPontoInferior(){\r\n       \r\n       Ponto p = null;\r\n       \r\n       for (Ponto ponto : this.pontos) \r\n       {\r\n           if(p == null)\r\n           {\r\n            p = ponto;\r\n           }\r\n           else\r\n           {\r\n               if(ponto.getY() < p.getY())  \r\n               {\r\n                   p.setY(ponto.getY());\r\n               } \r\n           }\r\n           \r\n       }//fim for\r\n       \r\n       return p;\r\n			    \r\n   }//fim metodo\r\n   \r\n   public Ponto obtemPontoMaisADireita(){\r\n       \r\n       Ponto p = null;\r\n       \r\n       for (Ponto ponto : this.pontos) \r\n       {\r\n           if(p == null)\r\n           {\r\n            p = ponto;\r\n           }\r\n           else\r\n           {\r\n               if(ponto.getX() > p.getY())  \r\n               {\r\n                   p.setX(ponto.getX());\r\n               } \r\n           }\r\n           \r\n       }//fim for\r\n       \r\n       return p;\r\n			    \r\n   }//fim metodo\r\n   \r\n   \r\n    public Ponto obtemPontoMaisAEsquerda(){\r\n       \r\n       Ponto p = null;\r\n       \r\n       for (Ponto ponto : this.pontos) \r\n       {\r\n           if(p == null)\r\n           {\r\n            p = ponto;\r\n           }\r\n           else\r\n           {\r\n               if(ponto.getX() < p.getX())  \r\n               {\r\n                   p.setX(ponto.getX());\r\n               } \r\n           }\r\n           \r\n       }//fim for\r\n       \r\n       return p;\r\n			    \r\n   }//fim metodo\r\n   \r\n   \r\n}//fim classe'),
(256, 132, 'Ponto', 'public class Ponto {\r\n\r\n    private int x;\r\n    private int y;\r\n    \r\n    public Ponto()\r\n    {\r\n        this.x = 0;\r\n        this.y = 0;\r\n    }\r\n    \r\n    public Ponto(int x, int y) {\r\n        this.x = x;\r\n        this.y = y;\r\n    }\r\n\r\n    public int getX() {\r\n        return x;\r\n    }\r\n\r\n    public void setX(int x) {\r\n        this.x = x;\r\n    }\r\n\r\n    public int getY() {\r\n        return y;\r\n    }\r\n\r\n    public void setY(int y) {\r\n        this.y = y;\r\n    }\r\n\r\n    @Override\r\n    public String toString() {\r\n        return "(" + x + ", " + y + '')'';\r\n    }\r\n}\r\n'),
(257, 132, 'ArrayDePontos', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass ArrayDePontos\r\n{\r\n   private Ponto[] pontos; \r\n   \r\n   private Integer tamanho;\r\n   \r\n   public ArrayDePontos(Integer numMaxElem)\r\n   {\r\n       pontos = new Ponto[numMaxElem];\r\n      \r\n   }\r\n   \r\n   public Integer getTamanho(){\r\n       return this.tamanho;\r\n   }\r\n   \r\n   public void setTamanho(Integer num){\r\n       this.tamanho=num;\r\n   }\r\n   \r\n   public Ponto[] getPontos(){\r\n       return this.pontos;\r\n   }\r\n   \r\n   \r\n   public void inserirPonto(Ponto ponto){\r\n       \r\n       Boolean inserido = Boolean.FALSE;\r\n       int cont = 0;\r\n       for (int i = 0; i < this.pontos.length; i++) \r\n       {\r\n           if(pontos[i]==null){\r\n               this.pontos[i] = ponto;\r\n               this.tamanho++;\r\n               inserido = Boolean.TRUE;\r\n           }else{\r\n               cont++;\r\n           }\r\n        }\r\n        \r\n        if(!inserido){\r\n            Ponto[] copiaPontos = new Ponto[this.pontos.lenth * 2];\r\n            System.arraycopy(this.pontos, 0, copiaPontos, 0,  Math.min (this.pontos.length, copiaPontos.length));\r\n            \r\n            this.pontos=copiaPontos;\r\n            copiaPontos=null;\r\n            \r\n            this.pontos[cont] =  ponto;\r\n         }//fim if\r\n            \r\n        }//fim inserido\r\n    }//fim metodo\r\n   \r\n   public int obtemPontoSuperior(){\r\n       \r\n       //Ponto p = null;\r\n       int p = null;\r\n       \r\n       for (Ponto ponto : this.pontos) \r\n       {\r\n           if(p == null)\r\n           {\r\n            //p = ponto;\r\n            ponto.getY();\r\n           }\r\n           else\r\n           {\r\n               if(ponto.getY() > p)  \r\n               {\r\n                   p=ponto.getY();\r\n               } \r\n           }\r\n           \r\n       }//fim for\r\n       \r\n       return p;\r\n			    \r\n   }//fim metodo\r\n   \r\n   public Ponto obtemPontoInferior(){\r\n       \r\n       Ponto p = null;\r\n       \r\n       for (Ponto ponto : this.pontos) \r\n       {\r\n           if(p == null)\r\n           {\r\n            p = ponto;\r\n           }\r\n           else\r\n           {\r\n               if(ponto.getY() < p.getY())  \r\n               {\r\n                   p.setY(ponto.getY());\r\n               } \r\n           }\r\n           \r\n       }//fim for\r\n       \r\n       return p;\r\n			    \r\n   }//fim metodo\r\n   \r\n   public Ponto obtemPontoMaisADireita(){\r\n       \r\n       Ponto p = null;\r\n       \r\n       for (Ponto ponto : this.pontos) \r\n       {\r\n           if(p == null)\r\n           {\r\n            p = ponto;\r\n           }\r\n           else\r\n           {\r\n               if(ponto.getX() > p.getY())  \r\n               {\r\n                   p.setX(ponto.getX());\r\n               } \r\n           }\r\n           \r\n       }//fim for\r\n       \r\n       return p;\r\n			    \r\n   }//fim metodo\r\n   \r\n   \r\n    public Ponto obtemPontoMaisAEsquerda(){\r\n       \r\n       Ponto p = null;\r\n       \r\n       for (Ponto ponto : this.pontos) \r\n       {\r\n           if(p == null)\r\n           {\r\n            p = ponto;\r\n           }\r\n           else\r\n           {\r\n               if(ponto.getX() < p.getX())  \r\n               {\r\n                   p.setX(ponto.getX());\r\n               } \r\n           }\r\n           \r\n       }//fim for\r\n       \r\n       return p;\r\n			    \r\n   }//fim metodo\r\n   \r\n   \r\n}//fim classe'),
(258, 133, 'Ponto', 'public class Ponto {\r\n\r\n    private int x;\r\n    private int y;\r\n    \r\n    public Ponto()\r\n    {\r\n        this.x = 0;\r\n        this.y = 0;\r\n    }\r\n    \r\n    public Ponto(int x, int y) {\r\n        this.x = x;\r\n        this.y = y;\r\n    }\r\n\r\n    public int getX() {\r\n        return x;\r\n    }\r\n\r\n    public void setX(int x) {\r\n        this.x = x;\r\n    }\r\n\r\n    public int getY() {\r\n        return y;\r\n    }\r\n\r\n    public void setY(int y) {\r\n        this.y = y;\r\n    }\r\n\r\n    @Override\r\n    public String toString() {\r\n        return "(" + x + ", " + y + '')'';\r\n    }\r\n}\r\n');
