(333, 170, 'ArrayDePontos', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass ArrayDePontos {\r\n    Ponto[] pontos;\r\n    int tamanho;\r\n    \r\n    public ArrayDePontos(int nValores){\r\n        this.pontos = new Ponto[nValores];\r\n    }\r\n    \r\n    public int getTamanho(){\r\n        return this.tamanho;\r\n    }\r\n    \r\n    public void inserirPonto(Ponto ponto){\r\n        for(int i=0; i < this.pontos.length; i++){\r\n            if(this.pontos[i] == null){\r\n                this.pontos[i] = ponto;\r\n                tamanho++;\r\n            }\r\n        }\r\n    }\r\n    \r\n    public Ponto obtemPontoSuperior(){\r\n        Ponto pontoMaior = this.pontos[0];\r\n        for(int i=1; i<=this.pontos.length; i++){\r\n            if(this.pontos[i].getY() > pontoMaior.getY()){\r\n                pontoMaior = this.pontos[i];\r\n            }\r\n        }\r\n        return pontoMaior;\r\n    }\r\n    \r\n    public Ponto obtemPontoInferior(){\r\n        Ponto pontoMenor = this.pontos[0];\r\n        for(int i=1; i<=this.pontos.length; i++){\r\n            if(this.pontos[i].getY() < pontoMenor.getY()){\r\n                pontoMenor = this.pontos[i];\r\n            }\r\n        }\r\n        return pontoMenor;\r\n    }\r\n    \r\n     public Ponto obtemPontoMaisADireita(){\r\n        Ponto pontoMaior = this.pontos[0];\r\n        for(int i=1; i<=this.pontos.length; i++){\r\n            if(this.pontos[i].getX() > pontoMaior.getX()){\r\n                pontoMaior = this.pontos[i];\r\n            }\r\n        }\r\n        return pontoMaior;\r\n    }\r\n    \r\n    public Ponto obtemPontoMaisAEsquerda(){\r\n        Ponto pontoMenor = this.pontos[0];\r\n        for(int i=1; i<=this.pontos.length; i++){\r\n            if(this.pontos[i].getX() < pontoMenor.getX()){\r\n                pontoMenor = this.pontos[i];\r\n            }\r\n        }\r\n        return pontoMenor;\r\n    }\r\n    \r\n}'),
(338, 173, 'Socio', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass Socio\r\n{\r\n   private int numero;\r\n   private int idade;\r\n   private String nome;\r\n   \r\n   public Socio(){\r\n       this.numero = 0;\r\n       this.idade = 0;\r\n       this.nome = "";\r\n   }\r\n   \r\n   public Socio(int numero, int idade, String nome){\r\n       this.numero = numero;\r\n       this.idade = idade;\r\n       this.nome = nome;\r\n   }\r\n   \r\n   public void setNumero(int numero){\r\n       this.numero = numero;\r\n   }\r\n   \r\n   public int getNumero(){\r\n       return this.numero;\r\n   }\r\n   \r\n   public void setIdade(int idade){\r\n       this.idade = idade;\r\n   }\r\n   \r\n   public int getIdade(){\r\n       return this.idade;\r\n   }\r\n   \r\n   public void setNome(String nome){\r\n       this.nome = nome;\r\n   }\r\n   \r\n   public String getNome(){\r\n       return this.nome;\r\n   }\r\n   \r\n   public String toString(){\r\n       return (this.numero + ", " + this.idade + ", " + this.nome);\r\n   }\r\n}'),
(339, 173, 'SocioAtleta', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass SocioAtleta extends Socio\r\n{\r\n   private String categoria;\r\n   \r\n   public SocioAtleta(){\r\n       super();\r\n       this.categoria = "Mirim";\r\n   }\r\n   \r\n   public SocioAtleta(int numero, int idade, String nome){\r\n       super(numero, idade, nome);\r\n       this.categoria = this.obterCategoriaPelaIdade(idade);\r\n   }\r\n   \r\n   private String obterCategoriaPelaIdade(int idade){\r\n       if(idade <= 10) return "Mirim";\r\n       else if(idade <= 15) return "Infantil";\r\n       else if(idade <= 20) return "Juvenil";\r\n       else if(idade <= 40) return "Adulto";\r\n       else return "Master";\r\n   }\r\n   \r\n   @Override\r\n   public void setIdade(int idade){\r\n       super.setIdade(idade);\r\n       this.categoria = this.obterCategoriaPelaIdade(idade);\r\n   }\r\n   \r\n   public String toString(){\r\n       return (super.toString() + ", " + this.categoria);\r\n   }\r\n}'),
(340, 174, 'Ponto', 'public class Ponto {\r\n\r\n    private int x;\r\n    private int y;\r\n    \r\n    public Ponto()\r\n    {\r\n        this.x = 0;\r\n        this.y = 0;\r\n    }\r\n    \r\n    public Ponto(int x, int y) {\r\n        this.x = x;\r\n        this.y = y;\r\n    }\r\n\r\n    public int getX() {\r\n        return x;\r\n    }\r\n\r\n    public void setX(int x) {\r\n        this.x = x;\r\n    }\r\n\r\n    public int getY() {\r\n        return y;\r\n    }\r\n\r\n    public void setY(int y) {\r\n        this.y = y;\r\n    }\r\n\r\n    @Override\r\n    public String toString() {\r\n        return "(" + x + ", " + y + '')'';\r\n    }\r\n}\r\n'),
(341, 174, 'ArrayDePontos', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass ArrayDePontos {\r\n    Ponto[] pontos;\r\n    int tamanho;\r\n    \r\n    public ArrayDePontos(int nValores){\r\n        this.pontos = new Ponto[nValores];\r\n    }\r\n    \r\n    public int getTamanho(){\r\n        return this.tamanho;\r\n    }\r\n    \r\n    public void inserirPonto(Ponto ponto){\r\n        for(int i=0; i < this.pontos.length; i++){\r\n            if(this.pontos[i] == null){\r\n                this.pontos[i] = ponto;\r\n                tamanho++;\r\n                break;\r\n            }\r\n        }\r\n    }\r\n    \r\n    public Ponto obtemPontoSuperior(){\r\n        Ponto pontoMaior = this.pontos[0];\r\n        for(int i=1; i<=this.pontos.length; i++){\r\n            if(this.pontos[i].getY() > pontoMaior.getY()){\r\n                pontoMaior = this.pontos[i];\r\n            }\r\n        }\r\n        return pontoMaior;\r\n    }\r\n    \r\n    public Ponto obtemPontoInferior(){\r\n        Ponto pontoMenor = this.pontos[0];\r\n        for(int i=1; i<=this.pontos.length; i++){\r\n            if(this.pontos[i].getY() < pontoMenor.getY()){\r\n                pontoMenor = this.pontos[i];\r\n            }\r\n        }\r\n        return pontoMenor;\r\n    }\r\n    \r\n     public Ponto obtemPontoMaisADireita(){\r\n        Ponto pontoMaior = this.pontos[0];\r\n        for(int i=1; i<=this.pontos.length; i++){\r\n            if(this.pontos[i].getX() > pontoMaior.getX()){\r\n                pontoMaior = this.pontos[i];\r\n            }\r\n        }\r\n        return pontoMaior;\r\n    }\r\n    \r\n    public Ponto obtemPontoMaisAEsquerda(){\r\n        Ponto pontoMenor = this.pontos[0];\r\n        for(int i=1; i<=this.pontos.length; i++){\r\n            if(this.pontos[i].getX() < pontoMenor.getX()){\r\n                pontoMenor = this.pontos[i];\r\n            }\r\n        }\r\n        return pontoMenor;\r\n    }\r\n    \r\n}'),
(342, 175, 'Ponto', 'public class Ponto {\r\n\r\n    private int x;\r\n    private int y;\r\n    \r\n    public Ponto()\r\n    {\r\n        this.x = 0;\r\n        this.y = 0;\r\n    }\r\n    \r\n    public Ponto(int x, int y) {\r\n        this.x = x;\r\n        this.y = y;\r\n    }\r\n\r\n    public int getX() {\r\n        return x;\r\n    }\r\n\r\n    public void setX(int x) {\r\n        this.x = x;\r\n    }\r\n\r\n    public int getY() {\r\n        return y;\r\n    }\r\n\r\n    public void setY(int y) {\r\n        this.y = y;\r\n    }\r\n\r\n    @Override\r\n    public String toString() {\r\n        return "(" + x + ", " + y + '')'';\r\n    }\r\n}\r\n'),
(343, 175, 'ArrayDePontos', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass ArrayDePontos {\r\n    Ponto[] pontos;\r\n    int tamanho;\r\n    \r\n    public ArrayDePontos(int nValores){\r\n        this.pontos = new Ponto[nValores];\r\n    }\r\n    \r\n    public int getTamanho(){\r\n        return this.tamanho;\r\n    }\r\n    \r\n    public void inserirPonto(Ponto ponto){\r\n        for(int i=0; i < this.pontos.length; i++){\r\n            if(this.pontos[i] == null){\r\n                this.pontos[i] = ponto;\r\n                tamanho++;\r\n                break;\r\n            }\r\n        }\r\n    }\r\n    \r\n    public Ponto obtemPontoSuperior(){\r\n        Ponto pontoMaior = this.pontos[0];\r\n        for(int i=1; i<this.pontos.length; i++){\r\n            if(this.pontos[i].getY() > pontoMaior.getY()){\r\n                pontoMaior = this.pontos[i];\r\n            }\r\n        }\r\n        return pontoMaior;\r\n    }\r\n    \r\n    public Ponto obtemPontoInferior(){\r\n        Ponto pontoMenor = this.pontos[0];\r\n        for(int i=1; i<this.pontos.length; i++){\r\n            if(this.pontos[i].getY() < pontoMenor.getY()){\r\n                pontoMenor = this.pontos[i];\r\n            }\r\n        }\r\n        return pontoMenor;\r\n    }\r\n    \r\n     public Ponto obtemPontoMaisADireita(){\r\n        Ponto pontoMaior = this.pontos[0];\r\n        for(int i=1; i<this.pontos.length; i++){\r\n            if(this.pontos[i].getX() > pontoMaior.getX()){\r\n                pontoMaior = this.pontos[i];\r\n            }\r\n        }\r\n        return pontoMaior;\r\n    }\r\n    \r\n    public Ponto obtemPontoMaisAEsquerda(){\r\n        Ponto pontoMenor = this.pontos[0];\r\n        for(int i=1; i<this.pontos.length; i++){\r\n            if(this.pontos[i].getX() < pontoMenor.getX()){\r\n                pontoMenor = this.pontos[i];\r\n            }\r\n        }\r\n        return pontoMenor;\r\n    }\r\n    \r\n}'),
