(362, 189, 'Socio', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass Socio {\r\n	\r\n	private String nome;\r\n	private int idade;\r\n	private int numero;\r\n	\r\n	public Socio() {\r\n		this.numero = 0;		\r\n		this.idade = 0;\r\n		this.nome = null;\r\n	}\r\n	\r\n	public Socio(int numero, int idade, String nome){\r\n		this.numero = numero;\r\n		this.idade = idade;\r\n		this.nome = nome;\r\n	}\r\n\r\n	public String getNome() {\r\n		return nome;\r\n	}\r\n\r\n	public void setNome(String nome) {\r\n		this.nome = nome;\r\n	}\r\n\r\n	public int getIdade() {\r\n		return idade;\r\n	}\r\n\r\n	public void setIdade(int idade) {\r\n		this.idade = idade;\r\n	}\r\n\r\n	public int getNumero() {\r\n		return numero;\r\n	}\r\n\r\n	public void setNumero(int numero) {\r\n		this.numero = numero;\r\n	}\r\n	\r\n	public String toString(){\r\n		return this.numero + ", " + this.idade + ", " + this.nome;\r\n	}\r\n\r\n}'),
(363, 189, 'SocioAtleta', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass SocioAtleta extends Socio {\r\n    \r\n    private String categoria;\r\n	\r\n	public SocioAtleta(){\r\n		super();\r\n		this.categoria = "Mirim";\r\n	}\r\n	\r\n	public SocioAtleta(int numero, int idade, String nome){\r\n		super(numero, idade, nome);\r\n		if(super.getIdade() <=10){\r\n			this.categoria = "Mirim";\r\n		} else if(super.getIdade()>= 11 && super.getIdade() <=15){\r\n			this.categoria = "Infantil";\r\n		} else if(super.getIdade()>=16 && super.getIdade()<=20){\r\n			this.categoria = "Juvenil";\r\n		} else if(super.getIdade()>=21 && super.getIdade()<=40){\r\n			this.categoria = "Adulto";\r\n		} else {\r\n			this.categoria = "Master";\r\n		}\r\n	}\r\n	\r\n	public void setIdade(int idade){\r\n		super.setIdade(idade);\r\n		if(super.getIdade() <=10){\r\n			this.categoria = "Mirim";\r\n		} else if(super.getIdade()>= 11 && super.getIdade() <=15){\r\n			this.categoria = "Infantil";\r\n		} else if(super.getIdade()>=16 && super.getIdade()<=20){\r\n			this.categoria = "Juvenil";\r\n		} else if(super.getIdade()>=21 && super.getIdade()<=40){\r\n			this.categoria = "Adulto";\r\n		} else {\r\n			this.categoria = "Master";\r\n		}\r\n	}\r\n	\r\n	public String toString(){\r\n		return super.toString() + ", " + this.categoria;\r\n	}\r\n	\r\n\r\n    \r\n}'),
