(367, 191, 'SocioAtleta', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\npublic class SocioAtleta extends Socio {\r\n    private String categoria;\r\n    \r\n    public SocioAtelta ( ) {\r\n        super ( );\r\n        categoria " Mirim";\r\n    }\r\n\r\n    public SocioAtleta (int numero, int idade, String nome) {\r\n        super (numero, idade, nome);\r\n        verificaCategoria ( );\r\n    }\r\n    \r\n    public void setIdade (int idade) {\r\n        this.idade = idade;\r\n        verificaCategoria ( );\r\n    }\r\n    \r\n    public void verificaCategoria ( ) {\r\n        if (idade <= 10)\r\n            categoria = "Mirim";\r\n    \r\n        else if (idade >= 11 && idade <= 15)\r\n            categoria = "Infantil";\r\n    \r\n        else if (idade >= 16 && idade <= 20)\r\n            categoria = "Juvenil";\r\n        \r\n        else if (idade >= 21 && idade <= 40)\r\n            categoria = "Adulto"\r\n    \r\n        else\r\n            categoria = "Master";\r\n    }\r\n    \r\n    public String toString ( ) {\r\n        return super.toString ( ) + ", " + categoria;\r\n    }\r\n}\r\n\r\n'),
