(408, 212, 'Socio', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\npublic class Socio {\r\n   protected int numero, idade;\r\n   protected String nome;\r\n   \r\n   public Socio ( ) {\r\n       numero = idade = 0;\r\n       nome = "";\r\n   }\r\n   \r\n   public Socio (int numero, int idade, String nome) {\r\n       this.numero = numero;\r\n       this.idade = idade;\r\n       this.nome = nome;\r\n   }\r\n   \r\n   public void setNumero (int numero) {\r\n       this.numero = numero;\r\n   }\r\n   \r\n   public void setIdade (int idade) {\r\n       this.idade = idade; \r\n   }\r\n   \r\n   public void setNome (String nome) {\r\n       this.nome = nome;\r\n   }\r\n   \r\n   public int getNumero ( ) {\r\n       return numero;\r\n   }\r\n   \r\n   public int getIdade ( ) {\r\n       return idade;\r\n   }\r\n   \r\n   public String getNome ( ) {\r\n       return nome;\r\n   }\r\n   \r\n   public String toString ( ) {\r\n       return numero + ", " + idade + ", " + nome;\r\n   }\r\n}'),
(409, 212, 'SocioAtleta', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\npublic class SocioAtleta extends Socio {\r\n    private String categoria;\r\n    \r\n    public SocioAtleta ( ) {\r\n        super ( );\r\n        categoria = "Mirim";\r\n    }\r\n\r\n    public SocioAtleta (int numero, int idade, String nome) {\r\n        super (numero, idade, nome);\r\n        verificaCategoria ( );\r\n    }\r\n    \r\n    public void setIdade (int idade) {\r\n        this.idade = idade;\r\n        verificaCategoria ( );\r\n    }\r\n    \r\n    public void verificaCategoria ( ) {\r\n        if (idade <= 10)\r\n            categoria = "Mirim";\r\n    \r\n        else if (idade >= 11 && idade <= 15)\r\n            categoria = "Infantil";\r\n    \r\n        else if (idade >= 16 && idade <= 20)\r\n            categoria = "Juvenil";\r\n        \r\n        else if (idade >= 21 && idade <= 40)\r\n            categoria = "Adulto"\r\n    \r\n        else\r\n            categoria = "Master";\r\n    }\r\n    \r\n    public String toString ( ) {\r\n        return super.toString ( ) + ", " + categoria;\r\n    }\r\n}\r\n\r\n'),
(410, 213, 'Socio', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\npublic class Socio {\r\n   protected int numero, idade;\r\n   protected String nome;\r\n   \r\n   public Socio ( ) {\r\n       numero = idade = 0;\r\n       nome = "";\r\n   }\r\n   \r\n   public Socio (int numero, int idade, String nome) {\r\n       this.numero = numero;\r\n       this.idade = idade;\r\n       this.nome = nome;\r\n   }\r\n   \r\n   public void setNumero (int numero) {\r\n       this.numero = numero;\r\n   }\r\n   \r\n   public void setIdade (int idade) {\r\n       this.idade = idade; \r\n   }\r\n   \r\n   public void setNome (String nome) {\r\n       this.nome = nome;\r\n   }\r\n   \r\n   public int getNumero ( ) {\r\n       return numero;\r\n   }\r\n   \r\n   public int getIdade ( ) {\r\n       return idade;\r\n   }\r\n   \r\n   public String getNome ( ) {\r\n       return nome;\r\n   }\r\n   \r\n   public String toString ( ) {\r\n       return numero + ", " + idade + ", " + nome;\r\n   }\r\n}'),
(411, 213, 'SocioAtleta', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\npublic class SocioAtleta extends Socio {\r\n    private String categoria;\r\n    \r\n    public SocioAtleta ( ) {\r\n        super ( );\r\n        categoria = "Mirim";\r\n    }\r\n\r\n    public SocioAtleta (int numero, int idade, String nome) {\r\n        super (numero, idade, nome);\r\n        verificaCategoria ( );\r\n    }\r\n    \r\n    public void setIdade (int idade) {\r\n        this.idade = idade;\r\n        verificaCategoria ( );\r\n    }\r\n    \r\n    public void verificaCategoria ( ) {\r\n        if (idade <= 10)\r\n            categoria = "Mirim";\r\n    \r\n        else if (idade >= 11 && idade <= 15)\r\n            categoria = "Infantil";\r\n    \r\n        else if (idade >= 16 && idade <= 20)\r\n            categoria = "Juvenil";\r\n        \r\n        else if (idade >= 21 && idade <= 40)\r\n            categoria = "Adulto";\r\n    \r\n        else\r\n            categoria = "Master";\r\n    }\r\n    \r\n    public String toString ( ) {\r\n        return super.toString ( ) + ", " + categoria;\r\n    }\r\n}\r\n\r\n'),
(418, 217, 'Ponto', 'public class Ponto {\r\n\r\n    private int x;\r\n    private int y;\r\n    \r\n    public Ponto()\r\n    {\r\n        this.x = 0;\r\n        this.y = 0;\r\n    }\r\n    \r\n    public Ponto(int x, int y) {\r\n        this.x = x;\r\n        this.y = y;\r\n    }\r\n\r\n    public int getX() {\r\n        return x;\r\n    }\r\n\r\n    public void setX(int x) {\r\n        this.x = x;\r\n    }\r\n\r\n    public int getY() {\r\n        return y;\r\n    }\r\n\r\n    public void setY(int y) {\r\n        this.y = y;\r\n    }\r\n\r\n    @Override\r\n    public String toString() {\r\n        return "(" + x + ", " + y + '')'';\r\n    }\r\n}\r\n'),
(419, 217, 'ArrayDePontos', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass ArrayDePontos\r\n{\r\n   \r\n   Ponto[] pontos;\r\n   int tamanho;\r\n \r\n   public ArrayDePontos( int tamanho )\r\n   {\r\n       pontos = new Ponto[tamanho];\r\n   }\r\n\r\n   public int getTamanho()\r\n   {\r\n       return tamanho;\r\n   }\r\n\r\n   public void setTamanho()\r\n   {\r\n       tamanho++;\r\n   }\r\n\r\n   public void inserirPonto ( Ponto ponto )\r\n   {\r\n       \r\n	   if ( getTamanho() < pontos.length ) \r\n	   {\r\n		   pontos[getTamanho()] = ponto;\r\n		   setTamanho();\r\n	   }\r\n       \r\n   }\r\n\r\n   \r\n   public int obtemPontoSuperior()\r\n   {\r\n\r\n	   int maior = pontos[0].getY();\r\n	   \r\n	   for (int i = 0; i <= pontos.length; i++)\r\n	   {\r\n		   \r\n		   if ( maior < pontos[i].getY() )\r\n		   {\r\n			   maior = pontos[i].getY();\r\n		   }\r\n		   \r\n	   }\r\n	   \r\n	   return maior;\r\n\r\n   }\r\n   \r\n   public int obtemPontoInferior()\r\n   {\r\n	   int menor = pontos[0].getY();\r\n	   \r\n	   for (int i = 0; i <= pontos.length; i++)\r\n	   {\r\n		   \r\n		   if ( menor > pontos[i].getY() )\r\n		   {\r\n			   menor = pontos[i].getY();\r\n		   }\r\n		   \r\n	   }\r\n	   \r\n	   return menor;\r\n   }\r\n   \r\n   public int obtemPontoMaisADireita()\r\n   {\r\n	   int maior = pontos[0].getX();\r\n	   \r\n	   for (int i = 0; i <= pontos.length; i++)\r\n	   {\r\n		   \r\n		   if ( maior < pontos[i].getX() )\r\n		   {\r\n			   maior = pontos[i].getX();\r\n		   }\r\n		   \r\n	   }\r\n	   \r\n	   return maior;\r\n   }\r\n   \r\n   public int obtemPontoMaisAEsquerda()\r\n   {\r\n	   int menor = pontos[0].getX();\r\n	   \r\n	   for (int i = 0; i <= pontos.length; i++)\r\n	   {\r\n		   \r\n		   if ( menor > pontos[i].getX() )\r\n		   {\r\n			   menor = pontos[i].getX();\r\n		   }\r\n		   \r\n	   }\r\n	   \r\n	   return menor;\r\n   }\r\n   \r\n}\r\n\r\n'),
(420, 218, 'Ponto', 'public class Ponto {\r\n\r\n    private int x;\r\n    private int y;\r\n    \r\n    public Ponto()\r\n    {\r\n        this.x = 0;\r\n        this.y = 0;\r\n    }\r\n    \r\n    public Ponto(int x, int y) {\r\n        this.x = x;\r\n        this.y = y;\r\n    }\r\n\r\n    public int getX() {\r\n        return x;\r\n    }\r\n\r\n    public void setX(int x) {\r\n        this.x = x;\r\n    }\r\n\r\n    public int getY() {\r\n        return y;\r\n    }\r\n\r\n    public void setY(int y) {\r\n        this.y = y;\r\n    }\r\n\r\n    @Override\r\n    public String toString() {\r\n        return "(" + x + ", " + y + '')'';\r\n    }\r\n}\r\n');
