(421, 218, 'ArrayDePontos', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass ArrayDePontos\r\n{\r\n   \r\n   Ponto[] pontos;\r\n   int tamanho;\r\n \r\n   public ArrayDePontos( int tamanho )\r\n   {\r\n       pontos = new Ponto[tamanho];\r\n   }\r\n\r\n   public int getTamanho()\r\n   {\r\n       return tamanho;\r\n   }\r\n\r\n   public void setTamanho()\r\n   {\r\n       tamanho++;\r\n   }\r\n\r\n   public void inserirPonto ( Ponto ponto )\r\n   {\r\n       \r\n	   if ( getTamanho() < pontos.length ) \r\n	   {\r\n		   pontos[getTamanho()] = ponto;\r\n		   setTamanho();\r\n	   }\r\n       \r\n   }\r\n\r\n   \r\n   public int obtemPontoSuperior()\r\n   {\r\n\r\n	   int maior = pontos[0].getY();\r\n	   \r\n	   for (int i = 0; i < pontos.length; i++)\r\n	   {\r\n		   \r\n		   if ( maior < pontos[i].getY() )\r\n		   {\r\n			   maior = pontos[i].getY();\r\n		   }\r\n		   \r\n	   }\r\n	   \r\n	   return maior;\r\n\r\n   }\r\n   \r\n   public int obtemPontoInferior()\r\n   {\r\n	   int menor = pontos[0].getY();\r\n	   \r\n	   for (int i = 0; i < pontos.length; i++)\r\n	   {\r\n		   \r\n		   if ( menor > pontos[i].getY() )\r\n		   {\r\n			   menor = pontos[i].getY();\r\n		   }\r\n		   \r\n	   }\r\n	   \r\n	   return menor;\r\n   }\r\n   \r\n   public int obtemPontoMaisADireita()\r\n   {\r\n	   int maior = pontos[0].getX();\r\n	   \r\n	   for (int i = 0; i < pontos.length; i++)\r\n	   {\r\n		   \r\n		   if ( maior < pontos[i].getX() )\r\n		   {\r\n			   maior = pontos[i].getX();\r\n		   }\r\n		   \r\n	   }\r\n	   \r\n	   return maior;\r\n   }\r\n   \r\n   public int obtemPontoMaisAEsquerda()\r\n   {\r\n	   int menor = pontos[0].getX();\r\n	   \r\n	   for (int i = 0; i < pontos.length; i++)\r\n	   {\r\n		   \r\n		   if ( menor > pontos[i].getX() )\r\n		   {\r\n			   menor = pontos[i].getX();\r\n		   }\r\n		   \r\n	   }\r\n	   \r\n	   return menor;\r\n   }\r\n   \r\n}\r\n\r\n'),
(422, 219, 'Ponto', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\npublic class Ponto {\r\n	\r\n	private int x;\r\n	private int y;\r\n	\r\n	public Ponto() {\r\n	}\r\n\r\n	public Ponto(int x, int y) {\r\n		this.x = x;\r\n		this.y = y;\r\n	}\r\n\r\n	public void setX(int x) {\r\n		this.x = x;\r\n	}\r\n	\r\n	public void setY(int y) {\r\n		this.y = y;\r\n	}\r\n	\r\n	public int getX() {\r\n		return x;\r\n	}\r\n\r\n	public int getY() {\r\n		return y;\r\n	}\r\n\r\n	@Override\r\n	public String toString() {\r\n		return ( "("+ getX() + ", " + getY() + ")" );\r\n	}\r\n\r\n}'),
(423, 219, 'Reta', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\npublic class Reta {\r\n\r\n	private Ponto p;\r\n	private Ponto q;\r\n	\r\n	public Reta() {\r\n\r\n	}\r\n\r\n	public Reta(Ponto p, Ponto q) {\r\n		this.p = p;\r\n		this.q = q;\r\n	}\r\n\r\n	public void setP(Ponto p) {\r\n		this.p = p;\r\n	}\r\n	\r\n	public void setQ(Ponto q) {\r\n		this.q = q;\r\n	}\r\n\r\n	public Ponto getP() {\r\n		return p;\r\n	}\r\n	\r\n	public Ponto getQ() {\r\n		return q;\r\n	}\r\n\r\n	public double getDistancia() {\r\n		\r\n		return Math.sqrt( ( Math.pow( ( getQ().getX() - getP().getX() ), 2) +  Math.pow( ( getQ().getY() - getP().getY() ), 2) ) );\r\n		\r\n	}\r\n	\r\n}'),
(424, 220, 'Socio', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\npublic class Socio {\r\n	\r\n	private int numero;\r\n	private int idade;\r\n	private String nome;\r\n	\r\n	\r\n	public Socio() {\r\n		this.numero = 0;\r\n		this.idade = 0;\r\n		this.nome = new String();\r\n	}\r\n\r\n\r\n	public Socio(int numero, int idade, String nome) {\r\n		this.numero = numero;\r\n		this.idade = idade;\r\n		this.nome = nome;\r\n	}\r\n\r\n\r\n	public void setNumero(int numero) {\r\n		this.numero = numero;\r\n	}\r\n\r\n\r\n	public void setIdade(int idade) {\r\n		this.idade = idade;\r\n	}\r\n\r\n\r\n	public void setNome(String nome) {\r\n		this.nome = nome;\r\n	}\r\n\r\n\r\n	public int getNumero() {\r\n		return numero;\r\n	}\r\n\r\n\r\n	public int getIdade() {\r\n		return idade;\r\n	}\r\n\r\n\r\n	public String getNome() {\r\n		return nome;\r\n	}\r\n\r\n	@Override\r\n	public String toString() {\r\n		return ( "" + getNumero() + ", " + getIdade() + ", " + getNome() + "" );\r\n	}\r\n	\r\n}'),
(425, 220, 'SocioAtleta', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\npublic class SocioAtrela extends Socio {\r\n\r\n	private String categoria;\r\n\r\n	public SocioAtrela() {\r\n		super();\r\n		this.categoria = "Mirim";\r\n	}\r\n\r\n	public SocioAtrela(int numero, int idade, String nome) {\r\n		super(numero, idade, nome);\r\n		\r\n		if ( super.getIdade() <= 10 ){ this.categoria = "Mirim"; }\r\n		if ( super.getIdade() > 10 && super.getIdade() <= 15 ) { this.categoria = "Infantil"; }\r\n		if ( super.getIdade() > 15 && super.getIdade() <= 20 ) { this.categoria = "Juvenil"; }\r\n		if ( super.getIdade() > 20 && super.getIdade() <= 40 ) { this.categoria = "Adulto"; }\r\n		if ( super.getIdade() > 40 ) { this.categoria = "Master"; }\r\n		\r\n	}\r\n	\r\n	public void setIdade(int idade){\r\n		super.setIdade(idade);\r\n		if ( super.getIdade() <= 10 ){ this.categoria = "Mirim"; }\r\n		if ( super.getIdade() > 10 && super.getIdade() <= 15 ) { this.categoria = "Infantil"; }\r\n		if ( super.getIdade() > 15 && super.getIdade() <= 20 ) { this.categoria = "Juvenil"; }\r\n		if ( super.getIdade() > 20 && super.getIdade() <= 40 ) { this.categoria = "Adulto"; }\r\n		if ( super.getIdade() > 40 ) { this.categoria = "Master"; }\r\n	}\r\n	\r\n	@Override\r\n	public String toString() {\r\n		return ( "" + getNumero() + ", " + getIdade() + ", " + getNome() + ", " + this.categoria + "" );\r\n	}\r\n	\r\n}'),
