(427, 221, 'SocioAtleta', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\npublic class SocioAtlela extends Socio {\r\n\r\n	private String categoria;\r\n\r\n	public SocioAtlela() {\r\n		super();\r\n		this.categoria = "Mirim";\r\n	}\r\n\r\n	public SocioAtlela(int numero, int idade, String nome) {\r\n		super(numero, idade, nome);\r\n		\r\n		if ( super.getIdade() <= 10 ){ this.categoria = "Mirim"; }\r\n		if ( super.getIdade() > 10 && super.getIdade() <= 15 ) { this.categoria = "Infantil"; }\r\n		if ( super.getIdade() > 15 && super.getIdade() <= 20 ) { this.categoria = "Juvenil"; }\r\n		if ( super.getIdade() > 20 && super.getIdade() <= 40 ) { this.categoria = "Adulto"; }\r\n		if ( super.getIdade() > 40 ) { this.categoria = "Master"; }\r\n		\r\n	}\r\n	\r\n	public void setIdade(int idade){\r\n		super.setIdade(idade);\r\n		if ( super.getIdade() <= 10 ){ this.categoria = "Mirim"; }\r\n		if ( super.getIdade() > 10 && super.getIdade() <= 15 ) { this.categoria = "Infantil"; }\r\n		if ( super.getIdade() > 15 && super.getIdade() <= 20 ) { this.categoria = "Juvenil"; }\r\n		if ( super.getIdade() > 20 && super.getIdade() <= 40 ) { this.categoria = "Adulto"; }\r\n		if ( super.getIdade() > 40 ) { this.categoria = "Master"; }\r\n	}\r\n	\r\n	@Override\r\n	public String toString() {\r\n		return ( "" + getNumero() + ", " + getIdade() + ", " + getNome() + ", " + this.categoria + "" );\r\n	}\r\n	\r\n}'),
