(470, 243, 'ArrayDePontos', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass ArrayDePontos\r\n{\r\n   private Ponto pontos[];\r\n    private int tamanho;\r\n\r\n    public ArrayDePontos(int numMax){\r\n        pontos = new Ponto [numMax];\r\n        tamanho = 0;\r\n    }\r\n\r\n    public int getTamanho(){\r\n        return tamanho;\r\n    }\r\n\r\n    public void inserirPonto(Ponto ponto){\r\n        if(tamanho < pontos.length){\r\n            pontos[tamanho] = ponto;\r\n            tamanho++;\r\n        }\r\n\r\n        //Posição:  0   1   2   3   4   5 ... \r\n        //            /   /   /   /   /   ...\r\n        //Tamanho   1   2   3   4   5   6 ...\r\n    }\r\n\r\n    public Ponto obtemPontoSuperior(){\r\n        Ponto maior = pontos[0];\r\n        for(int i = 1; i < tamanho; i++){\r\n            if(pontos[i].getY() > maior.getY()){\r\n                maior = pontos[i];\r\n            }\r\n        }\r\n        return maior;\r\n    }\r\n\r\n    public Ponto obtemPontoInferior(){\r\n        Ponto menor = pontos[0];\r\n        for(int i = 1; i < tamanho; i++){\r\n            if(pontos[i].getY() < menor.getY()){\r\n                menor = pontos[i];\r\n            }\r\n        }\r\n        return menor;\r\n    }\r\n\r\n    public Ponto obtemPontoMaisADireita(){\r\n        Ponto maior = pontos[0];\r\n        for(int i = 1; i < tamanho; i++){\r\n            if(pontos[i].getX() > maior.getX()){\r\n                maior = pontos[i];\r\n            }\r\n        }\r\n        return maior.toString();\r\n    }\r\n\r\n    public Ponto obtemPontoMaisAEsquerda(){\r\n        Ponto menor = pontos[0];\r\n        for(int i = 1; i < tamanho; i++){\r\n            if(pontos[i].getX() < menor.getX()){\r\n                menor = pontos[i];\r\n            }\r\n        }\r\n        return menor;\r\n    } \r\n  \r\n}'),
(471, 244, 'Ponto', 'public class Ponto {\r\n\r\n    private int x;\r\n    private int y;\r\n    \r\n    public Ponto()\r\n    {\r\n        this.x = 0;\r\n        this.y = 0;\r\n    }\r\n    \r\n    public Ponto(int x, int y) {\r\n        this.x = x;\r\n        this.y = y;\r\n    }\r\n\r\n    public int getX() {\r\n        return x;\r\n    }\r\n\r\n    public void setX(int x) {\r\n        this.x = x;\r\n    }\r\n\r\n    public int getY() {\r\n        return y;\r\n    }\r\n\r\n    public void setY(int y) {\r\n        this.y = y;\r\n    }\r\n\r\n    @Override\r\n    public String toString() {\r\n        return "(" + x + ", " + y + ")";\r\n    }\r\n}\r\n'),
(472, 244, 'ArrayDePontos', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass ArrayDePontos\r\n{\r\n   private Ponto pontos[];\r\n    private int tamanho;\r\n\r\n    public ArrayDePontos(int numMax){\r\n        pontos = new Ponto [numMax];\r\n        tamanho = 0;\r\n    }\r\n\r\n    public int getTamanho(){\r\n        return tamanho;\r\n    }\r\n\r\n    public void inserirPonto(Ponto ponto){\r\n        if(tamanho < pontos.length){\r\n            pontos[tamanho] = ponto;\r\n            tamanho++;\r\n        }\r\n\r\n        //Posição:  0   1   2   3   4   5 ... \r\n        //            /   /   /   /   /   ...\r\n        //Tamanho   1   2   3   4   5   6 ...\r\n    }\r\n\r\n    public Ponto obtemPontoSuperior(){\r\n        Ponto maior = pontos[0];\r\n        for(int i = 1; i < tamanho; i++){\r\n            if(pontos[i].getY() > maior.getY()){\r\n                maior = pontos[i];\r\n            }\r\n        }\r\n        return maior;\r\n    }\r\n\r\n    public Ponto obtemPontoInferior(){\r\n        Ponto menor = pontos[0];\r\n        for(int i = 1; i < tamanho; i++){\r\n            if(pontos[i].getY() < menor.getY()){\r\n                menor = pontos[i];\r\n            }\r\n        }\r\n        return menor;\r\n    }\r\n\r\n    public Ponto obtemPontoMaisADireita(){\r\n        Ponto maior = pontos[0];\r\n        for(int i = 1; i < tamanho; i++){\r\n            if(pontos[i].getX() > maior.getX()){\r\n                maior = pontos[i];\r\n            }\r\n        }\r\n        return maior;\r\n    }\r\n\r\n    public Ponto obtemPontoMaisAEsquerda(){\r\n        Ponto menor = pontos[0];\r\n        for(int i = 1; i < tamanho; i++){\r\n            if(pontos[i].getX() < menor.getX()){\r\n                menor = pontos[i];\r\n            }\r\n        }\r\n        return menor;\r\n    } \r\n  \r\n}'),
(473, 245, 'SocioAtleta', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\npublic class SocioAtleta extends Socio {\r\n    protected String categoria;\r\n\r\n    public SocioAtleta(){\r\n        super();\r\n        categoria = "Mirim";\r\n    }\r\n\r\n    public SocioAtleta(int numero, int idade, String nome){\r\n        super(numero, idade, nome);\r\n        if(idade <= 10){\r\n            categoria = "Mirim";\r\n        }        \r\n        if((idade >= 11) && (idade <= 15)){\r\n            categoria = "Infantil";\r\n        }\r\n        if((idade >= 16) && (idade <= 20)){\r\n            categoria = "Juvenil";\r\n        }\r\n        if((idade >= 21) && (idade <= 40)){\r\n            categoria = "Adulto";\r\n        }\r\n        if(idade > 40){\r\n            categoria = "Master";\r\n        }\r\n    }\r\n\r\n    public void setIdade(int idade){\r\n        idade = idade;\r\n        if(idade <= 10){\r\n            categoria = "Mirim";\r\n        }        \r\n        if((idade >= 11) && (idade <= 15)){\r\n            categoria = "Infantil";\r\n        }\r\n        if((idade >= 16) && (idade <= 20)){\r\n            categoria = "Juvenil";\r\n        }\r\n        if((idade >= 21) && (idade <= 40)){\r\n            categoria = "Adulto";\r\n        }\r\n        if(idade > 40){\r\n            categoria = "Master";\r\n        }\r\n    }\r\n\r\n    public String toString(){\r\n        String dados = getNumero() + ", " + getIdade() + ", " \r\n            + getNome() + ", " + categoria;\r\n        return dados;\r\n    }\r\n}'),
