(547, 284, 'TestaReta', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\npublic class TestaReta\r\n{\r\n        public static void main(String[] args){\r\n            Teclado teclado = new Teclado();\r\n            char x1 = '' '', x2 = '' '', y1 = '' '' , y2 = '' '';\r\n            while(  x1 != ''S'' && x2 != ''S'' && y1 != ''S'' && y2 != ''S''){\r\n            x1 = teclado.leChar("\\nPonto 1 x: ");\r\n            y1 = teclado.leChar("Ponto 1 y: ");\r\n            x2 = teclado.leChar("Ponto 2 x: ");\r\n            y2 = teclado.leChar("Ponto 1 x: ");\r\n            if(   x1 != ''S'' && x2 != ''S'' && y1 != ''S'' && y2 != ''S'' ){\r\n             Ponto nP1 = new Ponto( Character.getNumericValue(x1) , Character.getNumericValue(y1) );\r\n             Ponto nP2 = new Ponto( Character.getNumericValue(x2) , Character.getNumericValue(y2) );\r\n             Reta reta = new Reta( nP1 , nP2);\r\n             System.out.println(reta.toString());\r\n        }\r\n       }\r\n    }\r\n}\r\n'),
(548, 285, 'Ponto', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass Ponto\r\n{\r\n    private int x,y; // as coordenadas do ponto no espaço bidimensional\r\n    \r\n    public Ponto( int _x ,int _y) {\r\n        x = _x; \r\n        y = _y;\r\n    }   \r\n    \r\n    public Ponto() {\r\n        x = 0; \r\n        y = 0;\r\n    }    \r\n     \r\n    public String toString(){\r\n        String resultado = "("+x+","+y+")";\r\n        return resultado;\r\n    }\r\n    public void setX( int x ){\r\n        this.x = x;\r\n    }\r\n    public void setY( int y){\r\n        this.y = y;\r\n    }\r\n    public int getX(){\r\n        return x;\r\n     }\r\n    public int getY(){\r\n        return y;\r\n    }}'),
(549, 285, 'Reta', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\n\r\npublic class Reta\r\n{\r\n    private Ponto ponto1, ponto2;\r\n\r\n    public Reta( Ponto p1, Ponto p2 ){\r\n        ponto1 = p1;\r\n        ponto2= p2;\r\n    }\r\n    public Reta(){\r\n        ponto1 = null;\r\n        ponto2= null;\r\n    }\r\n    public Ponto getPonto1(){\r\n        return ponto1;\r\n    }\r\n    public Ponto getPonto2(){\r\n        return ponto2;\r\n    }\r\n    public void setPonto1( Ponto p1 ){\r\n        ponto1 = p1;\r\n    }\r\n    public void serPonto2( Ponto p2){\r\n        ponto2 = p2;\r\n    }\r\n    public double getDistancia(){\r\n        int p1x, p1y, p2x, p2y;\r\n        p1x = ponto1.getX();\r\n        p1y = ponto1.getY();\r\n        p2x = ponto2.getX();\r\n        p2y = ponto2.getY();\r\n        double dist = Math.pow(p2x-p1x,2) + Math.pow(p2y-p1y,2);\r\n        dist = Math.sqrt(dist); \r\n        return dist;\r\n    }\r\n    public String toString(){\r\n        String res = ("Ponto 1: "+ponto1.toString()+"\\tPonto 2 :"+ponto2.toString()+"\\tDistancia: "+getDistancia());\r\n    return res;\r\n    }\r\n        \r\n}\r\n');
