(566, 291, 'NumerosPares', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\npublic class NumerosPares\r\n{\r\n  int n;\r\n  \r\n  public NumerosPares(int n ){\r\n    this.n = n;\r\n    }\r\n    public NumerosPares(){\r\n        n = 0;\r\n    }\r\n    public int getN(){\r\n        return n;\r\n    }\r\n    public void setN( int n_ ){\r\n        n = n_;\r\n    }\r\n    public String geraPares(){\r\n        String pares = "2, ";\r\n        int i= 0;\r\n        while( i <= n){\r\n            i = i + 2;\r\n            pares = pares + i +", ";\r\n        }\r\n        return pares;\r\n    }\r\n    public int somaNumeros(){\r\n        int i = 0;\r\n        while( i <= n){\r\n                i = i + 1;\r\n            }\r\n        return i;\r\n    }\r\n}\r\n'),
(567, 292, 'NumerosPares', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\npublic class NumerosPares\r\n{\r\n  int n;\r\n  \r\n  public NumerosPares(int n ){\r\n    this.n = n;\r\n    }\r\n    public NumerosPares(){\r\n        n = 0;\r\n    }\r\n    public int getN(){\r\n        return n;\r\n    }\r\n    public void setN( int n_ ){\r\n        n = n_;\r\n    }\r\n    public String geraPares(){\r\n        String pares = "2, ";\r\n        int i= 0;\r\n        while( i <= n){\r\n            i = i + 2;\r\n            pares = pares + i +", ";\r\n        }\r\n        return pares;\r\n    }\r\n    public int somaNumeros(){\r\n        int soma = 0, i = 0;\r\n        while( i <= n){\r\n                i = i + 1;\r\n                soma = i + soma;\r\n            }\r\n        return soma;\r\n    }\r\n}\r\n'),
(568, 293, 'NumerosPares', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\npublic class NumerosPares\r\n{\r\n  int n;\r\n  \r\n  public NumerosPares(int n ){\r\n    this.n = n;\r\n    }\r\n    public NumerosPares(){\r\n        n = 0;\r\n    }\r\n    public int getN(){\r\n        return n;\r\n    }\r\n    public void setN( int n_ ){\r\n        n = n_;\r\n    }\r\n    public String geraPares(){\r\n        String pares = "2, ";\r\n        int i= 0;\r\n        while( i <= n){\r\n            i = i + 2;\r\n            pares = pares + i +", ";\r\n        }\r\n        return pares;\r\n    }\r\n    public int somaNumeros(){\r\n        int soma = 0, i = 0;\r\n        while( i <= n){\r\n                i = i + 1;\r\n                soma = i + soma;\r\n            }\r\n        return soma;\r\n    }\r\n}\r\n'),
(569, 294, 'NumerosPares', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\npublic class NumerosPares\r\n{\r\n  int n;\r\n  \r\n  public NumerosPares(int n ){\r\n    this.n = n;\r\n    }\r\n    public NumerosPares(){\r\n        n = 0;\r\n    }\r\n    public int getN(){\r\n        return n;\r\n    }\r\n    public void setN( int n_ ){\r\n        n = n_;\r\n    }\r\n    public String geraPares(){\r\n        String pares = "2, ";\r\n        int i= 0;\r\n        while( i <= n){\r\n            i = i + 2;\r\n            pares = pares + i +", ";\r\n        }\r\n        return pares;\r\n    }\r\n    public int somaNumeros(){\r\n        int soma = 0, i = 0;\r\n        while( i <= n){\r\n                i = i + 1;\r\n            }\r\n        return i;\r\n    }\r\n}\r\n'),
(570, 295, 'NumerosPares', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\npublic class NumerosPares\r\n{\r\n  int n;\r\n  \r\n  public NumerosPares(int n ){\r\n    this.n = n;\r\n    }\r\n    public NumerosPares(){\r\n        n = 0;\r\n    }\r\n    public int getN(){\r\n        return n;\r\n    }\r\n    public void setN( int n_ ){\r\n        n = n_;\r\n    }\r\n    public String geraPares(){\r\n        String pares = "2, ";\r\n        int i= 0;\r\n        while( i <= n){\r\n            i = i + 2;\r\n            pares = pares + i +", ";\r\n        }\r\n        return pares;\r\n    }\r\n    public int somaNumeros(){\r\n        int soma = 0, i = 1;\r\n        while( i <= n){\r\n                i = i + 1;\r\n            }\r\n        return i;\r\n    }\r\n}\r\n'),
(571, 296, 'NumerosPares', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\npublic class NumerosPares\r\n{\r\n  int n;\r\n  \r\n  public NumerosPares(int n ){\r\n    this.n = n;\r\n    }\r\n    public NumerosPares(){\r\n        n = 0;\r\n    }\r\n    public int getN(){\r\n        return n;\r\n    }\r\n    public void setN( int n_ ){\r\n        n = n_;\r\n    }\r\n    public String geraPares(){\r\n        String pares = "2, ";\r\n        int i= 0;\r\n        while( i <= n){\r\n            i = i + 2;\r\n            pares = pares + i +", ";\r\n        }\r\n        return pares;\r\n    }\r\n    public int somaNumeros(){\r\n        int soma = 0, i = 1;\r\n        while( i <= n){\r\n                i = i + 1;\r\n            }\r\n        return i;\r\n    }\r\n}\r\n'),
(572, 297, 'Ponto', 'public class Ponto\r\n{\r\n    private int x;\r\n    private int y;\r\n    \r\n    public Ponto(){\r\n        x=0;\r\n        y=0;\r\n    }\r\n    public Ponto (int x,int y){\r\n        this.x=x;\r\n        this.y=y;\r\n    }\r\n    \r\n    // sets\r\n    public void setX(int x){\r\n        this.x=x;\r\n    }\r\n    public void setY(int y){\r\n        this.y=y;\r\n    }\r\n    \r\n    // gets \r\n    public int getX(){\r\n        return x;\r\n    }\r\n    public int getY(){\r\n        return y;\r\n    }\r\n    \r\n    public String toString(){\r\n        String ret;\r\n        ret="("+x+","+y+")";\r\n        return ret;\r\n    }\r\n}'),
(573, 297, 'Reta', '\r\n/**\r\n * Write a description of class Reta here.\r\n * \r\n * @author (Renan) \r\n * @version (a version number or a date)\r\n */\r\npublic class Reta\r\n{\r\n   private Ponto ponto1;\r\n   private Ponto ponto2;\r\n   \r\n   public Reta(){\r\n       ponto1=new Ponto();\r\n       ponto2=new Ponto();\r\n   }\r\n   public Reta(Ponto ponto1,Ponto ponto2){\r\n       this.ponto1=ponto1;\r\n       this.ponto2=ponto2;\r\n   }\r\n   \r\n   public void setPonto1(Ponto ponto1){\r\n       this.ponto1=ponto1;\r\n    }\r\n   public void setPonto2(Ponto ponto2){\r\n       this.ponto2=ponto2;\r\n    }\r\n    \r\n   public Ponto getPonto1(){\r\n       return ponto1;\r\n    }\r\n   public Ponto getPonto2(){\r\n       return ponto2;\r\n    } \r\n    \r\n   public double getDistancia(){\r\n       double d;\r\n       //double b = Math.pow (a,2);     // retorna o resultado de 2\r\n       //double c = Math.sqrt(res);   // retorna a raiz quadrada de res\r\n       \r\n       d=Math.sqrt(Math.pow ((ponto2.getX()-ponto1.getX()),2) + Math.pow ((ponto2.getY()-ponto1.getY()),2));\r\n       \r\n       return d;\r\n       \r\n   } \r\n   \r\n   public String toString(){\r\n       String ret;\r\n       ret=" A Distancia é: "+getDistancia();\r\n       return ret;\r\n   }\r\n   \r\n}\r\n'),
(574, 297, 'Teclado', ' \r\n\r\nimport java.io.*;\r\n\r\n/** Classe que permite fazer leitura de dados do tecladeo */\r\n\r\npublic class Teclado\r\n{\r\n     private String s;\r\n     private InputStreamReader i = new InputStreamReader (System.in);\r\n     private BufferedReader d = new BufferedReader(i);\r\n\r\n     /**\r\n        Le um inteiro.\r\n        @return int\r\n     */\r\n     public int leInt ()\r\n     {   System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         int a = 0;\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser inteiro: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um inteiro, com mensagem.\r\n        @return int\r\n     */\r\n     public int leInt (String msg)\r\n     { \r\n         int a = 0;\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: "+e );\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser inteiro: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um double.\r\n        @return double\r\n     */\r\n     public double leDouble()\r\n     { \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         double a = 0;\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Double.parseDouble(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser numero: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um double, com mensagem.\r\n        @return double\r\n     */\r\n     public double leDouble(String msg)\r\n     {   double a = 0;\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Double.parseDouble(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser numero: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um string.\r\n        @return String\r\n     */\r\n     public String leString()\r\n     { \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         s = "";\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            \r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (s);\r\n     }\r\n\r\n     /**\r\n        Le um string. com mensagem.\r\n        @return String\r\n     */\r\n     public String leString(String msg)\r\n     {   s = "";\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n            s = d.readLine();\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (s);\r\n     }\r\n        \r\n    /**\r\n        Le um char.\r\n        @return char\r\n     */\r\n     public char leChar()\r\n     {  \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         s = "";\r\n         char c='' '';\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            c = s.charAt(0);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (c);\r\n     }\r\n          \r\n     /**\r\n        Le um char com mensagem.\r\n        @return char\r\n     */\r\n     public char leChar(String msg)\r\n     {   s = "";\r\n         char c='' '';\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            c = s.charAt(0);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (c);\r\n     }\r\n     \r\n     \r\n    \r\n    }\r\n\r\n'),
(575, 297, 'TestaReta', '\r\n/**\r\n * Write a description of class TestaReta here.\r\n * \r\n * @author (your name) \r\n * @version (a version number or a date)\r\n */\r\npublic class TestaReta\r\n{\r\n   public static void main (String args[]){\r\n       Teclado t=new Teclado();\r\n       int x;\r\n       int y;\r\n       char cond='' '';\r\n       \r\n       while(cond!=''s''){\r\n       x=t.leInt("digite o valor de x:");\r\n       y=t.leInt("digite o valor de y:");\r\n       Ponto p1=new Ponto(x,y);\r\n       x=t.leInt("digite o outro valor de x:");\r\n       y=t.leInt("digite o outro valor de y:");\r\n       Ponto p2=new Ponto(x,y);\r\n       \r\n       Reta r1=new Reta(p1,p2);\r\n       System.out.println(r1.toString());\r\n    }\r\n      System.out.println("Programa finalizado!!");\r\n   }\r\n}\r\n'),
(576, 298, 'Ponto', 'public class Ponto\r\n{\r\n    private int x;\r\n    private int y;\r\n    \r\n    public Ponto(){\r\n        x=0;\r\n        y=0;\r\n    }\r\n    public Ponto (int x,int y){\r\n        this.x=x;\r\n        this.y=y;\r\n    }\r\n    \r\n    // sets\r\n    public void setX(int x){\r\n        this.x=x;\r\n    }\r\n    public void setY(int y){\r\n        this.y=y;\r\n    }\r\n    \r\n    // gets \r\n    public int getX(){\r\n        return x;\r\n    }\r\n    public int getY(){\r\n        return y;\r\n    }\r\n    \r\n    public String toString(){\r\n        String ret;\r\n        ret="("+x+", "+y+")";\r\n        return ret;\r\n    }\r\n}'),
(577, 298, 'Reta', '\r\n/**\r\n * Write a description of class Reta here.\r\n * \r\n * @author (Renan) \r\n * @version (a version number or a date)\r\n */\r\npublic class Reta\r\n{\r\n   private Ponto ponto1;\r\n   private Ponto ponto2;\r\n   \r\n   public Reta(){\r\n       ponto1=new Ponto();\r\n       ponto2=new Ponto();\r\n   }\r\n   public Reta(Ponto ponto1,Ponto ponto2){\r\n       this.ponto1=ponto1;\r\n       this.ponto2=ponto2;\r\n   }\r\n   \r\n   public void setPonto1(Ponto ponto1){\r\n       this.ponto1=ponto1;\r\n    }\r\n   public void setPonto2(Ponto ponto2){\r\n       this.ponto2=ponto2;\r\n    }\r\n    \r\n   public Ponto getPonto1(){\r\n       return ponto1;\r\n    }\r\n   public Ponto getPonto2(){\r\n       return ponto2;\r\n    } \r\n    \r\n   public double getDistancia(){\r\n       double d;\r\n       //double b = Math.pow (a,2);     // retorna o resultado de 2\r\n       //double c = Math.sqrt(res);   // retorna a raiz quadrada de res\r\n       \r\n       d=Math.sqrt(Math.pow ((ponto2.getX()-ponto1.getX()),2) + Math.pow ((ponto2.getY()-ponto1.getY()),2));\r\n       \r\n       return d;\r\n       \r\n   } \r\n   \r\n   public String toString(){\r\n       String ret;\r\n       ret=" A Distancia é: "+getDistancia();\r\n       return ret;\r\n   }\r\n   \r\n}\r\n');
