(606, 307, 'NumerosPares', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\npublic class NumerosPares\r\n{\r\n  int n;\r\n  \r\n  public NumerosPares(int n ){\r\n    this.n = n;\r\n    }\r\n    public NumerosPares(){\r\n        n = 0;\r\n    }\r\n    public int getN(){\r\n        return n;\r\n    }\r\n    public void setN( int n_ ){\r\n        n = n_;\r\n    }\r\n    public String geraPares(){\r\n        String pares = " ";\r\n        int i= 0;\r\n        while( i <= n){\r\n            i = i + 2;\r\n            pares = pares + ", " +i;\r\n        }\r\n        return pares;\r\n    }\r\n    public int somaNumeros(){\r\n        int soma = 0, i = 0;\r\n        while( i <= n){\r\n            soma = soma + i;\r\n                i = i + 1;\r\n            }\r\n        return soma;\r\n    }\r\n}\r\n'),
(607, 308, 'Ponto', '\r\n/**\r\n * Write a description of class Ponto here.\r\n * \r\n * @author (your name) \r\n * @version (a version number or a date)\r\n */\r\npublic class Ponto{\r\n    private int x, y;\r\n    \r\n    public Ponto (){\r\n        x = 0;\r\n        y = 0;\r\n    }\r\n    \r\n    public Ponto (int x1 , int y1){\r\n        this.x = x1;\r\n        this.y = y1;\r\n    }\r\n    \r\n    public void setX (int x){\r\n        this.x = x;\r\n    }\r\n    \r\n    public void setY (int y){\r\n        this.y = y;\r\n    }\r\n    \r\n    public int getX (){\r\n        return this.x;\r\n    }\r\n    \r\n    public int getY (){\r\n        return this.y;\r\n    }\r\n    \r\n    public String toString (){\r\n        String res = "("+x+", " +y+")";\r\n        return res;\r\n    }    \r\n        \r\n    \r\n    \r\n        \r\n\r\n\r\n}\r\n'),
(608, 308, 'Reta', '\r\n/**\r\n * Write a description of class Reta here.\r\n * \r\n * @author (your name) \r\n * @version (a version number or a date)\r\n */\r\npublic class Reta{\r\n    private Ponto ponto1;\r\n    private Ponto ponto2;\r\n    \r\n    public Reta (Ponto p1 , Ponto p2){\r\n        ponto1 = p1;\r\n        ponto2 = p2;\r\n    }\r\n    \r\n    public Reta (){\r\n    }  \r\n    \r\n    public void setPonto1 (Ponto p1){\r\n        ponto1 = p1;\r\n    }\r\n    \r\n    public Ponto getPonto1 (){\r\n        return ponto1;\r\n    }\r\n    \r\n    public void setPonto2 (Ponto p2){\r\n        ponto2 = p2;\r\n    }\r\n    \r\n    public Ponto getPonto2 (){\r\n        return ponto2;\r\n    }\r\n    \r\n    public double getDistancia (){\r\n        int c1 =ponto2.getX() - ponto1.getX();\r\n        int c2 =ponto2.getY() - ponto1.getY();\r\n        double b1 = 0;\r\n        double b2 = 0;\r\n        b1 = Math.pow (c1,2);\r\n        b2 = Math.pow (b2,2); \r\n        double d = 0;\r\n        double j = 0;\r\n        j = b1 + b2;\r\n        d = Math.sqrt (j);\r\n        return d;\r\n    }\r\n    \r\n    public String toString (){\r\n    String res = "("+ponto1.getX()+","+ponto1.getY()+")";\r\n    res += "\\n("+ponto2.getX()+","+ponto2.getY()+")";\r\n    res += "\\nA distância entre os pontos é: " +getDistancia();\r\n    \r\n    return res;\r\n}\r\n\r\n \r\n}    \r\n        \r\n    \r\n    \r\n        \r\n    \r\n    \r\n        \r\n        \r\n    \r\n    \r\n    \r\n\r\n\r\n'),
(609, 308, 'Teclado', ' \r\n\r\nimport java.io.*;\r\n\r\n/** Classe que permite fazer leitura de dados do tecladeo */\r\n\r\npublic class Teclado\r\n{\r\n     private String s;\r\n     private InputStreamReader i = new InputStreamReader (System.in);\r\n     private BufferedReader d = new BufferedReader(i);\r\n\r\n     /**\r\n        Le um inteiro.\r\n        @return int\r\n     */\r\n     public int leInt ()\r\n     {   System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         int a = 0;\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser inteiro: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um inteiro, com mensagem.\r\n        @return int\r\n     */\r\n     public int leInt (String msg)\r\n     { \r\n         int a = 0;\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: "+e );\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser inteiro: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um double.\r\n        @return double\r\n     */\r\n     public double leDouble()\r\n     { \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         double a = 0;\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Double.parseDouble(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser numero: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um double, com mensagem.\r\n        @return double\r\n     */\r\n     public double leDouble(String msg)\r\n     {   double a = 0;\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Double.parseDouble(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser numero: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um string.\r\n        @return String\r\n     */\r\n     public String leString()\r\n     { \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         s = "";\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            \r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (s);\r\n     }\r\n\r\n     /**\r\n        Le um string. com mensagem.\r\n        @return String\r\n     */\r\n     public String leString(String msg)\r\n     {   s = "";\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n            s = d.readLine();\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (s);\r\n     }\r\n        \r\n    /**\r\n        Le um char.\r\n        @return char\r\n     */\r\n     public char leChar()\r\n     {  \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         s = "";\r\n         char c='' '';\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            c = s.charAt(0);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (c);\r\n     }\r\n          \r\n     /**\r\n        Le um char com mensagem.\r\n        @return char\r\n     */\r\n     public char leChar(String msg)\r\n     {   s = "";\r\n         char c='' '';\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            c = s.charAt(0);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (c);\r\n     }\r\n     \r\n     \r\n    \r\n    }\r\n\r\n'),
(610, 308, 'TestaReta', '\r\n/**\r\n * Write a description of class TestaReta here.\r\n * \r\n * @author (your name) \r\n * @version (a version number or a date)\r\n */\r\npublic class TestaReta{\r\n    public static void main (String args []){\r\n        Teclado t = new Teclado ();\r\n        char l= '' '';\r\n        while (l != ''s''){\r\n        int x =t.leInt ("Digite o valor de X do ponto 1");\r\n        int y =t.leInt ("Digite o valor de Y do ponto 1");\r\n        int x1 = t.leInt ("Digite o valor de X do ponto 2");\r\n        int y2 = t.leInt ("Digite o valor de Y do ponto 2");\r\n        Ponto p1 = new Ponto (x,y);\r\n        Ponto p2 = new Ponto (x1,y2);\r\n        Reta r1 = new Reta (p1 , p2);\r\n        System.out.println (r1);\r\n        l = t.leChar ("Digite alguma letra , s interrompe");}\r\n    }   \r\n\r\n}\r\n'),
(611, 309, 'NumerosPares', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\npublic class NumerosPares\r\n{\r\n  int n;\r\n  \r\n  public NumerosPares(int n ){\r\n    this.n = n;\r\n    }\r\n    public NumerosPares(){\r\n        n = 0;\r\n    }\r\n    public int getN(){\r\n        return n;\r\n    }\r\n    public void setN( int n_ ){\r\n        n = n_;\r\n    }\r\n    public String geraPares(){\r\n        String pares = "2";\r\n        int i= 2;\r\n        while( i <= n){\r\n            pares = pares + ", " +i;\r\n            i = i + 2;\r\n        }\r\n        return pares;\r\n    }\r\n    public int somaNumeros(){\r\n        int soma = 0, i = 0;\r\n        while( i <= n){\r\n            soma = soma + i;\r\n                i = i + 1;\r\n            }\r\n        return soma;\r\n    }\r\n}\r\n'),
