      }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser numero: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um double, com mensagem.\r\n        @return double\r\n     */\r\n     public double leDouble(String msg)\r\n     {   double a = 0;\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Double.parseDouble(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser numero: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um string.\r\n        @return String\r\n     */\r\n     public String leString()\r\n     { \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         s = "";\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            \r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (s);\r\n     }\r\n\r\n     /**\r\n        Le um string. com mensagem.\r\n        @return String\r\n     */\r\n     public String leString(String msg)\r\n     {   s = "";\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n            s = d.readLine();\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (s);\r\n     }\r\n        \r\n    /**\r\n        Le um char.\r\n        @return char\r\n     */\r\n     public char leChar()\r\n     {  \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         s = "";\r\n         char c='' '';\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            c = s.charAt(0);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (c);\r\n     }\r\n          \r\n     /**\r\n        Le um char com mensagem.\r\n        @return char\r\n     */\r\n     public char leChar(String msg)\r\n     {   s = "";\r\n         char c='' '';\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            c = s.charAt(0);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (c);\r\n     }\r\n     \r\n     \r\n    \r\n    }\r\n\r\n'),
(655, 336, 'TestaReta', '\r\n/**\r\n * Write a description of class TestaReta here.\r\n * \r\n * @author (your name) \r\n * @version (a version number or a date)\r\n */\r\npublic class TestaReta{\r\n    public static void main (String args []){\r\n        Teclado t = new Teclado ();\r\n        char l= '' '';\r\n        while (l != ''s''){\r\n        int x =t.leInt ("Digite o valor de X do ponto 1");\r\n        int y =t.leInt ("Digite o valor de Y do ponto 1");\r\n        int x1 = t.leInt ("Digite o valor de X do ponto 2");\r\n        int y2 = t.leInt ("Digite o valor de Y do ponto 2");\r\n        Ponto p1 = new Ponto (x,y);\r\n        Ponto p2 = new Ponto (x1,y2);\r\n        Reta r1 = new Reta (p1 , p2);\r\n        System.out.println (r1);\r\n        l = t.leChar ("Digite alguma letra , s interrompe");}\r\n    }   \r\n\r\n}\r\n'),
(656, 337, 'NumerosPares', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\npublic class NumerosPares\r\n{\r\n  int n;\r\n  \r\n  public NumerosPares(int n ){\r\n    this.n = n;\r\n    }\r\n    public NumerosPares(){\r\n        n = 0;\r\n    }\r\n    public int getN(){\r\n        return n;\r\n    }\r\n    public void setN( int n_ ){\r\n        n = n_;\r\n    }\r\n    public String geraPares(){\r\n        String pares = "";\r\n        int i= 2;\r\n        while( i <= n){\r\n            if (i == 2){\r\n                pares = "2";\r\n                }\r\n            else{\r\n                pares = pares + ", " +i;\r\n            }\r\n            i = i + 2;\r\n        }\r\n        return pares;\r\n    }\r\n    public int somaNumeros(){\r\n        int soma = 0, i = 0;\r\n        while( i <= n){\r\n            soma = soma + i;\r\n                i = i + 1;\r\n            }\r\n        return soma;\r\n    }\r\n}\r\n'),
(657, 338, 'Imprime', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\npublic class Imprime\r\n{\r\n   // Coloque aqui o seu código\r\n   \r\n   public void imprimeTextos()\r\n   {\r\n        Scanner in = new Scanner(System.in);\r\n        \r\n        for(int i=0;i<10;i++)\r\n        {\r\n            int readed = in.nextInt();\r\n            \r\n            if((readed  % 2) == 0)  \r\n                System.out.println("par");\r\n            else \r\n                System.out.println("impar");\r\n        \r\n        }\r\n   }\r\n   \r\n   public void imprimeTexto()\r\n   {\r\n        Scanner in = new Scanner(System.in);\r\n        \r\n        String readed = in.nextLine();\r\n\r\n        System.out.println(readed);\r\n   }\r\n   \r\n}'),
(658, 338, 'Main', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\nclass Main\r\n{\r\n   // Coloque aqui o seu código\r\n   public static void main(String[] args) {\r\n        \r\n        Imprime imprimidor = new Imprime();\r\n        imprimidor.imprimeTextos();\r\n    }\r\n}'),
