         c = s.charAt(0);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (c);\r\n     }\r\n          \r\n     /**\r\n        Le um char com mensagem.\r\n        @return char\r\n     */\r\n     public char leChar(String msg)\r\n     {   s = "";\r\n         char c='' '';\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            c = s.charAt(0);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (c);\r\n     }\r\n     \r\n     \r\n    \r\n    }\r\n\r\n'),
(728, 368, 'TestaReta', 'public class TestaReta {\r\n    \r\n    public static void main (String args []){\r\n        Teclado t1 = new Teclado();\r\n        boolean flag = true;\r\n        while (flag){\r\n        char var1 = t1.leChar("Digite o valor de X do ponto 1: ");\r\n        if(var1 == ''S'')\r\n        flag = false;\r\n        int n1 = (int)var1;\r\n        \r\n        \r\n        char var2 = t1.leChar("Digite o valor de Y do ponto 1: ");\r\n        if(var2 == ''S'')\r\n        flag = false;\r\n        int n2 = (int)var2;\r\n        \r\n        \r\n        char var3 = t1.leChar("Digite o valor de X do ponto 2: ");\r\n        if(var3 == ''S'')\r\n        flag = false;\r\n        int n3 = (int)var3;\r\n        \r\n        \r\n        int var4 = t1.leChar("Digite o valor de Y do ponto 2: ");\r\n        if(var4 == ''S'')\r\n        flag = false;\r\n        int n4 = (int)var4;\r\n    \r\n                                \r\n        \r\n        Ponto p1 = new Ponto(n1,n2);\r\n        Ponto p2 = new Ponto(n3,n4);\r\n        \r\n        Reta r1 = new Reta(p1,p2);\r\n        \r\n        System.out.println (r1);\r\n    }\r\n\r\n}\r\n}\r\n        '),
(729, 369, 'NumerosPares', '\r\n/**\r\n * @author Joice Cazanoski Gomes\r\n * @version 10/05/2016\r\n */\r\npublic class NumerosPares {\r\n    private int n;\r\n    \r\n    public NumerosPares(){\r\n        n = 0;\r\n    }\r\n    \r\n    public NumerosPares(int n){\r\n        this.n = n;\r\n    }\r\n    \r\n    public void setN(int n){\r\n        this.n = n;\r\n    }\r\n\r\n    public int getN(){\r\n        return n;\r\n    }\r\n    \r\n    public String geraPares(){\r\n        int i = 2;\r\n        String s = i + "";\r\n        while(i > 0 && i < n){\r\n            i += 2;\r\n            s+= ", " + i;            \r\n     }\r\n     return s;\r\n    }\r\n\r\n    public int somaNumeros(){\r\n        int soma = 1;\r\n        int i = 1;\r\n        while (i > 0 && i < n){\r\n            i++;\r\n            soma+=i;\r\n        }       \r\n        return soma;\r\n    }\r\n}'),
(730, 370, 'Ponto', 'public class Ponto{\r\n    private int x, y;\r\n    \r\n    public Ponto(){\r\n        \r\n    }\r\n    public Ponto(int x, int y){\r\n        this.x = x;\r\n        this.y = y;\r\n    }\r\n    \r\n    public void setX(int x){\r\n        this.x = x;\r\n    }\r\n    public void setY(int y){\r\n        this.y = y;\r\n    }\r\n    \r\n    public int getX(){\r\n        return x;\r\n    }\r\n    public int getY(){\r\n        return y;\r\n    }\r\n    \r\n    public String toString(){\r\n        String str = "";\r\n        str = "(" + x + ", " + y + ")";\r\n        return str;\r\n    }\r\n}'),
(731, 370, 'Teclado', ' \r\n\r\nimport java.io.*;\r\n\r\n/** Classe que permite fazer leitura de dados do tecladeo */\r\n\r\npublic class Teclado\r\n{\r\n     private String s;\r\n     private InputStreamReader i = new InputStreamReader (System.in);\r\n     private BufferedReader d = new BufferedReader(i);\r\n\r\n     /**\r\n        Le um inteiro.\r\n        @return int\r\n     */\r\n     public int leInt ()\r\n     {   System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         int a = 0;\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser inteiro: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um inteiro, com mensagem.\r\n        @return int\r\n     */\r\n     public int leInt (String msg)\r\n     { \r\n         int a = 0;\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: "+e );\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser inteiro: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um double.\r\n        @return double\r\n     */\r\n     public double leDouble()\r\n     { \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         double a = 0;\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Double.parseDouble(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser numero: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um double, com mensagem.\r\n        @return double\r\n     */\r\n     public double leDouble(String msg)\r\n     {   double a = 0;\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Double.parseDouble(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser numero: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um string.\r\n        @return String\r\n     */\r\n     public String leString()\r\n     { \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         s = "";\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            \r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (s);\r\n     }\r\n\r\n     /**\r\n        Le um string. com mensagem.\r\n        @return String\r\n     */\r\n     public String leString(String msg)\r\n     {   s = "";\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n            s = d.readLine();\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (s);\r\n     }\r\n        \r\n    /**\r\n        Le um char.\r\n        @return char\r\n     */\r\n     public char leChar()\r\n     {  \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         s = "";\r\n         char c='' '';\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            c = s.charAt(0);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (c);\r\n     }\r\n          \r\n     /**\r\n        Le um char com mensagem.\r\n        @return char\r\n     */\r\n     public char leChar(String msg)\r\n     {   s = "";\r\n         char c='' '';\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            c = s.charAt(0);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (c);\r\n     }\r\n     \r\n     \r\n    \r\n    }\r\n\r\n'),
(732, 370, 'Reta', 'public class Reta{\r\n    private Ponto ponto1, ponto2;\r\n    \r\n    public Reta(){\r\n        ponto1 = new Ponto();\r\n        ponto2 = new Ponto();\r\n    }\r\n    public Reta(Ponto p1, Ponto p2){\r\n        ponto1 = p1;\r\n        ponto2 = p2;\r\n    }\r\n    \r\n    public void setPonto1(Ponto p1){\r\n        ponto1 = p1;\r\n    }\r\n     public void setPonto2(Ponto p2){\r\n        ponto2 = p2;\r\n    }\r\n    \r\n    public Ponto getPonto1(){\r\n        return ponto1;\r\n    }\r\n    public Ponto getPonto2(){\r\n        return ponto2;\r\n    }\r\n    \r\n    public double getDistancia(){\r\n        double par1 = (ponto2.getX() - ponto1.getX());\r\n        double par2 = (ponto2.getY() - ponto1.getY());\r\n        double contIncomp = (Math.pow(par1, 2)) + (Math.pow(par2, 2));\r\n        double contCompl = Math.sqrt(contIncomp);\r\n        return contCompl;\r\n    }\r\n    \r\n    public String toString(){\r\n        String str = "\\n Distância entre os dois pontos: " + getDistancia();\r\n        return str;\r\n    }\r\n}'),
(733, 370, 'TestaReta', 'public class TestaReta{\r\n    public static void main(String[] args){\r\n        Teclado t = new Teclado();\r\n        String opc = "";\r\n        \r\n        while(!(opc.equalsIgnoreCase("s"))){\r\n            System.out.println("Digite a coordenada X do ponto 1");\r\n            int x1 = t.leInt();\r\n            System.out.println("Digite a coordenada Y do ponto 1");\r\n            int y1 = t.leInt();\r\n            Ponto p1 = new Ponto(x1, y1);\r\n            System.out.println("Digite a coordenada X do ponto 2");\r\n            int x2 = t.leInt();\r\n            System.out.println("Digite a coordenada Y do ponto 2");\r\n            int y2 = t.leInt();\r\n            Ponto p2 = new Ponto(x2, y2);\r\n            \r\n            Reta r1 = new Reta(p1, p2); \r\n            \r\n            System.out.println(r1.toString());\r\n            System.out.println("");\r\n            \r\n            System.out.println("Você quer sair? [Digite ''S'' para sair]");\r\n            opc = t.leString();\r\n        }\r\n    }\r\n}'),
(734, 371, 'Reta', '\r\n/**\r\n * Escreva a descrição da classe Reta aqui.\r\n * \r\n * @author (Augusto Dal Ago Richter) \r\n * @version (número de versão ou data)\r\n */\r\npublic class Reta\r\n{\r\n   private Ponto ponto1;\r\n   private Ponto ponto2;\r\n   \r\n   public Reta(Ponto p1, Ponto p2){\r\n       this.ponto1 = p1;\r\n       this.ponto2 = p2;\r\n   }\r\n   \r\n   public Reta(){\r\n       this.ponto1 = null;\r\n       this.ponto2 = null;\r\n    }\r\n    \r\n   public void setPonto1(Ponto p1){\r\n       this.ponto1 = p1;\r\n    }\r\n    \r\n    public void setPonto2(Ponto p2){\r\n        this.ponto2 = p2;\r\n    }\r\n    \r\n    public Ponto getPonto1(){\r\n        return ponto1;\r\n    }\r\n    \r\n    public Ponto getPonto2(){\r\n        return ponto2;\r\n    }\r\n    \r\n    public double getDistancia(){\r\n        double calculo = Math.pow((ponto2.getX() - ponto1.getX()),2) + Math.pow((ponto2.getY() - ponto1.getY()),2);\r\n        double raiz = Math.sqrt(calculo);\r\n        return raiz;\r\n    }\r\n    \r\n    public String toString(){\r\n        String texto = "Ponto 1:" + ponto1.toString()+ "\\nPonto 2:" +ponto2.toString();\r\n        return texto;\r\n    }\r\n}\r\n    \r\n        \r\n\r\n    \r\n   \r\n   \r\n'),
(735, 371, 'Ponto', '\r\n/**\r\n * Escreva a descrição da classe Ponto aqui.\r\n * \r\n * @author Augusto Dal Ago Richter\r\n * @version (número de versão ou data)\r\n */\r\npublic class Ponto\r\n{\r\n    private int x, y;\r\n    \r\n    public Ponto(){\r\n        this.x = 0;\r\n        this.y = 0;\r\n    }\r\n    \r\n    public Ponto(int x, int y){\r\n        this.x = x;\r\n        this.y = y;\r\n    }\r\n    \r\n    public void setX(int x){\r\n        this.x = x;\r\n    }\r\n    \r\n    public void setY(int y){\r\n        this.y = y;\r\n    }\r\n    \r\n    public int getX(){\r\n        return x;\r\n    }\r\n    \r\n    public int getY(){\r\n        return y;\r\n    }\r\n    \r\n    public String toString(){\r\n         String texto = "("+x+","+y+")";\r\n         return texto;\r\n        }\r\n        \r\n    }   \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n\r\n'),
