(767, 377, 'Ponto', '\r\n/**\r\n * Write a description of class Ponto here.\r\n * \r\n * @author Marcos Roberto Souza \r\n * @version 06/05/2016\r\n */\r\npublic class Ponto\r\n{\r\n    private int x,y;\r\n    \r\n    public Ponto (int x, int y){\r\n        this.x = x;\r\n        this.y = y;\r\n    }\r\n    \r\n    public Ponto (){\r\n        this.x = 0;\r\n        this.y = 0;\r\n    }\r\n    \r\n    public int getX(){\r\n        return x;\r\n    }\r\n    \r\n    public int getY(){\r\n        return y;\r\n    }\r\n    \r\n    public void setX(int setX){\r\n        x = setX;\r\n    }\r\n    \r\n    public void setY(int setY) {\r\n        y = setY;\r\n    }\r\n    \r\n    public String toString(){\r\n        String str = " ";\r\n        str = "("+x+","+y+")";\r\n        return str;\r\n    }\r\n}\r\n'),
(768, 377, 'TestaReta', '\r\n/**\r\n * Write a description of class TestaReta here.\r\n * \r\n * @author (your name) \r\n * @version (a version number or a date)\r\n */\r\npublic class TestaReta\r\n{\r\n    public static void main (String args[]){\r\n        Teclado teclado = new Teclado();  \r\n        char entrada = ''c'';\r\n        \r\n        while (entrada != ''s''){\r\n        System.out.println("\\n");\r\n        System.out.println("***************************MENU***************************");\r\n        entrada = teclado.leChar ("Digite qualquer tecla para iniciar ou S para Sair: ");\r\n        System.out.println("\\f");\r\n        int x = 0;\r\n        int y = 0;\r\n        x = teclado.leInt ("Digite a Coordenada X do Ponto 1: ");\r\n        y = teclado.leInt ("Digite a Coordenada Y do Ponto 1: ");\r\n        Ponto Ponto1 = new Ponto (x,y);\r\n                \r\n        x = teclado.leInt ("Digite a Coordenada X do Ponto 2: ");\r\n        y = teclado.leInt ("Digite a Coordenada Y do Ponto 2: ");\r\n        Ponto Ponto2 = new Ponto (x,y);\r\n                \r\n        Reta reta1 = new Reta (Ponto1, Ponto2);\r\n        \r\n        reta1.toString();\r\n        \r\n        entrada = teclado.leChar ("Deseja continuar? Digite qualquer tecla ou S para Sair: ");\r\n        \r\n    }\r\n}\r\n}\r\n'),
(769, 377, 'Teclado', ' \r\n\r\nimport java.io.*;\r\n\r\n/** Classe que permite fazer leitura de dados do tecladeo */\r\n\r\npublic class Teclado\r\n{\r\n     private String s;\r\n     private InputStreamReader i = new InputStreamReader (System.in);\r\n     private BufferedReader d = new BufferedReader(i);\r\n\r\n     /**\r\n        Le um inteiro.\r\n        @return int\r\n     */\r\n     public int leInt ()\r\n     {   System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         int a = 0;\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser inteiro: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um inteiro, com mensagem.\r\n        @return int\r\n     */\r\n     public int leInt (String msg)\r\n     { \r\n         int a = 0;\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: "+e );\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser inteiro: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um double.\r\n        @return double\r\n     */\r\n     public double leDouble()\r\n     { \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         double a = 0;\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Double.parseDouble(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser numero: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um double, com mensagem.\r\n        @return double\r\n     */\r\n     public double leDouble(String msg)\r\n     {   double a = 0;\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Double.parseDouble(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser numero: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um string.\r\n        @return String\r\n     */\r\n     public String leString()\r\n     { \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         s = "";\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            \r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (s);\r\n     }\r\n\r\n     /**\r\n        Le um string. com mensagem.\r\n        @return String\r\n     */\r\n     public String leString(String msg)\r\n     {   s = "";\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n            s = d.readLine();\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (s);\r\n     }\r\n        \r\n    /**\r\n        Le um char.\r\n        @return char\r\n     */\r\n     public char leChar()\r\n     {  \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         s = "";\r\n         char c='' '';\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            c = s.charAt(0);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (c);\r\n     }\r\n          \r\n     /**\r\n        Le um char com mensagem.\r\n        @return char\r\n     */\r\n     public char leChar(String msg)\r\n     {   s = "";\r\n         char c='' '';\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            c = s.charAt(0);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (c);\r\n     }\r\n     \r\n     \r\n    \r\n    }\r\n\r\n'),
(770, 378, 'Reta', '\r\n/**\r\n * Write a description of class Reta here.\r\n * \r\n * @author (your name) \r\n * @version (a version number or a date)\r\n */\r\npublic class Reta\r\n{\r\n    private Ponto ponto1, ponto2;\r\n    \r\n    public Ponto getPonto1(){\r\n        return ponto1;\r\n    }\r\n    \r\n    public Ponto getPonto2(){\r\n        return ponto2;\r\n    }\r\n    \r\n    public void setPonto1(Ponto setPonto1){\r\n        ponto1 = setPonto1;\r\n    }\r\n    \r\n    public void setPonto2(Ponto setPonto2){\r\n        ponto1 = setPonto2;\r\n    }\r\n    \r\n    public Reta (Ponto ponto1, Ponto ponto2){\r\n        this.ponto1 = ponto1;\r\n        this.ponto1 = ponto1;\r\n    }\r\n    \r\n    public Reta (){\r\n        ponto1 = new Ponto();\r\n        ponto2 = new Ponto();\r\n    }\r\n    \r\n    public double getDistancia(){\r\n        double distancia = 0;\r\n        double p1, p2;\r\n        p1 = Math.pow(ponto2.getX() - ponto1.getX(), 2);\r\n        p2 = Math.pow(ponto2.getY() - ponto1.getY(), 2);\r\n        distancia = Math.sqrt(p1 + p2);\r\n        return distancia;\r\n    }\r\n    \r\n        public String toString(){\r\n        String str = "";\r\n        str = " A Distância é:"+getDistancia();\r\n        return str;\r\n    }\r\n    \r\n    \r\n    \r\n    \r\n    \r\n    \r\n}\r\n'),
(771, 378, 'Ponto', '\r\n/**\r\n * Write a description of class Ponto here.\r\n * \r\n * @author Marcos Roberto Souza \r\n * @version 06/05/2016\r\n */\r\npublic class Ponto\r\n{\r\n    private int x,y;\r\n    \r\n    public Ponto (int x, int y){\r\n        this.x = x;\r\n        this.y = y;\r\n    }\r\n    \r\n    public Ponto (){\r\n        this.x = 0;\r\n        this.y = 0;\r\n    }\r\n    \r\n    public int getX(){\r\n        return x;\r\n    }\r\n    \r\n    public int getY(){\r\n        return y;\r\n    }\r\n    \r\n    public void setX(int setX){\r\n        x = setX;\r\n    }\r\n    \r\n    public void setY(int setY) {\r\n        y = setY;\r\n    }\r\n    \r\n    public String toString(){\r\n        String str = " ";\r\n        str = "("+x+","+y+")";\r\n        return str;\r\n    }\r\n}\r\n'),
