(813, 398, 'Teclado', ' \r\n\r\nimport java.io.*;\r\n\r\n/** Classe que permite fazer leitura de dados do tecladeo */\r\n\r\npublic class Teclado\r\n{\r\n     private String s;\r\n     private InputStreamReader i = new InputStreamReader (System.in);\r\n     private BufferedReader d = new BufferedReader(i);\r\n\r\n     /**\r\n        Le um inteiro.\r\n        @return int\r\n     */\r\n     public int leInt ()\r\n     {   System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         int a = 0;\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser inteiro: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um inteiro, com mensagem.\r\n        @return int\r\n     */\r\n     public int leInt (String msg)\r\n     { \r\n         int a = 0;\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: "+e );\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser inteiro: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um double.\r\n        @return double\r\n     */\r\n     public double leDouble()\r\n     { \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         double a = 0;\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Double.parseDouble(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser numero: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um double, com mensagem.\r\n        @return double\r\n     */\r\n     public double leDouble(String msg)\r\n     {   double a = 0;\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Double.parseDouble(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser numero: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um string.\r\n        @return String\r\n     */\r\n     public String leString()\r\n     { \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         s = "";\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            \r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (s);\r\n     }\r\n\r\n     /**\r\n        Le um string. com mensagem.\r\n        @return String\r\n     */\r\n     public String leString(String msg)\r\n     {   s = "";\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n            s = d.readLine();\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (s);\r\n     }\r\n        \r\n    /**\r\n        Le um char.\r\n        @return char\r\n     */\r\n     public char leChar()\r\n     {  \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         s = "";\r\n         char c='' '';\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            c = s.charAt(0);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (c);\r\n     }\r\n          \r\n     /**\r\n        Le um char com mensagem.\r\n        @return char\r\n     */\r\n     public char leChar(String msg)\r\n     {   s = "";\r\n         char c='' '';\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            c = s.charAt(0);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (c);\r\n     }\r\n     \r\n     \r\n    \r\n    }\r\n\r\n'),
(814, 399, 'Teclado', ' \r\n\r\nimport java.io.*;\r\n\r\n/** Classe que permite fazer leitura de dados do tecladeo */\r\n\r\npublic class Teclado\r\n{\r\n     private String s;\r\n     private InputStreamReader i = new InputStreamReader (System.in);\r\n     private BufferedReader d = new BufferedReader(i);\r\n\r\n     /**\r\n        Le um inteiro.\r\n        @return int\r\n     */\r\n     public int leInt ()\r\n     {   System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         int a = 0;\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser inteiro: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um inteiro, com mensagem.\r\n        @return int\r\n     */\r\n     public int leInt (String msg)\r\n     { \r\n         int a = 0;\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: "+e );\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser inteiro: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um double.\r\n        @return double\r\n     */\r\n     public double leDouble()\r\n     { \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         double a = 0;\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Double.parseDouble(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser numero: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um double, com mensagem.\r\n        @return double\r\n     */\r\n     public double leDouble(String msg)\r\n     {   double a = 0;\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Double.parseDouble(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser numero: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um string.\r\n        @return String\r\n     */\r\n     public String leString()\r\n     { \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         s = "";\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            \r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (s);\r\n     }\r\n\r\n     /**\r\n        Le um string. com mensagem.\r\n        @return String\r\n     */\r\n     public String leString(String msg)\r\n     {   s = "";\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n            s = d.readLine();\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (s);\r\n     }\r\n        \r\n    /**\r\n        Le um char.\r\n        @return char\r\n     */\r\n     public char leChar()\r\n     {  \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         s = "";\r\n         char c='' '';\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            c = s.charAt(0);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (c);\r\n     }\r\n          \r\n     /**\r\n        Le um char com mensagem.\r\n        @return char\r\n     */\r\n     public char leChar(String msg)\r\n     {   s = "";\r\n         char c='' '';\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            c = s.charAt(0);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (c);\r\n     }\r\n     \r\n     \r\n    \r\n    }\r\n\r\n'),
(815, 399, 'TestaTabuada', '/**\r\n * @author Rodrigo Brandt\r\n * @version 13/05/16\r\n */\r\n\r\npublic class TestaTabuada{\r\n    public static void main(String args[]){\r\n        Teclado t = new Teclado();\r\n        int numero = t.leInt("Digite um numero ou -1 para sair: ");\r\n        while(numero != -1){\r\n            Tabuada ts = new Tabuada(numero);\r\n            System.out.println(ts.calculaTabuada());\r\n            numero = t.leInt("Digite um numero ou -1 para sair: ");\r\n        }\r\n    }\r\n}\r\n'),
(816, 399, 'Tabuada', '/**\r\n * @author Rodrigo Brandt\r\n * @version 13/05/16\r\n */\r\n\r\npublic class Tabuada{\r\n    \r\n    // atributo\r\n    private int numero;\r\n    \r\n    // construtor\r\n    public Tabuada(int n){\r\n        this.numero = n;\r\n    }\r\n    \r\n    // construtor default\r\n    public Tabuada(){\r\n        this.numero = 0;\r\n    }\r\n    \r\n    // get\r\n    public int getNumero(){\r\n        return numero;\r\n    }\r\n    \r\n    // set\r\n    public void setNumero(int n){\r\n        this.numero = n;\r\n    }\r\n    \r\n    //  Esse  método  irá  calcular  e  retornar  uma  String  contendo  a  tabuada  para  o  número  guardado  no  atributo\r\n    public String calculaTabuada(){\r\n        String tabuada = "";\r\n        for (int i = 1; i <= 10; i++){\r\n            tabuada += (numero+" x "+i+" = "+(numero*i));\r\n            if(i!=10){\r\n                tabuada+="\\n";\r\n            }\r\n        }\r\n        return tabuada;\r\n    }\r\n}\r\n'),
(817, 400, 'Teclado', ' \r\n\r\nimport java.io.*;\r\n\r\n/** Classe que permite fazer leitura de dados do tecladeo */\r\n\r\npublic class Teclado\r\n{\r\n     private String s;\r\n     private InputStreamReader i = new InputStreamReader (System.in);\r\n     private BufferedReader d = new BufferedReader(i);\r\n\r\n     /**\r\n        Le um inteiro.\r\n        @return int\r\n     */\r\n     public int leInt ()\r\n     {   System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         int a = 0;\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser inteiro: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um inteiro, com mensagem.\r\n        @return int\r\n     */\r\n     public int leInt (String msg)\r\n     { \r\n         int a = 0;\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: "+e );\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser inteiro: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um double.\r\n        @return double\r\n     */\r\n     public double leDouble()\r\n     { \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         double a = 0;\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Double.parseDouble(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser numero: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um double, com mensagem.\r\n        @return double\r\n     */\r\n     public double leDouble(String msg)\r\n     {   double a = 0;\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Double.parseDouble(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser numero: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um string.\r\n        @return String\r\n     */\r\n     public String leString()\r\n     { \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         s = "";\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            \r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (s);\r\n     }\r\n\r\n     /**\r\n        Le um string. com mensagem.\r\n        @return String\r\n     */\r\n     public String leString(String msg)\r\n     {   s = "";\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n            s = d.readLine();\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (s);\r\n     }\r\n        \r\n    /**\r\n        Le um char.\r\n        @return char\r\n     */\r\n     public char leChar()\r\n     {  \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         s = "";\r\n         char c='' '';\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            c = s.charAt(0);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (c);\r\n     }\r\n          \r\n     /**\r\n        Le um char com mensagem.\r\n        @return char\r\n     */\r\n     public char leChar(String msg)\r\n     {   s = "";\r\n         char c='' '';\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            c = s.charAt(0);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (c);\r\n     }\r\n     \r\n     \r\n    \r\n    }\r\n\r\n'),
(818, 400, 'Tabuada', '\r\n/**\r\n * @author Joice Cazanoski Gomes\r\n * @version 13/05/2016\r\n */\r\npublic class Tabuada {\r\n    private int numero;\r\n    \r\n    public Tabuada(int numero){\r\n        this.numero = numero;\r\n    }\r\n    \r\n    public Tabuada(){\r\n        numero = 0;\r\n    }\r\n    \r\n    public void setNumero(int numero){\r\n        this.numero = numero;\r\n    }\r\n    \r\n    public int getNumero(){\r\n        return numero;\r\n    }\r\n    \r\n    public String calculaTabuada(){\r\n        String ret = "";\r\n        for(int i = 1; i<=10; i++){\r\n            ret += numero + " x " + i + " = " + (numero*i)+ "\\n";\r\n        }\r\n        return ret;\r\n    }\r\n}\r\n   '),
