(837, 411, 'Desenho', 'public class Desenho {\r\n    private String simbolo;\r\n    \r\n    public Desenho (String simbolo) {\r\n        this.simbolo = simbolo;\r\n    }\r\n    \r\n    public void setSimbolo (String simbolo) {\r\n        this.simbolo = simbolo;\r\n    }\r\n    \r\n    public String getSimbolo () {\r\n        return simbolo;\r\n    }\r\n    \r\n    public String desenhaLinha (int comp) {\r\n        String ret = "";\r\n        for (int i=1; i<=comp; i++) {\r\n            ret = ret + simbolo;\r\n        }\r\n        return ret;\r\n    }\r\n    \r\n    public String desenhaTriangulo (int linhas) {\r\n        String ret = "";\r\n        for (int i=1; i<=linhas; i++) {\r\n            ret = ret + desenhaLinha(i) + "\\n";            \r\n        }        \r\n        return ret;\r\n    }\r\n    \r\n    public String desenhaLinhaVazada (int comp) {\r\n        String ret = "";\r\n        if (comp>2) {\r\n            ret = ret + simbolo;\r\n            for (int i=1; i<=(comp-2); i++) {\r\n                ret = ret + " ";\r\n            }\r\n            ret = ret + simbolo;\r\n        }\r\n        else {\r\n            desenhaLinha(comp);\r\n        }        \r\n        return ret;\r\n    }\r\n    \r\n    public String desenhaQuadradoVazado (int linhas) {\r\n        String ret = "";\r\n        for (int i=1; i<=linhas; i++) {\r\n            if (i==1 || i==linhas) {\r\n                ret = ret + desenhaLinha(linhas) + "\\n";\r\n            }\r\n            else {\r\n                ret = ret + desenhaLinhaVazada(linhas) + "\\n";\r\n            }                         \r\n        }        \r\n        return ret;\r\n    }\r\n	public String desenhaQuadrado (int linhas) {\r\n		String ret = "";\r\n		for (int i=1; i<=linhas; i++) {\r\n			ret = ret + desenhaLinha(linhas) + "\\n";\r\n		}\r\n		return ret;\r\n	}\r\n}'),
(838, 412, 'TabuadaSoma', 'public class TabuadaSoma {\r\n    private int numero;\r\n    \r\n    public TabuadaSoma (int numero) {\r\n        this.numero = numero;\r\n    }\r\n    \r\n    public TabuadaSoma () {\r\n        this.numero = 0;\r\n    }    \r\n    \r\n    public String calculaTabuada() {\r\n        String ret = "";\r\n        int res = 0;\r\n        for (int i=1; i<=10; i++) {\r\n            res = numero * i;\r\n            ret = ret + numero + "x" + i + "=" + res + "\\n";\r\n        }        \r\n        return ret;\r\n    }\r\n}'),
(839, 412, 'Teclado', ' \r\n\r\nimport java.io.*;\r\n\r\n/** Classe que permite fazer leitura de dados do tecladeo */\r\n\r\npublic class Teclado\r\n{\r\n     private String s;\r\n     private InputStreamReader i = new InputStreamReader (System.in);\r\n     private BufferedReader d = new BufferedReader(i);\r\n\r\n     /**\r\n        Le um inteiro.\r\n        @return int\r\n     */\r\n     public int leInt ()\r\n     {   System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         int a = 0;\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser inteiro: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um inteiro, com mensagem.\r\n        @return int\r\n     */\r\n     public int leInt (String msg)\r\n     { \r\n         int a = 0;\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: "+e );\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser inteiro: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um double.\r\n        @return double\r\n     */\r\n     public double leDouble()\r\n     { \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         double a = 0;\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Double.parseDouble(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser numero: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um double, com mensagem.\r\n        @return double\r\n     */\r\n     public double leDouble(String msg)\r\n     {   double a = 0;\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Double.parseDouble(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser numero: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um string.\r\n        @return String\r\n     */\r\n     public String leString()\r\n     { \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         s = "";\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            \r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (s);\r\n     }\r\n\r\n     /**\r\n        Le um string. com mensagem.\r\n        @return String\r\n     */\r\n     public String leString(String msg)\r\n     {   s = "";\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n            s = d.readLine();\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (s);\r\n     }\r\n        \r\n    /**\r\n        Le um char.\r\n        @return char\r\n     */\r\n     public char leChar()\r\n     {  \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         s = "";\r\n         char c='' '';\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            c = s.charAt(0);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (c);\r\n     }\r\n          \r\n     /**\r\n        Le um char com mensagem.\r\n        @return char\r\n     */\r\n     public char leChar(String msg)\r\n     {   s = "";\r\n         char c='' '';\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            c = s.charAt(0);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (c);\r\n     }\r\n     \r\n     \r\n    \r\n    }\r\n\r\n'),
(840, 412, 'TestaTabuada', 'public class TestaTabuada {\r\n    public static void main (String args[]) {\r\n        Teclado t = new Teclado();\r\n        TabuadaSoma t1 = new TabuadaSoma();\r\n        int i = 0;\r\n        while(i!=-1){\r\n            i=t.leInt("Digite um numero ou -1 para sair");\r\n            if (i!=-1) {\r\n                t1 = new TabuadaSoma(i);\r\n                System.out.println(t1.calculaTabuada());\r\n            }\r\n        }        \r\n    }\r\n}'),
