(855, 417, 'Tabuada', 'public class Tabuada {\r\n    private int numero;\r\n    \r\n    public Tabuada (int numero) {\r\n        this.numero = numero;\r\n    }\r\n    \r\n    public Tabuada () {\r\n        this.numero = 0;\r\n    }    \r\n    \r\n    public void setNumero (int numero) {\r\n        this.numero = numero;\r\n    }\r\n    \r\n    public int getNumero () {\r\n        return numero;\r\n    }\r\n    \r\n    public String calculaTabuada() {\r\n        String ret = "";\r\n        int res = 0;\r\n        for (int i=1; i<=10; i++) {\r\n            res = numero * i;\r\n            ret = ret+numero+" x "+i+" = "+res+"\\n";\r\n        }        \r\n        return ret;\r\n    }\r\n}'),
(856, 418, 'Desenho', '\r\n/**\r\n * Escreva a descrição da classe Desenho aqui.\r\n * \r\n * @author (seu nome) \r\n * @version (número de versão ou data)\r\n */\r\npublic class Desenho\r\n{\r\n    private String simbolo;\r\n    \r\n    public Desenho (String simbolo){\r\n        this.simbolo = simbolo;\r\n    }\r\n   \r\n     public void setSimbolo (String simbolo){\r\n        this.simbolo = simbolo;\r\n    }\r\n    \r\n    public String getSimbolo (){\r\n        return simbolo;\r\n    }\r\n    \r\n    public String desenhaLinha (int comp) {\r\n        String ret = "";\r\n        for (int i=1; i<=comp; i++) {\r\n            ret = ret + simbolo;\r\n        }\r\n        return ret;\r\n    } \r\n   public String desenhaQuadrado (int nroLinhas) {\r\n       String ret = "";\r\n       for (int i=1; i<=nroLinhas ; i++) {\r\n        ret = ret + desenhaLinha (nroLinhas) + "\\n";\r\n        } \r\n       return ret;\r\n    } \r\n   public String desenhaLinhaVazada (int nroLinhas) {\r\n       String ret = "";\r\n       for (int i=1; i<=nroLinhas; i++) {\r\n        if (i==1 || i==nroLinhas)\r\n        ret = ret + desenhaLinha (1);\r\n        else\r\n        ret = ret + " ";\r\n    }\r\n    return ret;\r\n    }\r\n   public String desenhaQuadradoVazado (int nroLinhas) {\r\n      String ret = "";\r\n    for (int i=1; i<=nroLinhas; i++) {\r\n    if (i==1 || i==nroLinhas)\r\n    ret = ret + desenhaLinha (nroLinhas) + "\\n";\r\n    else \r\n    ret = ret + desenhaLinhaVazada (nroLinhas) + "\\n";\r\n    }\r\n    return ret;\r\n    }\r\n   }\r\n\r\n\r\n\r\n'),
(857, 419, 'Desenho', '\r\n/**\r\n * Escreva a descrição da classe Desenho aqui.\r\n * \r\n * @author (seu nome) \r\n * @version (número de versão ou data)\r\n */\r\npublic class Desenho\r\n{\r\n    private String simbolo;\r\n    \r\n    public Desenho (String simbolo){\r\n        this.simbolo = simbolo;\r\n    }\r\n   \r\n     public void setSimbolo (String simbolo){\r\n        this.simbolo = simbolo;\r\n    }\r\n    \r\n    public String getSimbolo (){\r\n        return simbolo;\r\n    }\r\n    \r\n    public String desenhaLinha (int comp) {\r\n        String ret = "";\r\n        for (int i=1; i<=comp; i++) {\r\n            ret = ret + simbolo;\r\n        }\r\n        return ret;\r\n    } \r\n   public String desenhaQuadrado (int nroLinhas) {\r\n       String ret = "";\r\n       for (int i=1; i<=nroLinhas ; i++) {\r\n        ret = ret + desenhaLinha (nroLinhas) + "\\n";\r\n        } \r\n       return ret;\r\n    } \r\n    \r\n   public String desenhaTriangulo (int nroLinhas) {\r\n       String ret = "";\r\n       for (int i=1; i<=nroLinhas ; i++) {\r\n        ret = ret + desenhaLinha (i) + "\\n";\r\n        } \r\n       \r\n       return ret;\r\n    } \r\n   public String desenhaLinhaVazada (int nroLinhas) {\r\n       String ret = "";\r\n       for (int i=1; i<=nroLinhas; i++) {\r\n        if (i==1 || i==nroLinhas)\r\n        ret = ret + desenhaLinha (1);\r\n        else\r\n        ret = ret + " ";\r\n    }\r\n    return ret;\r\n    }\r\n   public String desenhaQuadradoVazado (int nroLinhas) {\r\n      String ret = "";\r\n    for (int i=1; i<=nroLinhas; i++) {\r\n    if (i==1 || i==nroLinhas)\r\n    ret = ret + desenhaLinha (nroLinhas) + "\\n";\r\n    else \r\n    ret = ret + desenhaLinhaVazada (nroLinhas) + "\\n";\r\n    }\r\n    return ret;\r\n    }\r\n   }\r\n\r\n\r\n\r\n'),
(858, 420, 'Desenho', '\r\n/**\r\n * Escreva a descrição da classe Desenho aqui.\r\n * \r\n * @author (seu nome) \r\n * @version (número de versão ou data)\r\n */\r\npublic class Desenho\r\n{\r\n    private String simbolo;\r\n    \r\n    public Desenho (String simbolo){\r\n        this.simbolo = simbolo;\r\n    }\r\n    \r\n    public void setSimbolo (String simbolo){\r\n        this.simbolo = simbolo;\r\n    }\r\n    \r\n    public String getSimbolo () {\r\n        return simbolo;\r\n    }\r\n    \r\n    public  String desenhaLinha(int  comp) {\r\n        String ret = "";\r\n        \r\n        for (int i=1; i<= comp; i++) {\r\n            ret = ret + simbolo;\r\n        }        \r\n        return ret;\r\n    }\r\n    \r\n    public String desenhaTriangulo (int nroLinhas) {\r\n        String ret = "";\r\n        \r\n        for (int i=1; i<= nroLinhas; i++) {\r\n            ret = ret + desenhaLinha (i)+"\\n";\r\n        }\r\n        \r\n        return ret;\r\n    }\r\n    \r\n    public String desenhaLinhaVazada(int comp){\r\n        String ret="";\r\n        for (int i=1;i<=comp;i++){\r\n            if(i==1||i==comp){\r\n                ret = ret + simbolo;\r\n            }else{\r\n                ret=ret+" ";\r\n            }\r\n            \r\n        }\r\n        \r\n        return ret;\r\n    }\r\n    \r\n    public  String desenhaQuadradoVazado(int linhas){\r\n        String ret="";\r\n        for(int i=1;i<=linhas;i++){\r\n            if(i==1||i==linhas){\r\n                ret=ret+desenhaLinha(linhas)+"\\n";\r\n            }else{\r\n                ret=ret+desenhaLinhaVazada(linhas)+"\\n";\r\n            }   \r\n        }\r\n        \r\n        return ret;\r\n    }\r\n    \r\n    public String desenhaQuadrado(int nroLinhas){\r\n        String ret="";\r\n        for(int i =1;i<=nroLinhas;i++){\r\n            ret=ret+desenhaLinha(nroLinhas)+"\\n";\r\n        }\r\n        return ret;\r\n    }\r\n}\r\n'),
(859, 420, 'TestaDesenho', '\r\n/**\r\n * Escreva a descrição da classe TestaDesenho aqui.\r\n * \r\n * @author (seu nome) \r\n * @version (número de versão ou data)\r\n */\r\npublic class TestaDesenho\r\n{\r\n    public static void main (String args[]){\r\n        Desenho d = new Desenho ("x");\r\n        System.out.println (d.desenhaQuadrado(5));\r\n    }\r\n}\r\n'),
