 (this.pontos[i].getX() < esquerda.getX()) {\r\n                esquerda = this.pontos[i];\r\n            }\r\n        }\r\n        return esquerda;\r\n    }\r\n}\r\n'),
(971, 463, 'Ponto', '\r\n/**\r\n * Write a description of class Ponto here.\r\n * \r\n * @author (your name) \r\n * @version (a version number or a date)\r\n */\r\npublic class Ponto{\r\n    private int x, y;\r\n    \r\n    public Ponto (){\r\n        x = 0;\r\n        y = 0;\r\n    }\r\n    \r\n    public Ponto (int x1 , int y1){\r\n        this.x = x1;\r\n        this.y = y1;\r\n    }\r\n    \r\n    public void setX (int x){\r\n        this.x = x;\r\n    }\r\n    \r\n    public void setY (int y){\r\n        this.y = y;\r\n    }\r\n    \r\n    public int getX (){\r\n        return this.x;\r\n    }\r\n    \r\n    public int getY (){\r\n        return this.y;\r\n    }\r\n    \r\n    public String toString (){\r\n        String res = "("+x+", " +y+")";\r\n        return res;\r\n    }    \r\n        \r\n    \r\n    \r\n        \r\n\r\n\r\n}\r\n'),
(972, 463, 'Reta', '\r\n/**\r\n * Write a description of class Reta here.\r\n * \r\n * @author (your name) \r\n * @version (a version number or a date)\r\n */\r\npublic class Reta{\r\n    private Ponto ponto1;\r\n    private Ponto ponto2;\r\n    \r\n    public Reta (Ponto p1 , Ponto p2){\r\n        ponto1 = p1;\r\n        ponto2 = p2;\r\n    }\r\n    \r\n    public Reta (){\r\n    }  \r\n    \r\n    public void setPonto1 (Ponto p1){\r\n        ponto1 = p1;\r\n    }\r\n    \r\n    public Ponto getPonto1 (){\r\n        return ponto1;\r\n    }\r\n    \r\n    public void setPonto2 (Ponto p2){\r\n        ponto2 = p2;\r\n    }\r\n    \r\n    public Ponto getPonto2 (){\r\n        return ponto2;\r\n    }\r\n    \r\n    public double getDistancia (){\r\n        double c1 =ponto2.getX() - ponto1.getX();\r\n        double c2 =ponto2.getY() - ponto1.getY();\r\n        double b1 = 0;\r\n        double b2 = 0;\r\n        b1 = Math.pow (c1,2);\r\n        b2 = Math.pow (c2,2); \r\n        double d = 0;\r\n        double j = 0;\r\n        j = b1 + b2;\r\n        d = Math.sqrt (j);\r\n        return d;\r\n    }\r\n    \r\n    public String toString (){\r\n    String res = "("+ponto1.getX()+","+ponto1.getY()+")";\r\n    res += "\\n("+ponto2.getX()+","+ponto2.getY()+")";\r\n    res += "\\nA distância entre os pontos é: " +getDistancia();\r\n    \r\n    return res;\r\n}\r\n\r\n \r\n}    \r\n        \r\n    \r\n    \r\n        \r\n    \r\n    \r\n        \r\n        \r\n    \r\n    \r\n    \r\n\r\n\r\n'),
(973, 463, 'Teclado', ' \r\n\r\nimport java.io.*;\r\n\r\n/** Classe que permite fazer leitura de dados do tecladeo */\r\n\r\npublic class Teclado\r\n{\r\n     private String s;\r\n     private InputStreamReader i = new InputStreamReader (System.in);\r\n     private BufferedReader d = new BufferedReader(i);\r\n\r\n     /**\r\n        Le um inteiro.\r\n        @return int\r\n     */\r\n     public int leInt ()\r\n     {   System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         int a = 0;\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser inteiro: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um inteiro, com mensagem.\r\n        @return int\r\n     */\r\n     public int leInt (String msg)\r\n     { \r\n         int a = 0;\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: "+e );\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser inteiro: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um double.\r\n        @return double\r\n     */\r\n     public double leDouble()\r\n     { \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         double a = 0;\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Double.parseDouble(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser numero: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um double, com mensagem.\r\n        @return double\r\n     */\r\n     public double leDouble(String msg)\r\n     {   double a = 0;\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Double.parseDouble(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser numero: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um string.\r\n        @return String\r\n     */\r\n     public String leString()\r\n     { \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         s = "";\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            \r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (s);\r\n     }\r\n\r\n     /**\r\n        Le um string. com mensagem.\r\n        @return String\r\n     */\r\n     public String leString(String msg)\r\n     {   s = "";\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n            s = d.readLine();\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (s);\r\n     }\r\n        \r\n    /**\r\n        Le um char.\r\n        @return char\r\n     */\r\n     public char leChar()\r\n     {  \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         s = "";\r\n         char c='' '';\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            c = s.charAt(0);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (c);\r\n     }\r\n          \r\n     /**\r\n        Le um char com mensagem.\r\n        @return char\r\n     */\r\n     public char leChar(String msg)\r\n     {   s = "";\r\n         char c='' '';\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            c = s.charAt(0);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (c);\r\n     }\r\n     \r\n     \r\n    \r\n    }\r\n\r\n'),
(974, 463, 'TestaReta', '\r\n/**\r\n * Write a description of class TestaReta here.\r\n * \r\n * @author (your name) \r\n * @version (a version number or a date)\r\n */\r\npublic class TestaReta{\r\n    public static void main (String args []){\r\n        Teclado t = new Teclado ();\r\n        char l= '' '';\r\n        while (l != ''s''){\r\n        int x =t.leInt ("Digite o valor de X do ponto 1");\r\n        int y =t.leInt ("Digite o valor de Y do ponto 1");\r\n        int x1 = t.leInt ("Digite o valor de X do ponto 2");\r\n        int y2 = t.leInt ("Digite o valor de Y do ponto 2");\r\n        Ponto p1 = new Ponto (x,y);\r\n        Ponto p2 = new Ponto (x1,y2);\r\n        Reta r1 = new Reta (p1 , p2);\r\n        System.out.println (r1);\r\n        l = t.leChar ("Digite alguma letra , s interrompe");}\r\n    }   \r\n\r\n}\r\n'),
(975, 464, 'NumerosPares', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\npublic class NumerosPares\r\n{\r\n  int n;\r\n  \r\n  public NumerosPares(int n ){\r\n    this.n = n;\r\n    }\r\n    public NumerosPares(){\r\n        n = 0;\r\n    }\r\n    public int getN(){\r\n        return n;\r\n    }\r\n    public void setN( int n_ ){\r\n        n = n_;\r\n    }\r\n    public String geraPares(){\r\n        String pares = "";\r\n        int i= 2;\r\n        while( i <= n){\r\n            if (i == 2){\r\n                pares = "2";\r\n                }\r\n            else{\r\n                pares = pares + ", " +i;\r\n            }\r\n            i = i + 2;\r\n        }\r\n        return pares;\r\n    }\r\n    public int somaNumeros(){\r\n        int soma = 0, i = 0;\r\n        while( i <= n){\r\n            soma = soma + i;\r\n                i = i + 1;\r\n            }\r\n        return soma;\r\n    }\r\n}\r\n'),
(976, 465, 'Desenho', '\r\n/**\r\n * Escreva a descrição da classe Desenho aqui.\r\n * \r\n * @author aluno\r\n * @version (número de versão ou data)\r\n */\r\npublic class Desenho\r\n{\r\n    private String simbolo = "";\r\n    \r\n    public Desenho (String simbolo) {\r\n        this.simbolo = simbolo;\r\n    }\r\n    \r\n    public void setSimbolo (String simbolo){\r\n        this.simbolo = simbolo;\r\n    }\r\n    \r\n    public String getSimbolo () {\r\n        return simbolo;\r\n    }\r\n    \r\n    public String desenhaLinha (int comp) {\r\n        String desenho = "";\r\n        for (int i = 1; i <= comp; i++)\r\n            desenho += simbolo; \r\n        return desenho;\r\n    }\r\n    \r\n    public String desenhaLinhaVazada (int comp) {\r\n        String desenho = "";\r\n        for (int i = 1; i <= comp; i++)\r\n            if (i==1 || i==comp)\r\n                desenho += simbolo;\r\n            else desenho += " "; \r\n        return desenho;\r\n    }\r\n    \r\n    public String desenhaTriangulo (int nroLinhas) {\r\n        String ret = "";\r\n        for (int i=1; i<=nroLinhas; i++) {\r\n            String str = desenhaLinha(i);\r\n            ret += str + "\\n";\r\n        }\r\n        return ret;\r\n    }\r\n    \r\n    public String desenhaQuadrado (int nroLinhas) {\r\n         String ret = "";\r\n         for (int i=1; i<=nroLinhas; i++) {\r\n                String str = desenhaLinha(nroLinhas);\r\n                ret += str + "\\n";\r\n         }\r\n        return ret;\r\n    }\r\n    \r\n    public String desenhaQuadradoVazado (int nroLinhas) {\r\n         String ret = "", str="";\r\n         for (int i=1; i<=nroLinhas; i++) {\r\n                if (i==1 || i== nroLinhas) \r\n                    str = desenhaLinha(nroLinhas);\r\n                else \r\n                    str = desenhaLinhaVazada(nroLinhas);\r\n                ret += str + "\\n";\r\n         }\r\n        return ret;\r\n    }\r\n    \r\n}\r\n'),
(977, 466, 'Tabuada', '\r\n/**\r\n * Escreva a descrição da classe Tabuada aqui.\r\n * \r\n * @author (seu nome) \r\n * @version (número de versão ou data)\r\n */\r\npublic class Tabuada\r\n{\r\n    // variáveis de instância - substitua o exemplo abaixo pelo seu próprio\r\n    private int numero;\r\n\r\n    /**\r\n     * COnstrutor para objetos da classe Tabuada\r\n     */\r\n    public Tabuada()\r\n    {\r\n        // inicializa variáveis de instância\r\n        numero = 0;\r\n    }\r\n    \r\n    public Tabuada(int numero)\r\n    {\r\n        // inicializa variáveis de instância\r\n        this.numero = numero;\r\n    }\r\n    \r\n    public void setNumero (int numero){\r\n         this.numero = numero;\r\n    }\r\n    \r\n    public int getNumero (){\r\n        return numero;\r\n    }\r\n\r\n    public String calculaTabuada (){\r\n        String ret = "";\r\n        for (int i=1; i<=10; i++) {\r\n            ret += numero + " x " + i + " = "+(numero*i)+"\\n";\r\n        }\r\n        return ret;\r\n    }\r\n}\r\n'),
(978, 466, 'Teclado', ' \r\n\r\nimport java.io.*;\r\n\r\n/** Classe que permite fazer leitura de dados do tecladeo */\r\n\r\npublic class Teclado\r\n{\r\n     private String s;\r\n     private InputStreamReader i = new InputStreamReader (System.in);\r\n     private BufferedReader d = new BufferedReader(i);\r\n\r\n     /**\r\n        Le um inteiro.\r\n        @return int\r\n     */\r\n     public int leInt ()\r\n     {   System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         int a = 0;\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser inteiro: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um inteiro, com mensagem.\r\n        @return int\r\n     */\r\n     public int leInt (String msg)\r\n     { \r\n         int a = 0;\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: "+e );\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser inteiro: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um double.\r\n        @return double\r\n     */\r\n     public double leDouble()\r\n     { \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         double a = 0;\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Double.parseDouble(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n   