(990, 472, 'SocioAtleta', 'public class SocioAtleta extends Socio {\r\n\r\n    private String categoria;\r\n\r\n    public SocioAtleta() {\r\n        super();\r\n    }\r\n\r\n    public SocioAtleta(int numero, int idade, String nome) {\r\n        super(numero, idade, nome);\r\n        this.atualizaCategoria();\r\n    }\r\n\r\n    @Override\r\n    public void setIdade(int idade) {\r\n        super.setIdade(idade);\r\n        this.atualizaCategoria();\r\n    }\r\n\r\n    private void atualizaCategoria() {\r\n\r\n        if (this.getIdade() <= 10) {\r\n            this.categoria = "Mirim";\r\n        } else if (this.getIdade() <= 15) {\r\n            this.categoria = "Infantil";\r\n        } else if (this.getIdade() <= 20) {\r\n            this.categoria = "Juvenil";\r\n        } else if (this.getIdade() <= 40) {\r\n            this.categoria = "Adulto";\r\n        } else {\r\n            this.categoria = "Master";\r\n        }\r\n    }\r\n\r\n    @Override\r\n    public String toString() {\r\n        return super.toString() + ", " + categoria;\r\n    }\r\n\r\n}\r\n'),
(991, 472, 'Socio', 'public class Socio {\r\n\r\n    private int numero;\r\n    private int idade;\r\n    private String nome;\r\n\r\n    public Socio() {\r\n        this.numero = 0;\r\n        this.idade = 0;\r\n        this.nome = "";\r\n    }\r\n\r\n    public Socio(int numero, int idade, String nome) {\r\n        this.numero = numero;\r\n        this.idade = idade;\r\n        this.nome = nome;\r\n    }\r\n\r\n    public int getNumero() {\r\n        return numero;\r\n    }\r\n\r\n    public void setNumero(int numero) {\r\n        this.numero = numero;\r\n    }\r\n\r\n    public int getIdade() {\r\n        return idade;\r\n    }\r\n\r\n    public void setIdade(int idade) {\r\n        this.idade = idade;\r\n    }\r\n\r\n    public String getNome() {\r\n        return nome;\r\n    }\r\n\r\n    public void setNome(String nome) {\r\n        this.nome = nome;\r\n    }\r\n\r\n    @Override\r\n    public String toString() {\r\n        return numero + ", " + idade + ", " + nome;\r\n    }\r\n\r\n}\r\n'),
(992, 473, 'SocioAtleta', 'public class SocioAtleta extends Socio {\r\n\r\n    private String categoria;\r\n\r\n    public SocioAtleta() {\r\n        super();\r\n        this.categoria = "Mirim";\r\n    }\r\n\r\n    public SocioAtleta(int numero, int idade, String nome) {\r\n        super(numero, idade, nome);\r\n        this.atualizaCategoria();\r\n    }\r\n\r\n    @Override\r\n    public void setIdade(int idade) {\r\n        super.setIdade(idade);\r\n        this.atualizaCategoria();\r\n    }\r\n\r\n    private void atualizaCategoria() {\r\n\r\n        if (this.getIdade() <= 10) {\r\n            this.categoria = "Mirim";\r\n        } else if (this.getIdade() <= 15) {\r\n            this.categoria = "Infantil";\r\n        } else if (this.getIdade() <= 20) {\r\n            this.categoria = "Juvenil";\r\n        } else if (this.getIdade() <= 40) {\r\n            this.categoria = "Adulto";\r\n        } else {\r\n            this.categoria = "Master";\r\n        }\r\n    }\r\n\r\n    @Override\r\n    public String toString() {\r\n        return super.toString() + ", " + categoria;\r\n    }\r\n\r\n}\r\n'),
(993, 473, 'Socio', 'public class Socio {\r\n\r\n    private int numero;\r\n    private int idade;\r\n    private String nome;\r\n\r\n    public Socio() {\r\n        this.numero = 0;\r\n        this.idade = 0;\r\n        this.nome = "";\r\n    }\r\n\r\n    public Socio(int numero, int idade, String nome) {\r\n        this.numero = numero;\r\n        this.idade = idade;\r\n        this.nome = nome;\r\n    }\r\n\r\n    public int getNumero() {\r\n        return numero;\r\n    }\r\n\r\n    public void setNumero(int numero) {\r\n        this.numero = numero;\r\n    }\r\n\r\n    public int getIdade() {\r\n        return idade;\r\n    }\r\n\r\n    public void setIdade(int idade) {\r\n        this.idade = idade;\r\n    }\r\n\r\n    public String getNome() {\r\n        return nome;\r\n    }\r\n\r\n    public void setNome(String nome) {\r\n        this.nome = nome;\r\n    }\r\n\r\n    @Override\r\n    public String toString() {\r\n        return numero + ", " + idade + ", " + nome;\r\n    }\r\n\r\n}\r\n'),
(994, 474, 'NumerosPares', '/* package qualquer; // Não coloque nome no package */\r\n\r\nimport java.util.*;\r\nimport java.lang.*;\r\nimport java.io.*;\r\n\r\npublic class NumerosPares\r\n{\r\n  int n;\r\n  \r\n  public NumerosPares(int n ){\r\n    this.n = n;\r\n    }\r\n    public NumerosPares(){\r\n        n = 0;\r\n    }\r\n    public int getN(){\r\n        return n;\r\n    }\r\n    public void setN( int n_ ){\r\n        n = n_;\r\n    }\r\n    public String geraPares(){\r\n        String pares = "";\r\n        int i= 2;\r\n        while( i <= n){\r\n            if (i == 2){\r\n                pares = "2";\r\n                }\r\n            else{\r\n                pares = pares + ", " +i;\r\n            }\r\n            i = i + 2;\r\n        }\r\n        return pares;\r\n    }\r\n    public int somaNumeros(){\r\n        int soma = 0, i = 0;\r\n        while( i <= n){\r\n            soma = soma + i;\r\n                i = i + 1;\r\n            }\r\n        return soma;\r\n    }\r\n}\r\n'),
(995, 475, 'Desenho', '\r\n/**\r\n * Escreva a descrição da classe Desenho aqui.\r\n * \r\n * @author aluno\r\n * @version (número de versão ou data)\r\n */\r\npublic class Desenho\r\n{\r\n    private String simbolo = "";\r\n    \r\n    public Desenho (String simbolo) {\r\n        this.simbolo = simbolo;\r\n    }\r\n    \r\n    public void setSimbolo (String simbolo){\r\n        this.simbolo = simbolo;\r\n    }\r\n    \r\n    public String getSimbolo () {\r\n        return simbolo;\r\n    }\r\n    \r\n    public String desenhaLinha (int comp) {\r\n        String desenho = "";\r\n        for (int i = 1; i <= comp; i++)\r\n            desenho += simbolo; \r\n        return desenho;\r\n    }\r\n    \r\n    public String desenhaLinhaVazada (int comp) {\r\n        String desenho = "";\r\n        for (int i = 1; i <= comp; i++)\r\n            if (i==1 || i==comp)\r\n                desenho += simbolo;\r\n            else desenho += " "; \r\n        return desenho;\r\n    }\r\n    \r\n    public String desenhaTriangulo (int nroLinhas) {\r\n        String ret = "";\r\n        for (int i=1; i<=nroLinhas; i++) {\r\n            String str = desenhaLinha(i);\r\n            ret += str + "\\n";\r\n        }\r\n        return ret;\r\n    }\r\n    \r\n    public String desenhaQuadrado (int nroLinhas) {\r\n         String ret = "";\r\n         for (int i=1; i<=nroLinhas; i++) {\r\n                String str = desenhaLinha(nroLinhas);\r\n                ret += str + "\\n";\r\n         }\r\n        return ret;\r\n    }\r\n    \r\n    public String desenhaQuadradoVazado (int nroLinhas) {\r\n         String ret = "", str="";\r\n         for (int i=1; i<=nroLinhas; i++) {\r\n                if (i==1 || i== nroLinhas) \r\n                    str = desenhaLinha(nroLinhas);\r\n                else \r\n                    str = desenhaLinhaVazada(nroLinhas);\r\n                ret += str + "\\n";\r\n         }\r\n        return ret;\r\n    }\r\n    \r\n}\r\n'),
(996, 476, 'Tabuada', '\r\n/**\r\n * Escreva a descrição da classe Tabuada aqui.\r\n * \r\n * @author (seu nome) \r\n * @version (número de versão ou data)\r\n */\r\npublic class Tabuada\r\n{\r\n    // variáveis de instância - substitua o exemplo abaixo pelo seu próprio\r\n    private int numero;\r\n\r\n    /**\r\n     * COnstrutor para objetos da classe Tabuada\r\n     */\r\n    public Tabuada()\r\n    {\r\n        // inicializa variáveis de instância\r\n        numero = 0;\r\n    }\r\n    \r\n    public Tabuada(int numero)\r\n    {\r\n        // inicializa variáveis de instância\r\n        this.numero = numero;\r\n    }\r\n    \r\n    public void setNumero (int numero){\r\n         this.numero = numero;\r\n    }\r\n    \r\n    public int getNumero (){\r\n        return numero;\r\n    }\r\n\r\n    public String calculaTabuada (){\r\n        String ret = "";\r\n        for (int i=1; i<=10; i++) {\r\n            ret += numero + " x " + i + " = "+(numero*i)+"\\n";\r\n        }\r\n        return ret;\r\n    }\r\n}\r\n'),
(997, 476, 'Teclado', ' \r\n\r\nimport java.io.*;\r\n\r\n/** Classe que permite fazer leitura de dados do tecladeo */\r\n\r\npublic class Teclado\r\n{\r\n     private String s;\r\n     private InputStreamReader i = new InputStreamReader (System.in);\r\n     private BufferedReader d = new BufferedReader(i);\r\n\r\n     /**\r\n        Le um inteiro.\r\n        @return int\r\n     */\r\n     public int leInt ()\r\n     {   System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         int a = 0;\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser inteiro: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um inteiro, com mensagem.\r\n        @return int\r\n     */\r\n     public int leInt (String msg)\r\n     { \r\n         int a = 0;\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Integer.parseInt(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: "+e );\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser inteiro: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um double.\r\n        @return double\r\n     */\r\n     public double leDouble()\r\n     { \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         double a = 0;\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Double.parseDouble(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser numero: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um double, com mensagem.\r\n        @return double\r\n     */\r\n     public double leDouble(String msg)\r\n     {   double a = 0;\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n             s = d.readLine();\r\n             a = Double.parseDouble(s);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n             System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         catch (NumberFormatException e)\r\n         {\r\n             System.out.println ("o valor digitado deve ser numero: "+e );\r\n         }\r\n         return (a);\r\n     }\r\n\r\n     /**\r\n        Le um string.\r\n        @return String\r\n     */\r\n     public String leString()\r\n     { \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         s = "";\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            \r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (s);\r\n     }\r\n\r\n     /**\r\n        Le um string. com mensagem.\r\n        @return String\r\n     */\r\n     public String leString(String msg)\r\n     {   s = "";\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n            s = d.readLine();\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (s);\r\n     }\r\n        \r\n    /**\r\n        Le um char.\r\n        @return char\r\n     */\r\n     public char leChar()\r\n     {  \r\n         System.out.print(''\\b'');  //para evitar o bug do BlueJ\r\n         s = "";\r\n         char c='' '';\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            c = s.charAt(0);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (c);\r\n     }\r\n          \r\n     /**\r\n        Le um char com mensagem.\r\n        @return char\r\n     */\r\n     public char leChar(String msg)\r\n     {   s = "";\r\n         char c='' '';\r\n         System.out.println(msg);\r\n         try\r\n         {\r\n            s = d.readLine();\r\n            c = s.charAt(0);\r\n         }\r\n         catch (IOException e)\r\n         {\r\n            System.out.println ("Erro de I/O: " + e);\r\n         }\r\n         return (c);\r\n     }\r\n     \r\n     \r\n    \r\n    }\r\n\r\n\r\n'),
(998, 476, 'TestaTabuada', '\r\npublic class TestaTabuada\r\n{\r\n    public static void main (String args[]){\r\n        Teclado teclado = new Teclado();\r\n        int num = teclado.leInt("Digite um numero ou -1 para sair:");\r\n        while (num != -1){\r\n            Tabuada t = new Tabuada (num);\r\n            System.out.println (t.calculaTabuada());\r\n            num = teclado.leInt("Digite um numero ou -1 para sair:");\r\n            \r\n        }\r\n    }\r\n}\r\n'),
